(window.SB_FULLC=window.SB_FULLC||{}).hy={c:`[{"w":"hydrangea","d":"A leafy garden shrub known for big rounded clusters of pink, blue, or white flowers.","s":"Grandma's backyard was lined with hydrangea bushes whose enormous blue flower clusters swayed gently in the summer breeze.","p":"hy-DRAYN-juh","o":"English","y":7,"bp":46,"m":"hydrangia","nt":"Open","ps":"noun","t":["botany","flowers"]},{"w":"hyena","d":"a doglike carnivore of Africa","s":"The spotted hyena let out its eerie, laughing call as it prowled the moonlit savanna.","p":"h-ay-EE-n-uh","o":"French","y":6,"bp":47,"m":"hyeena","nt":"Open","ps":"noun","t":["animals","ofrench"]},{"w":"hypotenuse","d":"the side of a right triangle opposite the right angle","s":"To find the length of the hypotenuse, the student applied the Pythagorean theorem to the right triangle.","p":"hy-POT-uh-noos","o":"English","y":7,"bp":48,"m":"hypoteneuse","nt":"Open","ps":"noun","t":["numbers"]},{"w":"hydraulic","d":"is employing water or other liquids in motion","s":"The engineering students marveled at how the hydraulic lift at the auto shop could raise an entire vehicle effortlessly using only the power of pressurized fluid flowing through a compact network of metal tubes.","p":"h-ay-d-r-AW-l-ih-k","o":"English","y":3,"bp":64,"m":"hydralic","nt":"Advanced","ps":"adjective","t":[]},{"w":"hydrolysis","d":"is chemical decomposition by reacting with water","s":"During hydrolysis, the complex starch molecule breaks apart when it reacts with water.","p":"h-ay-d-r-AH-l-uh-s-uh-s","o":"Greek","y":6,"bp":69,"m":"hydrolisis","nt":"Advanced","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypothesis","d":"a proposition set forth to explain some occurrence","s":"A scientific hypothesis that survives experimental testing becomes a scientific theory.","p":"h-ay-p-AH-th-uh-s-uh-s","o":"English","y":3,"bp":100,"m":"hypothisis","nt":"Advanced | North South Finals","ps":"noun","t":[]},{"w":"hysterical","d":"overcome by wild, uncontrollable feeling such as fear or excitement; informally, also extremely funny","s":"The crowd grew hysterical with excitement when the band finally walked onto the stage.","p":"h-ih-s-t-EH-r-ih-k-uh-l","o":"Latin","y":3,"bp":70,"m":"hysterical (histerical)","nt":"Advanced","ps":"adjective","t":["olatin"]},{"w":"hyacinth","d":"a red transparent variety of zircon used as a gemstone","s":"The jeweler set a polished hyacinth into the golden ring, its reddish glow catching every light in the shop.","p":"h-AY-uh-s-ih-n-th","o":"Latin","y":4,"bp":52,"m":"hyacynth","nt":"Junior","ps":"noun","t":["minerals","olatin"]},{"w":"hybrid","d":"the offspring of two different breeds or species","s":"The vice-presidency is a hybrid of administrative and legislative offices.","p":"h-AY-b-r-uh-d","o":"English","y":1,"bp":90,"m":"hybred","nt":"Junior | North South Finals","ps":"noun","t":[]},{"w":"hygiene","d":"the science that deals with preservation of health","s":"The school nurse visited every classroom to explain why proper hygiene, including washing hands thoroughly before eating and after using the restroom, was essential for preventing the spread of germs and illness.","p":"h-AY-j-ee-n","o":"French","y":4,"bp":50,"m":"hygene","nt":"Junior","ps":"noun","t":["eponyms","ofrench","epfrench"]},{"w":"hyperbole","d":"is obvious exaggeration","s":"Saying you have a million hours of homework is a classic hyperbole that most students use every week.","p":"h-ay-p-UR-b-uh-l-ee","o":"Latin","y":6,"bp":53,"m":"hyperboly","nt":"Junior","ps":"noun","t":["olatin"]},{"w":"hyphen","d":"a short line used to connect parts of compound word","s":"Hyphenate these words and names.","p":"h-AY-f-uh-n","o":"English","y":4,"bp":45,"m":"hyphin","nt":"Junior","ps":"noun","t":["wordwords"]},{"w":"hypocrisy","d":"is pretending to something that one doesn't believe","s":"The politician's hypocrisy was exposed when reporters discovered he had broken the very law he championed.","p":"h-ih-p-AH-k-r-uh-s-ee","o":"French","y":3,"bp":53,"m":"hypocrasy","nt":"Junior","ps":"noun","t":["ofrench"]},{"w":"hypocaust","d":"a central heating system of an ancient Roman building consisting of an underground furnace and a series of tile flues for distribution of the heat.","s":"The Roman bathhouse was kept warm by a hypocaust, which circulated hot air beneath the tiled floors.","p":"HY-poh-kawst","o":"Latin","y":7,"bp":64,"m":"hypocost","sy":"hy.poh.kawst","ps":"noun","t":["buildings","ancient","olatin"]},{"w":"hydra","d":"(Greek mythology) monster with nine heads; when struck off each head was replaced by two new ones","s":"Hydra was slain by Hercules.","p":"HEYE-druh","o":"Latin","y":5,"bp":81,"m":"hidra","sy":"hhay.drah","nt":"Primary | North South Finals","ps":"noun","t":["myth","eponyms","olatin","eplatin"]},{"w":"hypnotic","d":"a drug that induces sleep","s":"The doctor prescribed a mild hypnotic to help the patient sleep before the major surgery.","p":"hih-PNAH-tihk","o":"French","y":3,"bp":40,"m":"hypnodic","sy":"hyp.not.ic","nt":"Primary","ps":"noun","t":["pharmacy","ofrench"]},{"w":"hyrax","d":"any of several small ungulate mammals of Africa and Asia with rodent-like incisors and feet with hooflike toes","s":"Perched on a sun-warmed boulder in Kenya, the hyrax looked like a large guinea pig but was actually a distant relative of the elephant.","p":"HY-raks","o":"Greek","y":5,"bp":28,"sy":"hy.rax","nt":"Open","ps":"noun","t":["animals","ogreek"]},{"w":"hydroponic","d":"of or relating to aquiculture","s":"The school's hydroponic garden grew crisp lettuce year-round inside the gymnasium using only water and special nutrients.","p":"heye-druh-PAH-nihk","o":"Greek","y":5,"bp":35,"m":"hydraoponic","sy":"hy.dro.pon.ic","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"hydrophobia","d":"a symptom of rabies in humans consisting of an aversion to swallowing liquids","s":"The doctor explained that hydrophobia in the patient was an alarming sign that the rabies infection had progressed severely.","p":"heye-druh-FOH-bee-uh","o":"Latin","y":8,"bp":37,"sy":"heye.druh.foh.bee.uh","nt":"Open","ps":"noun","t":["disease","olatin"]},{"w":"hypochondria","d":"chronic and abnormal anxiety about imaginary symptoms and ailments","s":"Whenever Marcus read about a new disease online, his hypochondria convinced him he had every symptom listed on the page.","p":"heye-puh-KAH-ndree-uh","o":"Latin","y":9,"bp":38,"m":"hypocondria","sy":"hy.po.chon.dri.a","nt":"Open","ps":"noun","t":["disease","emotions","olatin"]},{"w":"hydrant","d":"a faucet for drawing water from a pipe or cask","s":"The firefighters quickly connected their hose to the nearest hydrant and had water flowing within seconds.","p":"HEYE-druhnt","o":"Greek","y":4,"bp":30,"m":"hydrent","sy":"hhay.drah.nt","nt":"Open","ps":"noun","t":["tools","household","ogreek"]},{"w":"hymnal","d":"a songbook containing a collection of hymns","s":"Each member of the congregation received a worn hymnal and flipped to page forty-two for the opening song.","p":"HIH-mnuhl","o":"Greek","y":4,"bp":61,"m":"himnal","sy":"hhih.mnah.l","nt":"Advanced","ps":"noun","t":["religion","ogreek"]},{"w":"hydrargyrum","d":"a heavy silvery toxic univalent and bivalent metallic element; the only metal that is liquid at ordinary temperatures","s":"The old thermometer contained hydrargyrum, the Latin name for mercury, which is the only metal that remains liquid at room temperature.","p":"hy-DRAR-jih-rum","o":"Greek","y":9,"bp":68,"sy":"hy.drar.jih.rum","nt":"Advanced","ps":"noun","t":["chemistry","colors","ogreek"]},{"w":"hypertrophy","d":"abnormal enlargement of a body part or organ","s":"The cardiologist warned that the patient's heart hypertrophy, caused by years of untreated high blood pressure, needed immediate treatment.","p":"HEYE-per-troh-fee","o":"Greek","y":5,"bp":70,"m":"hypertrofy","sy":"hy.per.tro.phy","nt":"Senior","ps":"noun","t":["body","disease","ogreek"]},{"w":"hypallage","d":"reversal of the syntactic relation of two words (as in 'her beauty's face')","s":"The poet employed hypallage when she wrote 'anxious clocks' to describe how nervously the characters watched time pass.","p":"hy-PAL-uh-jee","o":"Latin","y":9,"bp":68,"m":"hypallage (often mispronounced but spelled correctly)","sy":"hy.pal.la.ge","nt":"Senior","ps":"noun","t":["wordwords","olatin"]},{"w":"hyssop","d":"a fragrant European mint plant used in cooking, perfume, and remedies","s":"The ancient recipe called for a bundle of hyssop to be dipped in the mixture and used to anoint the doorframe.","p":"HIH-suhp","o":"Greek","y":6,"bp":63,"m":"hysop","sy":"hhih.sah.p","nt":"Senior","ps":"noun","t":["pharmacy","botany","farming","culinary","spices","time","ogreek"]},{"w":"hydrology","d":"the branch of geology that studies water on the earth and in the atmosphere: its distribution and uses and conservation","s":"Scientists who study hydrology monitor river levels, rainfall patterns, and groundwater supplies to predict future droughts and floods.","p":"heye-DRAH-luh-jee","o":"Greek","y":4,"bp":34,"m":"hydorology","sy":"heye.drah.luh.jee","nt":"Open","ps":"noun","t":["minerals","ecology","ogreek"]},{"w":"hyades","d":"(Greek mythology) 7 daughters of Atlas and half-sisters of the Pleiades; they nurtured the infant Dionysus and Zeus placed them among the stars as a reward","s":"According to Greek mythology, the Hyades were seven sorrowful sisters who wept so much for their lost brother that the gods placed them among the stars.","p":"HEYE-uh-deez","o":"Greek","y":6,"bp":30,"sy":"hhay.ah.diy.z","nt":"Open","ps":"noun","t":["astronomy","maps","myth","kinship","ogreek"]},{"w":"hydras","d":"(Greek mythology) monster with nine heads; when struck off each head was replaced by two new ones","p":"HEYE-druhz","o":"Greek","y":6,"bp":29,"m":"hydrae","sy":"hhay.drah.z","nt":"Open","ps":"noun","t":["myth","ogreek"]},{"w":"hyenas","d":"doglike nocturnal mammal of Africa and southern Asia that feeds chiefly on carrion","s":"The hyenas circled the carcass at the edge of the watering hole, their eerie calls echoing across the dark savanna.","p":"heye-EE-nuhz","o":"Greek","y":3,"bp":30,"m":"hyeenas","sy":"hhay.iy.nah.z","nt":"Open","ps":"noun","t":["animals","ecology","ogreek"]},{"w":"hygeia","d":"(Greek mythology) the goddess of health; daughter of Aesculapius and sister of Panacea","s":"The ancient Greeks prayed to Hygeia to keep their families free from disease and illness.","p":"heye-JAY-uh","o":"Greek","y":8,"bp":30,"m":"hygia","sy":"hhay.jhey.ah","nt":"Open","ps":"noun","t":["myth","kinship","ogreek"]},{"w":"hymen","d":"(Greek mythology) the god of marriage","s":"In Greek mythology, Hymen was invoked at wedding celebrations to bless the union of the bride and groom.","p":"HEYE-muhn","o":"Greek","y":4,"bp":28,"m":"himen","sy":"hhay.mah.n","nt":"Open","ps":"noun","t":["myth","kinship","ogreek"]},{"w":"hymn","d":"a song of praise (to God or to a saint or to a nation)","s":"They hymned their love of God.","p":"HIHM","o":"French","y":2,"bp":26,"m":"him","sy":"hhih.m","nt":"Open","ps":"noun","t":["music","religion","ofrench"]},{"w":"hymns","d":"a song of praise (to God or to a saint or to a nation)","p":"HIHMZ","o":"Greek","y":2,"bp":27,"m":"hims","sy":"hhih.mz","nt":"Open","ps":"noun","t":["nations","music","ogreek"]},{"w":"hype","d":"blatant or sensational promotion","s":"The hype surrounding the new video game made the line outside the store stretch around the block.","p":"HEYEP","y":3,"bp":22,"m":"hipe","sy":"hhay.p","nt":"Open","ps":"noun","t":[]},{"w":"hyped","d":"publicize in an exaggerated and often misleading manner","s":"The studio hyped the movie so much that audiences were disappointed when it finally came out.","p":"HEYEPT","y":2,"bp":23,"m":"hiped","sy":"hhay.pt","nt":"Open","ps":"verb","t":[]},{"w":"hypes","d":"blatant or sensational promotion","s":"Every season, the fashion industry hypes new trends that disappear just as quickly as they arrived.","p":"HEYEPS","o":"Greek","y":5,"bp":27,"m":"hipes","sy":"hhay.ps","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hyphae","d":"any of the threadlike filaments forming the mycelium of a fungus","s":"Under the microscope, the hyphae of the mold spread like a delicate web across the surface of the bread.","p":"HEYE-fee","o":"Greek","y":6,"bp":29,"m":"hyphee","sy":"hhay.fiy","nt":"Open","ps":"noun","t":["botany","ogreek"]},{"w":"hyping","d":"publicize in an exaggerated and often misleading manner","s":"The company kept hyping their new phone as the greatest invention of the century.","p":"HEYE-pihng","o":"Greek","y":4,"bp":29,"m":"hipeing","sy":"hhay.pih.ng","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hypo","d":"a compound used as a fixing agent in photographic developing","s":"The photographer dipped the print into the hypo solution to set the image permanently on the paper.","p":"HEYE-poh","o":"Greek","y":6,"bp":27,"m":"hipo","sy":"hhay.pow","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hyson","d":"a Chinese green tea with twisted leaves","s":"The tea merchant recommended a fine hyson from a small farm in the mountains of Zhejiang province.","p":"HEYE-suhn","o":"Chinese","y":5,"bp":24,"m":"hison","sy":"hhay.sah.n","nt":"Open","ps":"noun","t":["botany","oeastasia"]},{"w":"hyacinths","d":"a red transparent variety of zircon used as a gemstone","s":"The jeweler displayed a row of rare hyacinths whose deep red sparkle rivaled that of rubies.","p":"HEYE-uh-sihnths","o":"Greek","y":6,"bp":33,"m":"hyasynths","sy":"hhay.ah.sih.nths","nt":"Open","ps":"noun","t":["minerals","ogreek"]},{"w":"hybridize","d":"breed animals or plants using parents of different races and varieties","p":"HEYE-bruh-deyez","o":"Latin","y":7,"bp":33,"m":"hybridise","sy":"hhay.brah.day.z","nt":"Open","ps":"verb","t":["botany","animals","farming","olatin"]},{"w":"hybrids","d":"living things bred from two different kinds of plants or animals","p":"HEYE-bruhdz","o":"Latin","y":3,"bp":30,"m":"hybreds","sy":"hhay.brah.dz","nt":"Open","ps":"noun","t":["botany","wordwords","olatin"]},{"w":"hydrants","d":"a faucet for drawing water from a pipe or cask","s":"On the hottest day of summer, children danced gleefully around the opened hydrants spraying cool water.","p":"HEYE-druhnts","o":"Greek","y":5,"bp":30,"m":"hydrents","sy":"hhay.drah.nts","nt":"Open","ps":"noun","t":["tools","household","ogreek"]},{"w":"hydrate","d":"any compound that contains water of crystallization","s":"The bicyclists must be hydrated frequently.","p":"HEYE-drayt","o":"French","y":5,"bp":30,"m":"hydrait","sy":"hhay.drey.t","nt":"Open","ps":"noun","t":["chemistry","minerals","ofrench"]},{"w":"hydrated","d":"supply water or liquid to in order to maintain a healthy balance","s":"The bicyclists must be hydrated frequently.","p":"HEYE-dray-tuhd","o":"Greek","y":3,"bp":32,"m":"hydraded","sy":"hhay.drey.tah.d","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hydrates","d":"any compound that contains water of crystallization","p":"HEYE-drayts","o":"Greek","y":5,"bp":30,"m":"hydraits","sy":"hhay.drey.ts","nt":"Open","ps":"noun","t":["chemistry","minerals","ogreek"]},{"w":"hydration","d":"the process of combining with water; usually reversible","s":"The marathon coach reminded every runner that proper hydration before a race is just as important as training.","p":"heye-DRAY-shuhn","o":"French","y":4,"bp":33,"m":"hydrasion","sy":"hhay.drey.shah.n","nt":"Open","ps":"noun","t":["ofrench"]},{"w":"hydrazine","d":"a colorless fuming corrosive liquid; a powerful reducing agent; used chiefly in rocket fuels","s":"Scientists handled the hydrazine with extreme caution because its fumes are dangerously toxic even in small amounts.","p":"HEYE-druh-zeen","o":"Greek","y":7,"bp":33,"m":"hydrozine","sy":"hhay.drah.ziy.n","nt":"Open","ps":"noun","t":["vehicles","colors","ogreek"]},{"w":"hydride","d":"any binary compound formed by the union of hydrogen and other elements","s":"The chemistry lab experiment produced a metal hydride that released hydrogen gas when exposed to water.","p":"HEYE-dreyed","o":"Greek","y":6,"bp":30,"m":"hydried","sy":"hhay.dray.d","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrofoil","d":"a device consisting of a flat or curved piece (as a metal plate) so that its surface reacts to the water it is passing through","s":"The fins of a fish act as hydrofoils.","p":"HEYE-druh-foyl","o":"French","y":7,"bp":33,"m":"hydrofoyle","sy":"hhay.drah.foy.l","nt":"Open","ps":"noun","t":["tools","ofrench"]},{"w":"hydrogen","d":"a nonmetallic univalent element that is normally a colorless and odorless highly flammable diatomic gas; the simplest and lightest and most abundant element in the universe","s":"Hydrogen is the lightest element on the periodic table and makes up most of the universe's visible matter.","p":"HEYE-druh-juhn","o":"French","y":2,"bp":32,"m":"hydorgen","sy":"hhay.drah.jhah.n","nt":"Open","ps":"noun","t":["chemistry","astronomy","colors","ofrench"]},{"w":"hydrogens","d":"a nonmetallic univalent element that is normally a colorless and odorless highly flammable diatomic gas; the simplest and lightest and most abundant element in the universe","s":"The molecule contained two hydrogens bonded to a single oxygen atom, forming ordinary water.","p":"HEYE-druh-juhnz","o":"Greek","y":6,"bp":33,"m":"hydorgens","sy":"hhay.drah.jhah.nz","nt":"Open","ps":"noun","t":["chemistry","astronomy","colors","ogreek"]},{"w":"hydrolyze","d":"undergo hydrolysis; decompose by reacting with water","s":"Adding warm water caused the starch to hydrolyze rapidly into smaller sugar molecules.","p":"HEYE-druh-leyez","o":"Greek","y":8,"bp":33,"m":"hydrolise","sy":"hhay.drah.lay.z","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hydrous","d":"containing combined water (especially water of crystallization as in a hydrate)","s":"The geologist identified the mineral as hydrous because it contained water locked within its crystal structure.","p":"HEYE-druhs","o":"Greek","y":8,"bp":30,"m":"hyderous","sy":"hhay.drah.s","nt":"Open","ps":"adjective","t":["chemistry","minerals","ogreek"]},{"w":"hydroxide","d":"a compound of an oxide with water","s":"Sodium hydroxide, commonly called lye, is used in soap making but must be handled with protective gloves.","p":"heye-DRAH-kseyed","o":"Greek","y":6,"bp":33,"m":"hydroxcide","sy":"hhay.draa.ksay.d","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydroxy","d":"being or containing a hydroxyl group","s":"The chemist noted that the hydroxy group in the molecule made it much more soluble in water.","p":"heye-DRAW-ksee","o":"Greek","y":4,"bp":31,"m":"hidroxy","sy":"hhay.drao.ksiy","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"hygienist","d":"a medical specialist in hygiene","s":"The dental hygienist carefully cleaned and polished each tooth before the dentist performed the examination.","p":"heye-GEE-nihst","o":"French","y":5,"bp":33,"m":"hygienest","sy":"hhay.giy.nih.st","nt":"Open","ps":"noun","t":["body","ofrench"]},{"w":"hymeneal","d":"a wedding hymn","s":"The chorus performed a beautiful hymeneal as the bride and groom walked hand in hand beneath a canopy of white roses during their elegant outdoor wedding ceremony.","p":"hih-muh-NEE-uhl","o":"Greek","y":7,"bp":33,"m":"hymenial","nt":"Open","ps":"noun","t":["religion","kinship","eponyms","ogreek","epgreek"]},{"w":"hymnals","d":"a songbook containing a collection of hymns","s":"The congregation reached into the wooden pew racks and pulled out worn hymnals to follow along with the choir.","p":"HIH-mnuhlz","o":"Greek","y":5,"bp":30,"m":"hynmals","sy":"hhih.mnah.lz","nt":"Open","ps":"noun","t":["religion","ogreek"]},{"w":"hyperbola","d":"an open curve formed by a plane that cuts the base of a right circular cone","s":"The math teacher drew a perfect hyperbola on the whiteboard to show how the two curved branches open outward.","p":"heye-PUR-buh-luh","o":"Greek","y":7,"bp":34,"m":"hyperbolla","sy":"hhay.per.bah.lah","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hyperopia","d":"abnormal condition in which vision for distant objects is better than for near objects","s":"Her optometrist diagnosed her with hyperopia, explaining why she could read the distant scoreboard but not her textbook.","p":"heye-per-OH-pee-ah","o":"Greek","y":8,"bp":36,"m":"hyperopeia","sy":"hhay.per.ow.piy.ah","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hyphenate","d":"divide or connect with a hyphen","s":"Hyphenate these words and names.","p":"HEYE-fuh-nayt","o":"Greek","y":7,"bp":33,"m":"hyphanate","sy":"hhay.fah.ney.t","nt":"Open","ps":"verb","t":["wordwords","ogreek"]},{"w":"hypnosis","d":"a state that resembles sleep but that is induced by suggestion","s":"Under hypnosis, the patient recalled vivid details from her childhood that she had long forgotten.","p":"hih-PNOH-suhs","o":"Greek","y":3,"bp":32,"m":"hypnosos","sy":"hhih.pnow.sah.s","nt":"Open","ps":"noun","t":["eponyms","ogreek","epgreek"]},{"w":"hypnotics","d":"a drug that induces sleep","s":"The physician prescribed mild hypnotics to help the patient fall asleep, warning that they could cause drowsiness the next morning.","p":"hih-PNAH-tihks","o":"Greek","y":6,"bp":33,"sy":"hhih.pnaa.tih.ks","nt":"Open","ps":"noun","t":["pharmacy","ogreek"]},{"w":"hypnotism","d":"the act of inducing hypnosis","s":"The magician used hypnotism to make a volunteer from the audience cluck like a chicken.","p":"HIH-pnuh-tih-zuhm","o":"Greek","y":5,"bp":34,"m":"hypnotisim","sy":"hhih.pnah.tih.zah.m","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypnotize","d":"induce hypnosis in","s":"The therapist was able to hypnotize the patient and help her overcome her fear of heights.","p":"HIH-pnuh-teyez","o":"Greek","y":6,"bp":33,"m":"hypnotise","sy":"hhih.pnah.tay.z","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hypocrite","d":"a person who professes beliefs and opinions that he or she does not hold in order to conceal his or her real feelings or motives","s":"He called himself an environmentalist, but drove a gas-guzzling truck everywhere, making him a complete hypocrite.","p":"HIH-puh-kriht","o":"French","y":5,"bp":33,"m":"hypocrit","sy":"hhih.pah.krih.t","nt":"Open","ps":"noun","t":["logic","ofrench"]},{"w":"hypoxia","d":"oxygen deficiency causing a very strong drive to correct the deficiency","s":"Climbers ascending Mount Everest risk hypoxia if they ascend too quickly without supplemental oxygen.","p":"heye-PAH-ksee-uh","o":"Greek","y":6,"bp":33,"m":"hypoxea","sy":"hhay.paa.ksiy.ah","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hyraxes","d":"any of several small ungulate mammals of Africa and Asia with rodent-like incisors and feet with hooflike toes","s":"Despite their small size and furry appearance, hyraxes are surprisingly close relatives of elephants.","p":"HEYE-ra-ksuhz","o":"Greek","y":7,"bp":31,"m":"hiraxes","sy":"hhay.rae.ksah.z","nt":"Open","ps":"noun","t":["animals","ogreek"]},{"w":"hysteria","d":"wild, uncontrollable fear or excitement, often spreading through a crowd","s":"Mass hysteria broke out in the theater when someone yelled that there was a fire, even though there was none.","p":"hih-STEH-ree-uh","o":"Latin","y":5,"bp":33,"m":"histeria","sy":"hhih.steh.riy.ah","nt":"Open","ps":"noun","t":["olatin"]},{"w":"hysteric","d":"a person suffering from hysteria","s":"During hysterical conditions various functions of the human body are disordered.","p":"hih-STEH-rihk","o":"Latin","y":5,"bp":32,"m":"histeric","sy":"hhih.steh.rih.k","nt":"Open","ps":"noun","t":["olatin"]},{"w":"hydraulics","d":"study of the mechanics of fluids","s":"The engineer used hydraulics to design a braking system powerful enough to stop a loaded freight train.","p":"heye-DRAW-lihks","o":"Greek","y":5,"bp":34,"m":"hydralics","sy":"hhay.drao.lih.ks","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hydrocarbon","d":"an organic compound containing only carbon and hydrogen","s":"Methane is the simplest hydrocarbon, consisting of just one carbon atom bonded to four hydrogen atoms.","p":"heye-droh-KAH-rbuhn","o":"Latin","y":5,"bp":36,"m":"hydocarbon","sy":"hhay.drow.kaa.rbah.n","nt":"Open","ps":"noun","t":["chemistry","olatin"]},{"w":"hydrocarbons","d":"an organic compound containing only carbon and hydrogen","s":"Burning hydrocarbons like gasoline releases carbon dioxide into the atmosphere and contributes to climate change.","p":"heye-droh-KAH-rbuhnz","o":"Greek","y":5,"bp":37,"m":"hydocarbons","sy":"hhay.drow.kaa.rbah.nz","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrogenate","d":"combine or treat with or expose to hydrogen; add hydrogen to the molecule of (an unsaturated organic compound)","s":"Food scientists can hydrogenate vegetable oil to make it solid at room temperature for use in baking.","p":"HEYE-druh-juh-nayt","o":"Greek","y":9,"bp":36,"m":"hydrogenait","sy":"hhay.drah.jhah.ney.t","nt":"Open","ps":"verb","t":["chemistry","ogreek"]},{"w":"hydrogenated","d":"combine or treat with or expose to hydrogen; add hydrogen to the molecule of (an unsaturated organic compound)","s":"The nutrition label warned that the crackers contained hydrogenated oils, which are linked to heart disease.","p":"HEYE-druh-juh-nay-tihd","o":"Greek","y":6,"bp":38,"m":"hydrogeneted","sy":"hhay.drah.jhah.ney.tih.d","nt":"Open","ps":"verb","t":["chemistry","ogreek"]},{"w":"hydrogenates","d":"combine or treat with or expose to hydrogen; add hydrogen to the molecule of (an unsaturated organic compound)","s":"The factory hydrogenates large batches of vegetable fat every day to produce margarine for grocery stores.","p":"HEYE-druh-juh-nayts","o":"Greek","y":8,"bp":37,"m":"hydrogenats","sy":"hhay.drah.jhah.ney.ts","nt":"Open","ps":"verb","t":["chemistry","ogreek"]},{"w":"hydrographic","d":"of or relating to the science of hydrography","s":"The navy relied on detailed hydrographic charts to safely navigate the shallow harbor channels.","p":"heye-druh-GRA-fihk","o":"Greek","y":5,"bp":37,"m":"hydrograffic","sy":"hhay.drah.grae.fih.k","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"hydrolyzed","d":"undergo hydrolysis; decompose by reacting with water","s":"The protein was hydrolyzed in the lab so that its amino acids could be studied individually.","p":"HEYE-druh-leyezd","o":"Greek","y":7,"bp":34,"m":"hydrolised","sy":"hhay.drah.lay.zd","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hydrolyzing","d":"undergo hydrolysis; decompose by reacting with water","s":"By hydrolyzing the starch molecules, the chemist broke them down into simple sugars.","p":"HEYE-druh-leye-zihng","o":"Greek","y":8,"bp":36,"m":"hydrolising","sy":"hhay.drah.lay.zih.ng","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hydrometer","d":"a measuring instrument for determining the specific gravity of a liquid or solid","s":"The brewer used a hydrometer to check the sugar content of the fermenting liquid before bottling.","p":"heye-DRAH-muh-ter","o":"Greek","y":6,"bp":35,"m":"hydrommeter","sy":"hhay.draa.mah.ter","nt":"Open","ps":"noun","t":["physics","tools","ogreek"]},{"w":"hydrophilic","d":"having a strong affinity for water; tending to dissolve in, mix with, or be wetted by water","s":"The hydrophilic gel absorbed water rapidly and swelled to many times its original size.","p":"heye-druh-FIH-lihk","o":"Greek","y":5,"bp":36,"m":"hydrophillic","sy":"hhay.drah.fih.lih.k","nt":"Open","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hydrotherapy","d":"the internal and external use of water in the treatment of disease","s":"After his knee surgery, the athlete used hydrotherapy sessions in the warm pool to regain his strength.","p":"heye-droh-THEH-ruh-pee","o":"Greek","y":6,"bp":38,"m":"hydrothearpy","sy":"hhay.drow.theh.rah.piy","nt":"Open","ps":"noun","t":["disease","ogreek"]},{"w":"hydroxides","d":"a compound of an oxide with water","s":"Sodium and potassium hydroxides are both highly caustic substances used in industrial cleaning products.","p":"heye-DRAH-kseyedz","o":"Greek","y":6,"bp":34,"m":"hydroxcides","sy":"hhay.draa.ksay.dz","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hygienists","d":"a medical specialist in hygiene","s":"The dental hygienists carefully cleaned each patient's teeth before the dentist performed the checkup.","p":"heye-GEE-nihsts","o":"Greek","y":6,"bp":34,"m":"hygienests","sy":"hhay.giy.nih.sts","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hygrometer","d":"measuring instrument for measuring the relative humidity of the atmosphere","s":"The museum curator checked the hygrometer daily to ensure the humidity stayed low enough to protect the ancient paintings.","p":"heye-GRAH-muh-ter","o":"French","y":6,"bp":35,"m":"higrometer","sy":"hhay.graa.mah.ter","nt":"Open","ps":"noun","t":["weather","music","tools","ofrench"]},{"w":"hyperactive","d":"more active than normal","s":"The hyperactive puppy raced around the living room, knocked over the laundry basket, chewed three shoes, and somehow still had enough energy to demand another game of fetch in the yard.","p":"heye-per-A-ktihv","o":"Greek","y":6,"bp":36,"m":"hyperaktive","sy":"hhay.per.ae.ktih.v","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"hyperbolic","d":"enlarged beyond truth or reasonableness","s":"When Dani claimed she had waited 'literally a million years' for the bus, her friend laughed and pointed out that the hyperbolic statement made the ten-minute wait sound slightly more dramatic than it truly was.","p":"heye-per-BAH-lihk","o":"French","y":4,"bp":35,"m":"hyperbollic","sy":"hhay.per.baa.lih.k","nt":"Open","ps":"adjective","t":["logic","ofrench"]},{"w":"hyperborean","d":"(Greek mythology) one of a people that the ancient Greeks believed lived in a warm and sunny land north of the source of the north wind","s":"In the myth, the hyperborean was said to live in a paradise beyond the north wind where the sun always shone.","p":"heye-per-BAW-ree-uhn","o":"Greek","y":7,"bp":37,"m":"hyperborian","sy":"hhay.per.bao.riy.ah.n","nt":"Open","ps":"noun","t":["weather","myth","ancient","ogreek"]},{"w":"hypermarket","d":"a huge supermarket (usually built on the outskirts of a town)","s":"The new hypermarket on the edge of town sold everything from groceries to furniture under one enormous roof.","p":"HEYE-per-mah-rkiht","o":"Greek","y":6,"bp":36,"m":"hypermarkit","sy":"hhay.per.maa.rkih.t","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hyperplasia","d":"abnormal increase in number of cells","s":"The doctor explained that the patient's hyperplasia caused the tissue to thicken in an unusual way.","p":"heye-per-PLAY-zhah","o":"Greek","y":7,"bp":36,"m":"hyperplazia","sy":"hhay.per.pley.zhah","nt":"Open","ps":"noun","t":["body","disease","ogreek"]},{"w":"hypertension","d":"a common disorder in which blood pressure remains abnormally high (a reading of 140/90 mm Hg or greater)","s":"The doctor advised the patient to reduce salt intake and exercise regularly to manage his hypertension.","p":"heye-per-TEH-nshuhn","o":"Greek","y":4,"bp":37,"m":"hypertention","sy":"hhay.per.teh.nshah.n","nt":"Open","ps":"noun","t":["body","disease","ogreek"]},{"w":"hypertensive","d":"a person who has abnormally high blood pressure","s":"As a hypertensive, she monitored her blood pressure every morning and kept a detailed log for her physician.","p":"heye-per-TEH-nsihv","o":"Greek","y":7,"bp":37,"m":"hypertentive","sy":"hhay.per.teh.nsih.v","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hypertonic","d":"(of living tissue) in a state of abnormally high tension","p":"heye-per-TAH-nihk","o":"Greek","y":6,"bp":35,"m":"hypertonnic","sy":"hhay.per.taa.nih.k","nt":"Open","ps":"adjective","t":["body","ogreek"]},{"w":"hyphenated","d":"divide or connect with a hyphen","p":"HEYE-fuh-nay-tihd","o":"Greek","y":5,"bp":35,"m":"hyphanated","sy":"hhay.fah.ney.tih.d","nt":"Open","ps":"verb","t":["numbers","ogreek"]},{"w":"hyphenates","d":"divide or connect with a hyphen","p":"HEYE-fuh-nayts","o":"Greek","y":7,"bp":34,"m":"hyphanates","sy":"hhay.fah.ney.ts","nt":"Open","ps":"verb","t":["numbers","ogreek"]},{"w":"hyphenating","d":"divide or connect with a hyphen","p":"HEYE-fuh-nay-tihng","o":"Greek","y":7,"bp":36,"m":"hyphanating","sy":"hhay.fah.ney.tih.ng","nt":"Open","ps":"verb","t":["numbers","ogreek"]},{"w":"hyphenation","d":"division of a word especially at the end of a line on a page","s":"The editor checked the hyphenation of long words to make the printed page look clean and even.","p":"heye-fuh-NAY-shuhn","o":"Greek","y":7,"bp":36,"m":"hyphanation","sy":"hhay.fah.ney.shah.n","nt":"Open","ps":"noun","t":["wordwords","printing","ogreek"]},{"w":"hypnotists","d":"a person who induces hypnosis","s":"The two hypnotists on stage competed to see whose volunteer would fall into the deepest trance.","p":"HIH-pnuh-tihsts","o":"Greek","y":6,"bp":34,"m":"hypnotysts","sy":"hhih.pnah.tih.sts","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypnotized","d":"induce hypnosis in","s":"The performer hypnotized the volunteer so effectively that she believed she was standing on a beach in Hawaii.","p":"HIH-pnuh-teyezd","o":"Greek","y":5,"bp":34,"m":"hypnotised","sy":"hhih.pnah.tay.zd","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hypnotizes","d":"induce hypnosis in","s":"Everyone says the magician hypnotizes his audience with his smooth, commanding voice.","p":"HIH-pnuh-teye-zuhz","o":"Greek","y":6,"bp":35,"m":"hypnotises","sy":"hhih.pnah.tay.zah.z","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hypocrites","d":"a person who professes beliefs and opinions that he or she does not hold in order to conceal his or her real feelings or motives","s":"They called the politicians hypocrites because they voted against the very laws they had publicly championed.","p":"HIH-puh-krihts","o":"Greek","y":4,"bp":34,"m":"hypocrits","sy":"hhih.pah.krih.ts","nt":"Open","ps":"noun","t":["logic","ogreek"]},{"w":"hypocritical","d":"professing feelings or virtues one does not have","s":"It seemed hypocritical for the council member to campaign loudly for environmental protection while quietly driving one of the most fuel-inefficient vehicles registered in the entire county.","p":"hih-puh-KRIH-tih-kuhl","o":"Greek","y":4,"bp":38,"m":"hypocritacal","sy":"hhih.pah.krih.tih.kah.l","nt":"Open","ps":"adjective","t":["logic","ogreek"]},{"w":"hypodermic","d":"a syringe with a hollow needle used to give injections under the skin","s":"The school nurse carefully explained how a hypodermic needle works, showing students that the hollow tip passes just beneath the skin to deliver medicine quickly and directly into the bloodstream.","p":"heye-puh-DUR-mihk","o":"French","y":5,"bp":35,"m":"hypadermic","sy":"hhay.pah.der.mih.k","nt":"Open","ps":"noun","t":["body","ofrench"]},{"w":"hypoglycemia","d":"abnormally low blood sugar usually resulting from excessive insulin or a poor diet","s":"The athlete felt dizzy and shaky during practice, and her doctor later diagnosed her with hypoglycemia.","p":"heye-poh-gleye-SEE-mee-uh","o":"Greek","y":8,"bp":40,"m":"hypoglycaemia","sy":"hhay.pow.glay.siy.miy.ah","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hypoglycemic","d":"of or relating to hypoglycemia","s":"After skipping breakfast and lunch, the diabetic student began to feel dizzy and shaky because his hypoglycemic episode made it impossible for him to concentrate during the afternoon exam.","p":"heye-poh-gleye-SEE-mihk","o":"French","y":7,"bp":38,"m":"hypoglycaemic","sy":"hhay.pow.glay.siy.mih.k","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"hypotension","d":"abnormally low blood pressure","s":"After standing up too quickly, Marcus experienced a brief spell of hypotension that made the room spin.","p":"heye-poh-TEH-nshuhn","o":"Greek","y":5,"bp":36,"m":"hypotenshun","sy":"hhay.pow.teh.nshah.n","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hypothalamic","d":"of or relating to the hypothalamus","s":"The scientist studied hypothalamic activity to understand how the brain regulates body temperature.","p":"heye-poh-thuh-LA-mihk","o":"Greek","y":6,"bp":38,"m":"hypothalmic","sy":"hhay.pow.thah.lae.mih.k","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"hypothalamus","d":"a basal part of the diencephalon governing autonomic nervous system","s":"Your hypothalamus acts like a tiny thermostat inside your brain, helping to keep your body at the right temperature.","p":"heye-poh-THAH-luh-muhs","o":"Greek","y":5,"bp":38,"m":"hypothalmus","sy":"hhay.poh.thah.luh.muhs","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypothermia","d":"subnormal body temperature","s":"The hiker who fell into the icy river was rushed to the hospital suffering from severe hypothermia.","p":"heye-puh-THUR-mee-uh","o":"Greek","y":7,"bp":37,"m":"hypothermea","sy":"hhay.pah.ther.miy.ah","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypotheses","d":"a proposal intended to explain certain facts or observations","p":"heye-PAH-thuh-seez","o":"Greek","y":4,"bp":35,"m":"hypothesis's","sy":"hhay.paa.thah.siy.z","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypothesize","d":"to believe especially on uncertain or tentative grounds","p":"heye-PAH-thuh-seyez","o":"Greek","y":7,"bp":36,"sy":"hhay.paa.thah.say.z","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hypothesized","d":"to believe especially on uncertain or tentative grounds","p":"heye-PAH-thuh-seyezd","o":"Greek","y":5,"bp":37,"m":"hypothesised","sy":"hhay.paa.thah.say.zd","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hypothetical","d":"An imagined possibility or situation considered for the sake of argument, not a real one.","s":"Consider the following, just as a hypothetical.","p":"heye-puh-THEH-tuh-kuhl","o":"Greek","y":4,"bp":38,"m":"hypotheticle","sy":"hhay.pah.theh.tah.kah.l","nt":"Open","ps":"noun","t":["logic","ogreek"]},{"w":"hysterectomy","d":"surgical removal of the uterus","s":"After years of painful complications, the doctor recommended a hysterectomy as the most effective treatment.","p":"hih-ster-EH-ktuh-mee","o":"Greek","y":5,"bp":38,"m":"hysterectamy","sy":"hhih.ster.eh.ktah.miy","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hysterically","d":"in a hysterical manner","s":"She screamed hysterically when she heard the news.","p":"hih-STEH-rih-klee","o":"Greek","y":6,"bp":37,"m":"hystericly","sy":"hhih.steh.rih.kliy","nt":"Open","ps":"adverb","t":["ogreek"]},{"w":"hybridization","d":"(genetics) the act of mixing different species or varieties of animals or plants and thus to produce hybrids","s":"Through careful hybridization, the botanist created a rose that was both disease-resistant and strikingly fragrant.","p":"heye-bruh-duh-ZAY-shuhn","o":"Latin","y":5,"bp":39,"m":"hybridisation","sy":"hhay.brah.dah.zey.shah.n","nt":"Open","ps":"noun","t":["animals","botany","olatin"]},{"w":"hydrocephalic","d":"relating to or characterized by or evidencing hydrocephalus","s":"The doctor identified hydrocephalic symptoms in the infant and immediately ordered further neurological testing.","p":"heye-droh-seh-FAH-lihk","o":"Greek","y":9,"bp":39,"m":"hydrocefelic","sy":"heye.droh.seh.FAH.lihk","nt":"Open","ps":"adjective","t":["body","disease","ogreek"]},{"w":"hydrocephalus","d":"an abnormal condition in which cerebrospinal fluid collects in the ventricles of the brain; in infants it can cause abnormally rapid growth of the head and bulging fontanelles and a small face; in adults the symptoms are primarily neurological","s":"The newborn was diagnosed with hydrocephalus, and surgeons placed a shunt to drain excess fluid from his brain.","p":"heye-droh-SEH-fuh-luhs","o":"Greek","y":6,"bp":39,"m":"hydrocefalis","sy":"heye.droh.SEH.fuh.luhs","nt":"Open","ps":"noun","t":["body","disease","ogreek"]},{"w":"hydrocortisone","d":"an adrenal-cortex hormone (trade names Hydrocortone or Cortef) that is active in carbohydrate and protein metabolism","s":"The doctor prescribed a hydrocortisone cream to reduce the itching and redness of the allergic rash.","p":"heye-droh-KAW-rtuh-zohn","o":"Greek","y":8,"bp":40,"m":"hydrocortazone","sy":"heye.droh.KAW.rtuh.zohn","nt":"Open","ps":"noun","t":["pharmacy","body","ogreek"]},{"w":"hydroelectric","d":"of or relating to or used in the production of electricity by waterpower","s":"The massive hydroelectric dam harnessed the powerful rush of the river to generate enough electricity to light up every home and business in the surrounding region.","p":"heye-droh-ih-LEH-ktrihk","o":"Latin","y":5,"bp":39,"m":"hydroelctric","sy":"hhay.drow.ih.leh.ktrih.k","nt":"Open","ps":"adjective","t":["physics","olatin"]},{"w":"hydrogenating","d":"combine or treat with or expose to hydrogen; add hydrogen to the molecule of (an unsaturated organic compound)","s":"The food company was hydrogenating vegetable oils to make them solid at room temperature for use in baked goods.","p":"HEYE-druh-juh-nay-tihng","o":"Greek","y":9,"bp":39,"m":"hydrogenatiing","sy":"hhay.drah.jhah.ney.tih.ng","nt":"Open","ps":"verb","t":["chemistry","ogreek"]},{"w":"hydrogenation","d":"a chemical process that adds hydrogen atoms to an unsaturated oil","s":"Food producers use hydrogenation to keep fat from becoming rancid.","p":"heye-drah-juh-NAY-shuhn","o":"Greek","y":6,"bp":39,"m":"hydrogenasion","sy":"hhay.draa.jhah.ney.shah.n","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hyperactivity","d":"a condition characterized by excessive restlessness and movement","s":"The teacher noticed signs of hyperactivity in the student, who could rarely sit still for more than a few minutes.","p":"heye-per-a-KTIH-vih-tee","o":"Greek","y":5,"bp":40,"m":"hyperactivety","sy":"hhay.per.ae.ktih.vih.tiy","nt":"Open","ps":"noun","t":["behavior","disease","ogreek"]},{"w":"hypercritical","d":"inclined to judge too severely","s":"Hypercritical of colloquial speech.","p":"heye-per-KRIH-tih-kuhl","o":"Greek","y":7,"bp":39,"m":"hypercritcal","sy":"hhay.per.krih.tih.kah.l","nt":"Open","ps":"adjective","t":["character","ogreek"]},{"w":"hypersensitive","d":"having an allergy or peculiar or excessive susceptibility (especially to a specific factor)","s":"Because she was hypersensitive to certain food dyes, her parents carefully read every ingredient label before allowing her to eat packaged snacks at birthday parties.","p":"heye-per-SEH-nsih-tihv","o":"Greek","y":7,"bp":40,"m":"hypersensative","sy":"hhay.per.seh.nsih.tih.v","nt":"Open","ps":"adjective","t":["disease","ogreek"]},{"w":"hypersensitivity","d":"pathological sensitivity","s":"Her hypersensitivity to certain medications meant that doctors had to test every new prescription with extreme caution.","p":"heye-per-SEH-nsih-tih-vih-tee","o":"Greek","y":6,"bp":44,"m":"hypersensativity","sy":"hhay.per.seh.nsih.tih.vih.tiy","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypochondriac","d":"a patient with imaginary symptoms and ailments","s":"Every time he read about a new disease online, the hypochondriac convinced himself he had all the symptoms.","p":"heye-puh-KAH-ndree-ak","o":"Greek","y":7,"bp":39,"m":"hypocondriac","sy":"hhay.pah.kaa.ndriy.ae.k","nt":"Open","ps":"noun","t":["disease","ogreek"]},{"w":"hypothetically","d":"by hypothesis","s":"Hypothetically speaking, if you could travel back in time, which historical event would you most want to witness?","p":"heye-puh-THEH-tih-klee","o":"Greek","y":7,"bp":40,"m":"hypotheticly","sy":"hhay.pah.theh.tih.kliy","nt":"Open","ps":"adverb","t":["logic","ogreek"]},{"w":"hysterectomies","d":"surgical removal of the uterus","s":"The gynecologist explained that hysterectomies are sometimes recommended when other treatments for severe fibroids have failed.","p":"hih-ster-EH-ktuh-mee","o":"Greek","y":7,"bp":40,"m":"hysterectomys","sy":"hhih.ster.eh.ktah.miy","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hyaena","d":"doglike nocturnal mammal of Africa and southern Asia that feeds chiefly on carrion","s":"The hyaena let out its eerie laughing call as it prowled the moonlit savanna.","p":"hy-EE-nuh","o":"Greek","y":7,"bp":30,"m":"hyeana","sy":"hy.ae.na","nt":"Open","ps":"noun","t":["animals","ecology","ogreek"]},{"w":"hyalin","d":"a glassy translucent substance that occurs in hyaline cartilage or in certain skin conditions","s":"The doctor pointed to the hyalin coating visible in the cartilage sample under the microscope.","p":"HY-uh-lin","o":"Greek","y":8,"bp":30,"m":"hyaline","sy":"hy.a.lin","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hydnum","d":"type genus of Hydnaceae","s":"The botanist catalogued the hydnum specimens she collected from the forest floor.","p":"HID-num","o":"Greek","y":8,"bp":29,"m":"hydnam","sy":"hyd.num","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hydrae","d":"(Greek mythology) monster with nine heads; when struck off each head was replaced by two new ones","p":"HY-dree","o":"Greek","y":8,"bp":29,"m":"hydras","sy":"hy.drae","nt":"Open","ps":"noun","t":["myth","ogreek"]},{"w":"hydric","d":"having or characterized by excessive moisture","s":"The ecology field guide explained that hydric soils, which are saturated with water for long periods, are the defining characteristic of wetland environments like marshes and swamps.","p":"HY-drik","o":"Greek","y":6,"bp":29,"m":"hydrick","sy":"hy.dric","nt":"Open","ps":"adjective","t":["character","ogreek"]},{"w":"hydrus","d":"a constellation in the southern hemisphere near the south celestial pole","s":"The astronomer traced the faint outline of Hydrus near the south celestial pole on the star chart.","p":"HY-drus","o":"Latin","y":6,"bp":29,"m":"hidrus","sy":"hy.drus","nt":"Open","ps":"noun","t":["astronomy","maps","olatin"]},{"w":"hyla","d":"the type genus of the Hylidae; tree toads","s":"The tiny hyla clung to the wet bark of the tree, its sticky toes barely visible.","p":"HY-luh","o":"Greek","y":7,"bp":27,"m":"hila","sy":"hy.la","nt":"Open","ps":"noun","t":["animals","flowers","ogreek"]},{"w":"hylas","d":"the type genus of the Hylidae; tree toads","s":"Several hylas were spotted calling from the reeds around the pond at dusk.","p":"HY-lus","o":"Greek","y":5,"bp":28,"m":"hilas","sy":"hy.las","nt":"Open","ps":"noun","t":["animals","flowers","ogreek"]},{"w":"hymned","d":"To have sung or celebrated someone or something in the form of a hymn; the past tense of 'hymn' used as a verb, meaning to have praised through sacred song.","s":"They hymned their love of God.","p":"HIMD","o":"Greek","y":6,"bp":27,"m":"himd","nt":"Open","ps":"verb","t":["music","religion","wordwords","ogreek"]},{"w":"hyoid","d":"a U-shaped bone at the base of the tongue that supports the tongue muscles","s":"The forensic scientist examined the hyoid bone carefully to determine the cause of injury.","p":"HY-oyd","o":"French","y":5,"bp":28,"m":"hyiod","sy":"hy.oid","nt":"Open","ps":"noun","t":["body","ofrench"]},{"w":"hyoids","d":"a U-shaped bone at the base of the tongue that supports the tongue muscles","s":"Comparative anatomists study hyoids across species to understand the evolution of speech.","p":"HY-oydz","o":"Greek","y":8,"bp":29,"m":"hyiods","sy":"hy.oids","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hypha","d":"any of the threadlike filaments forming the mycelium of a fungus","s":"Under the microscope, a single hypha of the fungus looked like a delicate glass thread.","p":"HY-fuh","o":"Greek","y":8,"bp":28,"m":"hyphia","sy":"hy.pha","nt":"Open","ps":"noun","t":["botany","ogreek"]},{"w":"hypnos","d":"the Greek god of sleep","s":"Ancient Greeks prayed to Hypnos to grant them peaceful dreams through the night.","p":"HIP-nos","o":"Greek","y":5,"bp":29,"m":"hypnoss","sy":"hyp.nos","nt":"Open","ps":"noun","t":["myth","kinship","ogreek"]},{"w":"hypos","d":"a compound used as a fixing agent in photographic developing","s":"The photographer kept several hypos ready in the darkroom to fix the developed images.","p":"HY-pohz","o":"Greek","y":5,"bp":28,"m":"hippos","sy":"hy.pos","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hysons","d":"a Chinese green tea with twisted leaves","s":"The merchant displayed three varieties of hysons in elegant tins at his tea shop.","p":"HY-sunz","o":"Chinese","y":8,"bp":25,"m":"hisons","sy":"hy.sons","nt":"Open","ps":"noun","t":["botany","oeastasia"]},{"w":"hyaenas","d":"doglike nocturnal mammal of Africa and southern Asia that feeds chiefly on carrion","s":"The hyaenas circled the lion's kill at a safe distance, waiting for their chance to steal a meal.","p":"hy-EE-naz","o":"Greek","y":7,"bp":31,"m":"hyeanas","sy":"hy.ae.nas","nt":"Open","ps":"noun","t":["animals","ecology","ogreek"]},{"w":"hyaenidae","d":"The biological family that includes hyenas, comprising carnivorous mammals found in Africa and Asia known for their distinctive calls, powerful jaws, and often scavenging behavior.","s":"The scientist studied the feeding habits of animals in the family Hyaenidae, which includes spotted and striped hyenas.","p":"hy-EE-nih-dee","o":"Greek","y":9,"bp":34,"m":"hyaenedae","sy":"hy.ae.ni.dae","nt":"Open","ps":"noun","t":["animals","ogreek"]},{"w":"hyaline","d":"Clear and glassy, like something you can see straight through.","s":"The morning is as clear as diamond or as hyaline.","p":"HY-uh-lin","o":"Latin","y":6,"bp":31,"m":"hyalin","sy":"hy.a.line","nt":"Open","ps":"noun","t":["body","olatin"]},{"w":"hyalines","d":"a glassy translucent substance that occurs in hyaline cartilage or in certain skin conditions","s":"The biology student examined hyalines under the microscope, marveling at their glassy, translucent appearance.","p":"HY-uh-linz","o":"Greek","y":8,"bp":32,"m":"hyalins","sy":"hy.a.lines","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hyalins","d":"a glassy translucent substance that occurs in hyaline cartilage or in certain skin conditions","s":"The pathologist noted deposits of hyalins in the tissue sample taken from the patient's cartilage.","p":"HY-uh-linz","o":"Greek","y":8,"bp":31,"m":"hyalines","sy":"hy.a.lins","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hyaloid","d":"the transparent membrane enveloping the vitreous humor of the eye and separating it from the retina","p":"HY-uh-loyd","o":"Greek","y":7,"bp":31,"m":"hyalide","sy":"hy.a.loid","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hyaloids","d":"the transparent membrane enveloping the vitreous humor of the eye and separating it from the retina","s":"The ophthalmologist explained that hyaloids play a crucial role in maintaining the structure of the eye.","p":"HY-uh-loydz","o":"Greek","y":9,"bp":32,"m":"hyaloides","sy":"hy.a.loids","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hybanthus","d":"a genus of herbs and small shrubs with white or purple flowers; grows in tropical or subtropical regions","s":"The botanist discovered a rare species of Hybanthus blooming with delicate purple flowers in the tropical forest.","p":"hy-BAN-thus","o":"Greek","y":8,"bp":33,"sy":"hy.ban.thus","nt":"Open","ps":"noun","t":["botany","flowers","ogreek"]},{"w":"hybridise","d":"breed animals or plants using parents of different races and varieties","p":"HY-brih-dyz","o":"Latin","y":8,"bp":33,"m":"hybridize","sy":"hy.brid.ise","nt":"Open","ps":"verb","t":["animals","botany","kinship","sports","olatin"]},{"w":"hydantoin","d":"any of a group of anticonvulsant drugs used in treating epilepsy","s":"The doctor prescribed a hydantoin-based medication to help control the patient's epileptic seizures.","p":"hy-DAN-toh-in","o":"Greek","y":8,"bp":34,"m":"hydantoine","sy":"hy.dan.to.in","nt":"Open","ps":"noun","t":["pharmacy","ogreek"]},{"w":"hydathode","d":"a pore that exudes water on the surface or margin of a leaf of higher plants","s":"The plant biology teacher pointed out a hydathode at the leaf's edge, where tiny droplets of water were seeping out.","p":"HY-duh-thohd","o":"Greek","y":9,"bp":33,"m":"hydathoad","sy":"hy.da.thode","nt":"Open","ps":"noun","t":["botany","ogreek"]},{"w":"hydatid","d":"cyst filled with liquid; forms as a result of infestation by tapeworm larvae (as in echinococcosis)","s":"The surgeon carefully removed the hydatid cyst from the patient's liver, where the tapeworm larvae had taken hold.","p":"HY-duh-tid","o":"Greek","y":6,"bp":31,"m":"hydatide","sy":"hy.da.tid","nt":"Open","ps":"noun","t":["insects","ogreek"]},{"w":"hydatids","d":"cyst filled with liquid; forms as a result of infestation by tapeworm larvae (as in echinococcosis)","s":"The veterinarian found hydatids in the sheep's organs and recommended immediate treatment to prevent spreading.","p":"HY-duh-tidz","o":"Greek","y":8,"bp":32,"m":"hydatides","sy":"hy.da.tids","nt":"Open","ps":"noun","t":["insects","ogreek"]},{"w":"hydnaceae","d":"A family of fungi commonly called tooth fungi, characterized by spore-bearing spines or teeth hanging from the underside of the fruiting body rather than gills or pores.","s":"The mycologist collected several specimens of Hydnaceae, commonly known as tooth fungi, from the forest floor.","p":"hid-NAY-see-ee","o":"Greek","y":9,"bp":34,"m":"hydnacae","sy":"hyd.na.ce.ae","nt":"Open","ps":"noun","t":["botany","mycology","ogreek"]},{"w":"hydrastis","d":"small genus of perennial herbs having rhizomes and palmate leaves and small solitary flowers; of northeastern United States and Japan","s":"The herbalist used dried Hydrastis root, also known as goldenseal, to prepare a traditional remedy.","p":"hy-DRAS-tis","o":"Greek","y":8,"bp":33,"m":"hydrastus","sy":"hy.dras.tis","nt":"Open","ps":"noun","t":["botany","flowers","ogreek"]},{"w":"hydrating","d":"supply water or liquid to in order to maintain a healthy balance","p":"HY-dray-ting","o":"Greek","y":4,"bp":33,"m":"hydreating","sy":"hy.drat.ing","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hydremia","d":"blood disorder in which there is excess fluid volume compared with the cell volume of the blood","s":"The physician diagnosed the patient with hydremia after blood tests revealed an unusually high ratio of fluid to blood cells.","p":"hy-DREE-mee-uh","o":"Greek","y":9,"bp":33,"m":"hydroemia","sy":"hy.dre.mi.a","nt":"Open","ps":"noun","t":["body","disease","ogreek"]},{"w":"hydrides","d":"any binary compound formed by the union of hydrogen and other elements","s":"The chemistry class learned that hydrides are formed when hydrogen bonds with metals like sodium or lithium.","p":"HY-drydz","o":"Greek","y":6,"bp":30,"m":"hydrids","sy":"hy.drides","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrogel","d":"a colloidal gel in which water is the dispersion medium","s":"The nurse applied a soothing hydrogel dressing to the burn wound to keep it moist and promote healing.","p":"HY-droh-jel","o":"Greek","y":5,"bp":32,"m":"hydrojel","sy":"hy.dro.gel","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hydrogels","d":"a colloidal gel in which water is the dispersion medium","s":"Scientists are developing new hydrogels that can deliver medicine slowly and steadily inside the body.","p":"HY-droh-jelz","o":"Greek","y":6,"bp":33,"m":"hydrojels","sy":"hy.dro.gels","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hydroid","d":"colonial coelenterates having the polyp phase dominant","s":"The marine biologist pointed out a hydroid colony clinging to the rocky seafloor, its tiny polyps waving in the current.","p":"HY-droyd","o":"Greek","y":6,"bp":30,"m":"hydroyd","sy":"hy.droid","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hydroids","d":"colonial coelenterates having the polyp phase dominant","s":"During the tide pool tour, the guide showed us clusters of hydroids that looked almost like delicate underwater ferns.","p":"HY-droydz","o":"Greek","y":7,"bp":30,"sy":"hy.droids","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hydrolize","d":"make a compound react with water and undergo hydrolysis","s":"The chemist added water to hydrolize the compound and break it into simpler molecules.","p":"HY-droh-lyz","o":"Greek","y":9,"bp":33,"m":"hydrolyze","sy":"hy.dro.lize","nt":"Open","ps":"verb","t":["chemistry","ogreek"]},{"w":"hydrolyse","d":"undergo hydrolysis; decompose by reacting with water","s":"When you add water to certain proteins, they begin to hydrolyse and break down into amino acids.","p":"HY-droh-lyz","o":"Greek","y":9,"bp":33,"m":"hydrolise","sy":"hy.dro.lyse","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hydromel","d":"honey diluted in water; becomes mead when fermented","s":"The ancient Greeks enjoyed drinking hydromel, a simple mixture of honey and water that could be fermented into mead.","p":"HY-droh-mel","o":"Latin","y":8,"bp":32,"m":"hydromill","sy":"hy.dro.mel","nt":"Open","ps":"noun","t":["chemistry","olatin"]},{"w":"hydromels","d":"honey diluted in water; becomes mead when fermented","s":"The medieval feast featured various hydromels, some sweetened with herbs and others left plain.","p":"HY-droh-melz","o":"Greek","y":8,"bp":33,"m":"hydromells","sy":"hy.dro.mels","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydromys","d":"A genus of semiaquatic rodents, commonly known as water rats, native to Australia and New Guinea, well adapted to life in and around freshwater streams and lakes.","s":"The researcher studied Hydromys colonies living along the riverbanks of Australia, noting their excellent swimming abilities.","p":"HY-droh-mis","o":"Greek","y":9,"bp":32,"m":"hydromis","sy":"hy.dro.mys","nt":"Open","ps":"noun","t":["animals","waterways","ogreek"]},{"w":"hydrops","d":"swelling from excessive accumulation of watery fluid in cells, tissues, or serous cavities","s":"The doctor diagnosed the infant with hydrops, a serious condition involving dangerous fluid buildup in body tissues.","p":"HY-drops","o":"Greek","y":6,"bp":30,"m":"hydropps","sy":"hy.drops","nt":"Open","ps":"noun","t":["body","disease","ogreek"]},{"w":"hydropses","d":"swelling from excessive accumulation of watery fluid in cells, tissues, or serous cavities","s":"Medical literature describes several types of hydropses, each characterized by fluid accumulation in different parts of the body.","p":"HY-drop-sez","o":"Greek","y":8,"bp":33,"m":"hydropsies","sy":"hy.drop.ses","nt":"Open","ps":"noun","t":["body","disease","ogreek"]},{"w":"hydroxyl","d":"the monovalent group -OH in such compounds as bases and some acids and alcohols","s":"The chemistry teacher explained that a hydroxyl group, written as -OH, is responsible for making alcohols soluble in water.","p":"hy-DROK-sil","o":"Greek","y":4,"bp":32,"m":"hydroxel","sy":"hy.drox.yl","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydroxyls","d":"the monovalent group -OH in such compounds as bases and some acids and alcohols","s":"The chemistry teacher explained that hydroxyls are the key functional groups that make alcohols reactive.","p":"hy-DRОК-silz","o":"Greek","y":7,"bp":33,"m":"hydroxels","sy":"hy.drox.yls","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrozoa","d":"coelenterates typically having alternation of generations; hydroid phase is usually colonial giving rise to the medusoid phase by budding: hydras and jellyfishes","s":"The marine biology class studied hydrozoa, marveling at how these tiny organisms alternate between polyp and medusa forms.","p":"hy-droh-ZOH-uh","o":"Greek","y":8,"bp":33,"sy":"hy.dro.zo.a","nt":"Open","ps":"noun","t":["marine","ogreek"]},{"w":"hydrozoan","d":"colonial coelenterates having the polyp phase dominant","s":"The Portuguese man-of-war is actually a hydrozoan colony, not a single jellyfish as many people assume.","p":"hy-droh-ZOH-un","o":"Greek","y":8,"bp":34,"m":"hydrozooan","sy":"hy.dro.zo.an","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hygienes","d":"a condition promoting sanitary practices","s":"Good personal hygienes practiced daily can prevent the spread of many common illnesses.","p":"HY-jeenz","o":"Greek","y":8,"bp":30,"m":"hygenes","sy":"hy.gienes","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hygienics","d":"the science concerned with the prevention of illness and maintenance of health","s":"The public health course covered hygienics, teaching students how proper sanitation prevents widespread disease.","p":"hy-JEE-en-iks","o":"French","y":8,"bp":34,"m":"hygenics","sy":"hy.gien.ics","nt":"Open","ps":"noun","t":["disease","ofrench"]},{"w":"hygienize","d":"make sanitary by cleaning or sterilizing","s":"The hospital staff worked carefully to hygienize every surface in the operating room before the procedure.","p":"HY-jee-en-yz","o":"Greek","y":9,"bp":33,"m":"hygienise","sy":"hy.gien.ize","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hygrodeik","d":"a wet and dry bulb hygrometer","s":"The meteorologist used a hygrodeik to measure the humidity in the greenhouse with great precision.","p":"HY-groh-deek","o":"Greek","y":8,"bp":33,"m":"hygrodeic","sy":"hy.gro.deik","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hylidae","d":"the amphibian family of tree frogs","s":"The naturalist's field guide devoted an entire chapter to hylidae, showcasing dozens of brightly colored tree frog species.","p":"HIL-ih-dee","o":"Greek","y":9,"bp":31,"sy":"hy.li.dae","nt":"Open","ps":"noun","t":["animals","amphibians","ogreek"]},{"w":"hylobates","d":"A genus of small apes commonly known as gibbons, found in the forests of Southeast Asia, known for their long arms, agile tree-swinging locomotion, and melodic calls.","s":"The primatologist observed how hylobates swung gracefully through the forest canopy using their remarkably long arms.","p":"hy-LOB-uh-teez","o":"Greek","y":7,"bp":34,"m":"hilobates","sy":"hy.lo.ba.tes","nt":"Open","ps":"noun","t":["flowers","ogreek"]},{"w":"hymenaea","d":"genus of tropical American timber trees","s":"The botanist identified the towering tree as hymenaea, a valuable timber species prized throughout tropical America.","p":"hy-meh-NEE-uh","o":"Greek","y":9,"bp":33,"m":"hymenea","sy":"hy.me.nae.a","nt":"Open","ps":"noun","t":["flowers","ogreek"]},{"w":"hymenal","d":"of or relating to the hymen","s":"The medical textbook included a detailed diagram of hymenal anatomy for students studying reproductive health.","p":"HY-meh-nul","o":"Greek","y":8,"bp":31,"m":"hyminal","sy":"hy.men.al","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"hymeneals","d":"the social event at which the ceremony of marriage is performed","s":"The poet composed verses celebrating the hymeneals of the young couple as their guests gathered in the garden.","p":"him-eh-NEE-ulz","o":"Greek","y":8,"bp":34,"m":"hymenials","sy":"hy.me.ne.als","nt":"Open","ps":"noun","t":["religion","kinship","ogreek"]},{"w":"hymenium","d":"spore-bearing layer of cells in certain fungi containing asci or basidia","s":"Under the microscope, the hymenium of the mushroom revealed dozens of tiny spore-producing structures packed tightly together.","p":"hy-MEE-nee-um","o":"Greek","y":6,"bp":33,"m":"hymeneum","sy":"hy.me.ni.um","nt":"Open","ps":"noun","t":["botany","maps","ogreek"]},{"w":"hymeniums","d":"spore-bearing layer of cells in certain fungi containing asci or basidia","s":"The mycologist compared the hymeniums of several mushroom species to classify them accurately.","p":"hy-MEE-nee-umz","o":"Greek","y":8,"bp":34,"m":"hymeniems","sy":"hy.me.ni.ums","nt":"Open","ps":"noun","t":["botany","maps","ogreek"]},{"w":"hymnaries","d":"a songbook containing a collection of hymns","s":"The church elders donated several antique hymnaries to the local museum, where their faded pages told stories of centuries of worship.","p":"HIM-nuh-reez","o":"Greek","y":8,"bp":33,"m":"hymneries","sy":"hym.na.ries","nt":"Open","ps":"noun","t":["religion","ogreek"]},{"w":"hymnary","d":"a songbook containing a collection of hymns","s":"The choir director carefully selected songs from the old hymnary for the holiday service.","p":"HIM-nuh-ree","o":"Greek","y":8,"bp":31,"m":"hymnery","sy":"hym.na.ry","nt":"Open","ps":"noun","t":["religion","ogreek"]},{"w":"hymnbook","d":"a songbook containing a collection of hymns","s":"Each pew held a worn hymnbook whose pages had been turned by generations of faithful worshippers.","p":"HIM-book","o":"Greek","y":6,"bp":30,"m":"himbook","sy":"hymn.book","nt":"Open","ps":"noun","t":["religion","ogreek"]},{"w":"hymnbooks","d":"a songbook containing a collection of hymns","s":"The volunteers spent the afternoon replacing the damaged hymnbooks in every pew before Sunday's service.","p":"HIM-books","o":"Greek","y":7,"bp":31,"m":"himbooksbooks","sy":"hymn.books","nt":"Open","ps":"noun","t":["religion","ogreek"]},{"w":"hymning","d":"The act of singing or composing hymns; praising or celebrating something through the performance of a hymn or hymn-like song.","p":"HIM-ing","o":"Greek","y":8,"bp":30,"m":"himing","sy":"hym.ning","nt":"Open","ps":"verb","t":["music","religion","ogreek"]},{"w":"hymnodies","d":"the act of singing psalms or hymns","s":"The professor lectured on medieval hymnodies, playing recordings of ancient chants to illustrate how worship music evolved.","p":"HIM-noh-deez","o":"Greek","y":8,"bp":33,"m":"hymnodys","sy":"hym.no.dies","nt":"Open","ps":"noun","t":["music","religion","ogreek"]},{"w":"hymnody","d":"the act of singing psalms or hymns","s":"Sacred hymnody filled the cathedral as the congregation lifted their voices in unison during the evening service.","p":"HIM-noh-dee","o":"French","y":6,"bp":31,"m":"hymnodee","sy":"hym.no.dy","nt":"Open","ps":"noun","t":["music","religion","ofrench"]},{"w":"hyoscine","d":"an alkaloid with anticholinergic effects that is used as a sedative and to treat nausea and to dilate the pupils in ophthalmic procedures","p":"HY-oh-seen","o":"Greek","y":7,"bp":32,"m":"hyosceine","sy":"hy.o.scine","nt":"Open","ps":"noun","t":["disease","pharmacy","ogreek"]},{"w":"hyoscines","d":"an alkaloid with anticholinergic effects that is used as a sedative and to treat nausea and to dilate the pupils in ophthalmic procedures","p":"HY-oh-seenz","o":"Greek","y":8,"bp":33,"m":"hyosceines","sy":"hy.o.scines","nt":"Open","ps":"noun","t":["disease","pharmacy","ogreek"]},{"w":"hypanthia","d":"the cuplike or ringlike or tubular structure of a flower which bears the sepals and stamens and calyx (as in Rosaceae)","s":"The botanist pointed out that the hypanthia of rose flowers form the fleshy rose hips we harvest in autumn.","p":"hy-PAN-thee-uh","o":"Greek","y":9,"bp":34,"m":"hypanthea","sy":"hy.pan.thi.a","nt":"Open","ps":"noun","t":["flowers","ogreek"]},{"w":"hyperemia","d":"increased blood in an organ or other body part","s":"The doctor noted hyperemia in the patient's skin, explaining that the redness was caused by a rush of blood to the area.","p":"hy-per-EE-mee-uh","o":"Greek","y":8,"bp":36,"m":"hyperaemia","sy":"hy.per.e.mi.a","nt":"Open","ps":"noun","t":["body","disease","ogreek"]},{"w":"hyperemic","d":"relating to or caused by hyperemia","s":"The hyperemic tissue surrounding the wound appeared bright red and warm to the touch.","p":"hy-per-EE-mik","o":"Greek","y":7,"bp":34,"m":"hyperaemic","sy":"hy.per.e.mic","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"hyperfine","d":"extremely fine or thin, as in a spectral line split into two or more components","s":"In advanced physics class, the teacher explained that the hyperfine structure of the hydrogen atom results from tiny interactions between the electron and the nucleus, splitting spectral lines into extremely close pairs.","p":"HY-per-fyn","o":"French","y":7,"bp":33,"m":"hyperfyne","sy":"hy.per.fine","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"hypericum","d":"large almost cosmopolitan genus of evergreen or deciduous shrubs and herbs with often showy yellow flowers; cosmopolitan except tropical lowlands and Arctic or high altitudes and desert regions","s":"The herbalist recommended hypericum, commonly known as St. John's wort, as a natural remedy for mild anxiety.","p":"hy-PAIR-ih-kum","o":"Greek","y":6,"bp":34,"m":"hyperycum","sy":"hy.per.i.cum","nt":"Open","ps":"noun","t":["botany","flowers","ogreek"]},{"w":"hyperon","d":"any baryon that is not a nucleon; unstable particle with mass greater than a neutron","s":"The physicist was thrilled when the particle accelerator produced a hyperon, confirming a key prediction of her theoretical model.","p":"HY-per-on","o":"Greek","y":8,"bp":31,"m":"hyperron","sy":"hy.per.on","nt":"Open","ps":"noun","t":["physics","ogreek"]},{"w":"hyperons","d":"any baryon that is not a nucleon; unstable particle with mass greater than a neutron","s":"The research team detected several hyperons during the high-energy collision experiment and carefully recorded their decay patterns.","p":"HY-per-onz","o":"Greek","y":8,"bp":32,"m":"hyperrons","sy":"hy.per.ons","nt":"Open","ps":"noun","t":["physics","ogreek"]},{"w":"hyperope","d":"a person with hyperopia; a farsighted person","s":"The optometrist confirmed that Marcus was a hyperope who needed glasses for reading nearby text.","p":"HY-per-ope","o":"Greek","y":9,"bp":32,"m":"hyperop","sy":"hy.per.ope","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hyperopes","d":"a person with hyperopia; a farsighted person","s":"Most hyperopes find that reading small print becomes increasingly difficult as they age.","p":"HY-per-opes","o":"Greek","y":8,"bp":33,"m":"hyperops","sy":"hy.per.opes","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hyperopic","d":"abnormal ability to focus of distant objects","s":"Her hyperopic vision meant she could spot a hawk on a distant fence but struggled to read her own textbook.","p":"hy-per-OP-ik","o":"Greek","y":7,"bp":34,"m":"hyperoppic","sy":"hy.per.op.ic","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"hyperpnea","d":"energetic (deep and rapid) respiration that occurs normally after exercise or abnormally with fever or various disorders","s":"After sprinting the final lap, the runner experienced hyperpnea as her lungs worked overtime to restore oxygen levels.","p":"hy-perp-NEE-uh","o":"Greek","y":9,"bp":34,"m":"hyperpneia","sy":"hy.perp.ne.a","nt":"Open","ps":"noun","t":["disease","ogreek"]},{"w":"hypethral","d":"partly or entirely open to the sky","s":"The ancient Greek temple was hypethral, its central chamber left open so worshippers could see the heavens above.","p":"hy-PEE-thrul","o":"Greek","y":8,"bp":33,"m":"hypaethral","sy":"hy.pe.thral","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"hyphema","d":"bleeding into the interior chamber of the eye","s":"After taking a ball to the face, the young hockey player was diagnosed with a hyphema and ordered to rest his eyes.","p":"hy-FEE-muh","o":"Greek","y":8,"bp":31,"m":"hyphemia","sy":"hy.phe.ma","nt":"Open","ps":"noun","t":["buildings","ogreek"]},{"w":"hyphened","d":"divide or connect with a hyphen","s":"She hyphened the compound adjective so the sentence would be grammatically correct.","p":"HY-fend","o":"Greek","y":8,"bp":30,"m":"hyphined","sy":"hy.phened","nt":"Open","ps":"verb","t":["numbers","ogreek"]},{"w":"hyphening","d":"divide or connect with a hyphen","s":"The editor spent the afternoon hyphening awkward compound words throughout the manuscript.","p":"HY-fen-ing","o":"Greek","y":8,"bp":33,"m":"hyphining","sy":"hy.phen.ing","nt":"Open","ps":"verb","t":["numbers","ogreek"]},{"w":"hyphens","d":"a punctuation mark (-) used between parts of a compound word or between the syllables of a word when the word is divided at the end of a line of text","s":"The style guide explained exactly when to use hyphens in compound adjectives before a noun.","p":"HY-fenz","o":"Greek","y":5,"bp":30,"m":"hyphins","sy":"hy.phens","nt":"Open","ps":"noun","t":["chemistry","numbers","wordwords","ogreek"]},{"w":"hypnoid","d":"of or relating to a state of sleep or hypnosis","s":"The patient drifted into a hypnoid trance as the therapist spoke in a slow, steady voice.","p":"HIP-noid","o":"Greek","y":8,"bp":30,"m":"hypnoyid","sy":"hyp.noid","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"hypnoses","d":"a state that resembles sleep but that is induced by suggestion","s":"The researcher studied dozens of hypnoses performed in clinical settings to understand the brain during trance states.","p":"hip-NOH-seez","o":"Greek","y":8,"bp":32,"m":"hypnosises","sy":"hyp.no.ses","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypnotise","d":"induce hypnosis in","s":"The stage performer claimed he could hypnotise volunteers within minutes using only the sound of his voice.","p":"HIP-nuh-tize","o":"Greek","y":7,"bp":33,"m":"hypnotize","sy":"hyp.no.tise","nt":"Open","ps":"verb","t":["ogreek"]},{"w":"hypoblast","d":"the inner germ layer that develops into the lining of the digestive and respiratory systems","s":"During early embryonic development, the hypoblast forms the foundation for the digestive tract lining.","p":"HY-poh-blast","o":"Greek","y":7,"bp":33,"m":"hypoblaste","sy":"hy.po.blast","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypoderma","d":"in some classifications considered the type genus of the family Hypodermatidae: warble flies","s":"The veterinarian identified hypoderma larvae as the cause of the warble bumps along the cattle's backs.","p":"hy-poh-DER-muh","o":"Greek","y":9,"bp":34,"m":"hypodermia","sy":"hy.po.der.ma","nt":"Open","ps":"noun","t":["kinship","ogreek"]},{"w":"hyponym","d":"a word that is more specific than a given word","s":"The word 'spaniel' is a hyponym of 'dog' because it refers to a specific type within the broader category.","p":"HY-poh-nim","o":"Greek","y":9,"bp":31,"m":"hyponyme","sy":"hy.po.nym","nt":"Open","ps":"noun","t":["wordwords","ogreek"]},{"w":"hypopitys","d":"term used in some classifications for the pinesaps, which are usually included in the genus Monotropa","s":"Deep in the shaded pine forest, she discovered a cluster of hypopitys rising ghostly white from the leaf litter.","p":"hy-POP-ih-tis","o":"Greek","y":9,"bp":34,"m":"hypopitis","sy":"hy.pop.i.tys","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypopnea","d":"slow or shallow breathing","s":"The sleep study revealed episodes of hypopnea throughout the night, explaining why the patient always woke exhausted.","p":"hy-POP-nee-uh","o":"Greek","y":8,"bp":33,"m":"hypopnia","sy":"hy.pop.ne.a","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypopneas","d":"slow or shallow breathing","s":"Doctors counted multiple hypopneas per hour in the patient's sleep recording, indicating a moderate disorder.","p":"hy-POP-nee-uhz","o":"Greek","y":8,"bp":34,"m":"hypopnias","sy":"hy.pop.ne.as","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hyposmia","d":"lessened sensitivity to odors","s":"After his illness, Daniel developed hyposmia and could barely detect the strong scent of garlic cooking in the kitchen.","p":"hy-POZ-mee-uh","o":"Greek","y":9,"bp":33,"m":"hyposemia","sy":"hy.pos.mi.a","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hypotonia","d":"(of muscular tissue) the state of being hypotonic","s":"The infant's hypotonia made it difficult for him to hold up his head, so the doctor referred him to a specialist.","p":"hy-poh-TOH-nee-uh","o":"Greek","y":8,"bp":36,"m":"hypotonea","sy":"hy.po.to.ni.a","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hypotonic","d":"(of living tissue) lacking normal tone or tension","s":"The physical therapist noted that the child's hypotonic muscles required daily strengthening exercises.","p":"hy-poh-TON-ik","o":"Greek","y":6,"bp":34,"m":"hypotonick","sy":"hy.po.ton.ic","nt":"Open","ps":"adjective","t":["body","ogreek"]},{"w":"hypotonus","d":"(of muscular tissue) the state of being hypotonic","s":"The neurologist explained that hypotonus in the patient's limbs was a sign of an underlying nerve condition.","p":"hy-POT-oh-nus","o":"Greek","y":8,"bp":34,"m":"hypotonas","sy":"hy.pot.o.nus","nt":"Open","ps":"noun","t":["body","ogreek"]},{"w":"hypoxias","d":"oxygen deficiency causing a very strong drive to correct the deficiency","s":"Mountaineers at extreme altitude can suffer dangerous hypoxias that cloud their judgment and slow their movements.","p":"hy-POK-see-uhz","o":"Greek","y":8,"bp":33,"m":"hypoxeas","sy":"hy.pox.i.as","nt":"Open","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypoxis","d":"small plants that resemble amaryllis and that grow from a corm and bear flowers on a leafless stalk; sometimes classified as member of the family Amaryllidaceae: star grass","s":"The botanist pointed out a patch of hypoxis blooming with cheerful yellow stars along the meadow's edge.","p":"hy-POK-sis","o":"Greek","y":8,"bp":31,"m":"hypoxys","sy":"hy.pox.is","nt":"Open","ps":"noun","t":["botany","flowers","ogreek"]},{"w":"hyraces","d":"any of several small ungulate mammals of Africa and Asia with rodent-like incisors and feet with hooflike toes","s":"To our surprise, the guide told us that hyraces are actually the closest living relatives of elephants.","p":"HY-ruh-seez","o":"Greek","y":8,"bp":31,"m":"hyraxes (as alternate plural)","sy":"hy.ra.ces","nt":"Open","ps":"noun","t":["animals","ogreek"]},{"w":"hyssops","d":"a European mint with aromatic and pungent leaves used in perfumery and as a seasoning in cookery; often cultivated as a remedy for bruises; yields hyssop oil","s":"The herbalist kept several potted hyssops on her windowsill, using the fragrant leaves in both teas and soups.","p":"HIS-ups","o":"Greek","y":8,"bp":30,"m":"hysops","sy":"hys.sops","nt":"Open","ps":"noun","t":["pharmacy","botany","farming","culinary","spices","time","ogreek"]},{"w":"hyssopus","d":"Eurasian genus of perennial herbs or subshrubs","s":"The botanical garden's Mediterranean section featured hyssopus growing alongside lavender and rosemary.","p":"his-OH-pus","o":"Greek","y":8,"bp":32,"m":"hysopus","sy":"hys.so.pus","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hysterias","d":"state of violent mental agitation","s":"History books describe how mass hysterias have swept through communities, causing otherwise calm people to act irrationally.","p":"his-TAIR-ee-uhz","o":"Greek","y":8,"bp":34,"m":"histerias","sy":"hys.te.ri.as","nt":"Open","ps":"noun","t":["ogreek"]},{"w":"hysterics","d":"an attack of hysteria","s":"The comedian had the entire audience in hysterics with his impression of a confused robot.","p":"hih-STEH-rihks","o":"Greek","y":5,"bp":45,"m":"histerics","sy":"hhih.steh.rih.ks","nt":"Junior","ps":"noun","t":["ogreek"]},{"w":"hygienic","d":"tending to promote or preserve health","s":"Hygienic habits like using disposable tissues.","p":"hy-JEE-nik","o":"French","y":4,"bp":44,"m":"hygenic","sy":"hy.gien.ic","nt":"Junior","ps":"adjective","t":["health","ofrench"]},{"w":"hypnotist","d":"a person who induces hypnosis","s":"The hypnotist asked the volunteer to stare at the swinging watch and relax completely.","p":"HIH-pnuh-tihst","o":"Greek","y":5,"bp":45,"m":"hypnotyst","sy":"hhih.pnah.tih.st","nt":"Junior","ps":"noun","t":["ogreek"]},{"w":"hyperion","d":"(Greek mythology) a Titan who was the son of Gaea and Uranus and the father of Helios and Selene and Eos in ancient mythology","s":"In Greek mythology, Hyperion was a powerful Titan associated with the blazing sun.","p":"heye-PIH-ree-uhn","o":"Greek","y":4,"bp":67,"m":"hypereon","sy":"hhay.pih.riy.ah.n","nt":"Senior","ps":"noun","t":["myth","kinship","ancient","eponyms","ogreek","epgreek"]},{"w":"hyacinthlike","d":"Resembling a hyacinth flower in color, fragrance, shape, or other characteristic qualities, often used to describe something with a similar bell-shaped or richly fragrant appearance.","s":"The garden was filled with hyacinthlike blooms whose sweet fragrance drifted through the spring air.","p":"HY-uh-sinth-lyk","o":"Greek","y":9,"bp":36,"sy":"hy.acinth.like","ps":"adjective","t":["flowers","colors","ogreek"]},{"w":"Hyacinthus","d":"In Greek mythology, a beautiful youth beloved by the god Apollo who was accidentally killed and transformed into the hyacinth flower; also used as a proper name of Greek origin.","s":"In Greek mythology, Hyacinthus was a beautiful youth loved by the god Apollo.","p":"hy-uh-SIN-thus","o":"Greek","y":7,"bp":27,"sy":"hy.acinthus","ps":"noun","t":["flowers","myth","ogreek"]},{"w":"hyaloserositis","d":"Inflammation of a serous membrane that results in a thickened, glassy, or frosted appearance on the surface of the affected organ or tissue.","s":"The pathologist noted hyaloserositis in the tissue sample, recognizing the glassy inflammation of the serous membranes.","p":"hy-uh-loh-seer-oh-SY-tis","o":"Greek","y":9,"bp":24,"sy":"hyaloserosi.tis","ps":"noun","t":["body","disease","weather","music","ogreek"]},{"w":"hydatoscopy","d":"The ancient practice of divination or forecasting by observing and interpreting the appearance, movement, or properties of water.","s":"Ancient diviners practiced hydatoscopy, claiming they could predict the future by examining the surface of water.","p":"hy-dat-OS-koh-pee","o":"Greek","y":8,"bp":32,"ps":"noun","t":["ancient","ogreek"]},{"w":"hydramide","d":"A chemical compound formed from hydrazine and an acid or ester, containing both hydrogen and amide functional groups in its molecular structure.","s":"The chemistry student carefully recorded the properties of the hydramide compound in her lab notebook.","p":"HY-druh-myd","o":"Greek","y":9,"bp":26,"sy":"hy.dramide","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydranth","d":"The feeding polyp of a hydroid colony, a small water organism that has a mouth surrounded by tentacles used to capture food from the surrounding water.","s":"Under the microscope, the hydranth of the hydroid colony appeared as a tiny, flower-like feeding structure.","p":"HY-dranth","o":"Greek","y":8,"bp":25,"sy":"hy.dranth","ps":"noun","t":["ogreek"]},{"w":"hydrarthrosis","d":"inflammation and swelling of a movable joint because of excess synovial fluid","s":"After the injury, the doctor diagnosed hydrarthrosis in the patient's knee, explaining that excess fluid had built up in the joint.","p":"hy-drar-THROH-sis","o":"Greek","y":9,"bp":25,"sy":"hy.drarthro.sis","ps":"noun","t":["disease","ogreek"]},{"w":"hydrencephaloid","d":"Resembling or characteristic of hydrencephaly, a condition involving an abnormal accumulation of fluid in or around the brain, often used to describe symptoms that mimic this condition.","s":"The physician described the infant's symptoms as hydrencephaloid, resembling the signs of fluid accumulation in the brain.","p":"hy-dren-SEF-uh-loyd","o":"Greek","y":9,"bp":27,"sy":"hy.dren.cephaloid","ps":"adjective","t":["body","disease","ogreek"]},{"w":"hydria","d":"A type of ancient Greek water jar with three handles — two horizontal side handles for lifting and one vertical back handle for pouring — used for carrying and storing water.","s":"The museum displayed a beautifully painted hydria that ancient Greek women once used to carry water from the fountain.","p":"HY-dree-uh","o":"Greek","y":8,"bp":18,"sy":"hy.dria","ps":"noun","t":["ancient","ogreek"]},{"w":"hydro","d":"A shortened form referring to hydroelectric power, or informally to water; also used as a prefix root in compound words relating to water or hydrogen.","s":"The remote cabin was powered entirely by hydro, drawing electricity from the nearby rushing river.","p":"HEYE-droh","o":"Greek","y":4,"bp":17,"sy":"hhay.drow","ps":"noun","t":["botany","chemistry","wordwords","ogreek"]},{"w":"hydro-geothermal","d":"Relating to the combination of water and geothermal heat from within the earth, describing systems or processes where hot underground water or steam is used as an energy source.","s":"The scientists studied hydro-geothermal energy sources where underground water is heated by volcanic rock.","p":"HY-droh-jee-oh-THUR-mul","o":"Greek","y":6,"bp":29,"sy":"hy.dro-.geother.mal","ps":"adjective","t":["physics","ogreek"]},{"w":"hydrobarometer","d":"An instrument used to measure water pressure at various depths, especially in oceans or deep bodies of water, by recording the pressure exerted by a column of water.","s":"The researcher used a hydrobarometer to measure water pressure at various depths in the ocean.","p":"hy-droh-buh-ROM-ih-ter","o":"Greek","y":9,"bp":29,"sy":"hy.dro.barom.e.ter","ps":"noun","t":["waterways","buildings","music","numbers","ogreek"]},{"w":"hydrobilirubin","d":"A brownish pigment formed in the intestines by the bacterial reduction of bilirubin, a yellow compound produced by the breakdown of red blood cells.","s":"The biochemist identified hydrobilirubin as a reduced form of bilirubin found in the digestive tract.","p":"hy-droh-bil-ih-ROO-bin","o":"Greek","y":9,"bp":27,"sy":"hy.dro.biliru.bin","ps":"noun","t":["body","disease","chemistry","painting","ogreek"]},{"w":"hydroboracite","d":"A hydrated calcium magnesium borate mineral that occurs as colorless or white crystals, typically found in evaporite deposits and valued as a source of boron.","s":"The mineralogist found a rare specimen of hydroboracite, a hydrated calcium magnesium borate mineral.","p":"hy-droh-BOR-uh-syt","o":"Greek","y":9,"bp":26,"sy":"hy.drob.o.racite","ps":"noun","t":["chemistry","minerals","colors","ogreek"]},{"w":"hydrobromide","d":"A salt or compound formed by the reaction of hydrobromic acid with a base or organic compound, containing both hydrogen and bromine in its chemical structure.","s":"The pharmacist prepared a hydrobromide salt of the medication to make it more soluble in water.","p":"hy-droh-BROH-myd","o":"Greek","y":8,"bp":38,"sy":"hy.dro.bro.mide","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrocarbostyril","d":"A hydrogenated derivative of carbostyril, an organic chemical compound used in the synthesis of certain dyes, pharmaceuticals, and other chemical substances.","s":"The organic chemist synthesized hydrocarbostyril as part of her research into nitrogen-containing ring compounds.","p":"hy-droh-kar-boh-STY-ril","o":"Greek","y":9,"bp":29,"sy":"hy.dro.car.bostyril","ps":"noun","t":["pharmacy","chemistry","ogreek"]},{"w":"hydrocarburet","d":"An older chemical term for a compound consisting solely of hydrogen and carbon, equivalent to what is now called a hydrocarbon; used historically in early chemistry literature.","s":"Early chemists used the term hydrocarburet to describe what we now simply call a hydrocarbon compound.","p":"hy-droh-KAR-byuh-ret","o":"Greek","y":9,"bp":28,"sy":"hy.dro.car.bu.ret","ps":"noun","t":["chemistry","poetry","ogreek"]},{"w":"hydrocephaloid","d":"Resembling or having characteristics similar to hydrocephalus, a condition in which excess cerebrospinal fluid accumulates in the brain, without necessarily being the actual condition.","s":"The doctor noted that the infant's symptoms were hydrocephaloid, resembling but not identical to true hydrocephalus.","p":"hy-droh-SEF-uh-loyd","o":"Greek","y":9,"bp":26,"sy":"hy.dro.cephaloid","ps":"adjective","t":["body","ogreek"]},{"w":"hydrochemical","d":"Relating to the chemical properties, composition, or reactions of natural waters, including rivers, groundwater, and oceans, especially as studied in environmental or geological science.","s":"The hydrochemical analysis of the river revealed dangerous levels of dissolved heavy metals.","p":"hy-droh-KEM-ih-kul","o":"Greek","y":9,"bp":28,"sy":"hy.dro.chem.i.cal","ps":"adjective","t":["chemistry","minerals","ecology","waterways","ogreek"]},{"w":"hydrochloric","d":"a strong acid made from hydrogen chloride gas dissolved in water","s":"The science teacher warned students to handle hydrochloric acid with extreme care because of its corrosive power.","p":"hy-droh-KLOR-ik","o":"Greek","y":7,"bp":36,"sy":"hy.drochlo.ric","ps":"adjective","t":["body","chemistry","ogreek"]},{"w":"hydrochlorofluorocarbon","d":"a fluorocarbon that is replacing chlorofluorocarbon as a refrigerant and propellant in aerosol cans; considered to be somewhat less destructive to the atmosphere","s":"The refrigerator manufacturer switched to hydrochlorofluorocarbon as a safer alternative to the ozone-destroying CFCs.","p":"hy-droh-klor-oh-FLOOR-oh-kar-bon","o":"Greek","y":9,"bp":33,"sy":"hy.drochlo.roflu.o.ro.car.bon","ps":"noun","t":["ogreek"]},{"w":"hydrochory","d":"The dispersal of plant seeds or spores by water, a method by which certain plants spread their offspring through rivers, rain, floods, or ocean currents.","s":"Coconuts travel vast ocean distances through hydrochory, using water currents to spread to new islands.","p":"hy-droh-KOR-ee","o":"Greek","y":9,"bp":29,"sy":"hy.dro.chory","ps":"noun","t":["botany","weather","waterways","ogreek"]},{"w":"hydroclimatic","d":"Relating to the interaction between water resources and climate, especially the patterns of rainfall, drought, and water availability as influenced by broader climate conditions.","s":"The hydroclimatic data showed that droughts had become more frequent in the region over the past century.","p":"hy-droh-kly-MAT-ik","o":"Greek","y":9,"bp":28,"sy":"hy.dro.cli.mat.ic","ps":"adjective","t":["weather","ogreek"]},{"w":"hydrocyanate","d":"A salt or ester of hydrocyanic acid, a compound containing hydrogen and cyanide, used in certain chemical processes and reactions.","s":"The chemist identified hydrocyanate ions in the solution during the toxicology experiment.","p":"hy-droh-SY-uh-nayt","o":"Greek","y":9,"bp":36,"sy":"hy.dro.cyanate","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrocyanide","d":"A compound formed from hydrogen cyanide and another element or group, closely related to hydrocyanic acid and sharing its highly toxic chemical properties.","s":"Safety protocols required that any hydrocyanide compound be handled only in a fully ventilated laboratory.","p":"hy-droh-SY-uh-nyd","o":"Greek","y":9,"bp":36,"sy":"hy.dro.cyanide","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrodistention","d":"A medical procedure in which a body cavity, such as the bladder, is expanded by filling it with water or saline solution, often used for diagnostic or therapeutic purposes.","s":"The urologist performed hydrodistention of the bladder to both diagnose and temporarily relieve the patient's pain.","p":"hy-droh-dis-TEN-shun","o":"Greek","y":9,"bp":28,"sy":"hy.drodis.ten.tion","ps":"noun","t":["body","ogreek"]},{"w":"hydrodistillation","d":"A method of extracting essential oils from plant material by boiling the plant matter directly in water so that steam carries the volatile oils into a condenser for collection.","s":"The herbalist extracted lavender essential oil through hydrodistillation, boiling the plant material directly in water.","p":"hy-droh-dis-tih-LAY-shun","o":"Greek","y":9,"bp":30,"sy":"hy.drodis.til.la.tion","ps":"noun","t":["botany","culinary","ogreek"]},{"w":"hydrodistilled","d":"Describing a substance, especially an essential oil or extract, that has been obtained through the process of hydrodistillation, in which plant material is boiled in water to release its volatile compounds.","s":"The label stated that the rose water was hydrodistilled, ensuring a pure and natural extraction process.","p":"hy-droh-dis-TILD","o":"Greek","y":9,"bp":26,"sy":"hy.drodis.tilled","ps":"adjective","t":["botany","culinary","ogreek"]},{"w":"hydrodynamometer","d":"An instrument used to measure the power or force of flowing water, typically by calculating the energy produced by a water current or the thrust of a water-driven system.","s":"Engineers used a hydrodynamometer to precisely measure the power output of the new water-driven turbine.","p":"hy-droh-dy-nuh-MOM-ih-ter","o":"Greek","y":9,"bp":30,"sy":"hy.dro.dy.namome.ter","ps":"noun","t":["physics","music","numbers","ogreek"]},{"w":"hydroengineering","d":"The branch of engineering that deals with the design, construction, and management of systems that control or use water, such as dams, canals, and irrigation networks.","s":"The hydroengineering project aimed to build a network of canals to prevent seasonal flooding in the delta.","p":"HY-droh-en-jih-NEER-ing","o":"Greek","y":9,"bp":30,"sy":"hy.dro.engi.neer.ing","ps":"noun","t":["waterways","tools","ogreek"]},{"w":"hydroentangle","d":"To bond or interlock fibers together using high-pressure jets of water, a process used in making nonwoven fabrics.","s":"Manufacturers hydroentangle synthetic fibers using high-pressure water jets to bond them without adhesives.","p":"HY-droh-en-TANG-gul","o":"Greek","y":9,"bp":26,"sy":"hy.droen.tan.gle","ps":"verb","t":["fabrics","ogreek"]},{"w":"hydroentanglement","d":"A manufacturing process in which high-pressure water jets are used to entangle and bond fibers together to create nonwoven textile materials.","s":"The nonwoven fabric was produced through hydroentanglement, giving it both strength and softness without stitching.","p":"HY-droh-en-TANG-gul-ment","o":"Greek","y":9,"bp":30,"sy":"hy.droen.tan.gle.ment","ps":"noun","t":["fabrics","ogreek"]},{"w":"hydroferrocyanic","d":"Relating to or describing a compound formed from hydrogen, iron, and cyanide, especially hydrocyanic acid combined with iron, such as in Prussian blue chemistry.","s":"The hydroferrocyanic acid solution turned a deep blue color when it reacted with the iron compound.","p":"HY-droh-feh-roh-sy-AN-ik","o":"Greek","y":9,"bp":32,"sy":"hy.dro.fer.ro.cyan.ic","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hydrofluoric","d":"A powerful, extremely dangerous acid so corrosive it can even eat through glass.","s":"Hydrofluoric acid is so corrosive that it can etch glass, making it one of the most dangerous acids in a chemistry lab.","p":"HY-droh-floo-OR-ik","o":"Greek","y":6,"bp":38,"sy":"hy.droflu.o.ric","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hydrofluorocarbon","d":"a fluorocarbon emitted as a by-product of industrial manufacturing","s":"Scientists warned that hydrofluorocarbon emissions from old refrigerators were accelerating climate change.","p":"HY-droh-floo-or-oh-KAR-bon","o":"Greek","y":9,"bp":32,"sy":"hy.droflu.o.ro.car.bon","ps":"noun","t":["ogreek"]},{"w":"hydroformed","d":"Shaped or molded using the pressure of a liquid, typically water or oil, to force metal or other materials into a desired form.","s":"The bicycle frame was hydroformed using high-pressure water to shape the metal into a smooth curve.","p":"HY-droh-formd","o":"Greek","y":8,"bp":35,"sy":"hy.dro.formed","ps":"adjective","t":["physics","ogreek"]},{"w":"hydroforming","d":"A manufacturing technique in which high-pressure liquid is used to shape metal, plastic, or other materials into complex forms without traditional mechanical pressing.","s":"Hydroforming allows engineers to create complex metal shapes without cracking the material.","p":"HY-droh-FOR-ming","o":"Greek","y":7,"bp":38,"sy":"hy.dro.form.ing","ps":"noun","t":["festivals","ogreek"]},{"w":"hydrofracture","d":"The cracking or splitting of rock or earth caused by the pressure of water or other fluids injected underground, commonly used in oil and gas extraction.","s":"The geologist explained that hydrofracture occurs when water pressure splits rock deep underground.","p":"HY-droh-FRAK-chur","o":"Greek","y":9,"bp":25,"sy":"hy.drofrac.ture","ps":"noun","t":["minerals","ogreek"]},{"w":"hydrogamous","d":"Describing plants or organisms that are pollinated or fertilized by means of water rather than wind or insects.","s":"The hydrogamous water lily relies entirely on water currents to carry its pollen to other flowers.","p":"hy-DROG-uh-mus","o":"Greek","y":9,"bp":37,"sy":"hy.drog.a.mous","ps":"adjective","t":["insects","botany","weather","ogreek"]},{"w":"hydrogamy","d":"The process of pollination or fertilization in plants that occurs through the medium of water, as seen in many aquatic plants.","s":"Biologists studying hydrogamy discovered fascinating adaptations in aquatic plants that pollinate underwater.","p":"hy-DROG-uh-mee","o":"Greek","y":8,"bp":26,"sy":"hy.drogamy","ps":"noun","t":["marine","botany","ogreek"]},{"w":"hydrogenosome","d":"A membrane-bound organelle found in certain anaerobic microorganisms that produces hydrogen gas as a byproduct of energy metabolism.","s":"The tiny parasite contained a hydrogenosome, an organelle that helps it survive without oxygen.","p":"hy-DROJ-en-oh-sohm","o":"Greek","y":9,"bp":25,"sy":"hy.drogeno.some","ps":"noun","t":["chemistry","physics","ogreek"]},{"w":"hydrogeology","d":"The branch of geology that focuses on the distribution, movement, and properties of water found underground and in the soil, including the study of aquifers.","s":"The hydrogeology report helped city planners understand where underground water was flowing beneath the new park.","p":"HY-droh-jee-OL-oh-jee","o":"Greek","y":6,"bp":41,"sy":"hy.dro.ge.ol.o.gy","ps":"noun","t":["minerals","ogreek"]},{"w":"hydrograph","d":"A graph or chart that shows how the water level, flow rate, or discharge of a body of water changes over a period of time.","s":"The hydrograph showed a sharp spike in river flow right after the heavy rainstorm.","p":"HY-droh-graf","o":"Greek","y":7,"bp":29,"sy":"hy.dro.graph","ps":"noun","t":["time","ogreek"]},{"w":"hydrography","d":"the science of the measurement and description and mapping of the surface waters of the earth with special reference to navigation","s":"Sailors depend on accurate hydrography to navigate safely through shallow coastal waters.","p":"hy-DROG-ruh-fee","o":"Greek","y":6,"bp":37,"sy":"hy.drog.ra.phy","ps":"noun","t":["maps","numbers","ogreek"]},{"w":"hydrogravitational","d":"Relating to the combined effects of water and gravitational forces, especially as they influence the movement of water through landscapes or geological formations.","s":"The hydrogravitational forces in the planet's ocean affected how tides behaved near the shoreline.","p":"HY-droh-grav-ih-TAY-shun-ul","o":"Greek","y":9,"bp":33,"sy":"hy.dro.grav.i.ta.tion.al","ps":"adjective","t":["minerals","physics","ogreek"]},{"w":"hydrohalogenation","d":"A chemical reaction in which a hydrogen halide, such as hydrochloric or hydrobromic acid, is added across a double bond in an organic molecule.","s":"The chemistry teacher demonstrated hydrohalogenation by adding hydrogen chloride to a simple alkene.","p":"HY-droh-hal-oh-jen-AY-shun","o":"Greek","y":9,"bp":30,"sy":"hy.dro.halo.gena.tion","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrokinesis","d":"The study or application of the motion and energy of flowing water; also used in some contexts to describe the hypothetical ability to move water using mental power.","s":"In the fantasy novel, the hero's hydrokinesis allowed her to control ocean waves with her mind.","p":"HY-droh-kih-NEE-sis","o":"Greek","y":8,"bp":38,"sy":"hy.droki.ne.sis","ps":"noun","t":["physics","ogreek"]},{"w":"hydrolaccolith","d":"A dome-shaped geological formation similar to a laccolith but created by the pressure of water rather than magma pushing upward between rock layers.","s":"The geologist identified a hydrolaccolith beneath the frozen tundra, formed by trapped water pushing up the ground.","p":"HY-droh-LAK-oh-lith","o":"Greek","y":9,"bp":29,"sy":"hy.dro.lac.col.ith","ps":"noun","t":["minerals","buildings","ogreek"]},{"w":"hydrolipid","d":"A molecule or compound that contains both water-attracting (hydrophilic) and fat-based (lipid) components, often found in skin-care science and cell membrane studies.","s":"The skincare company advertised that its cream contained a hydrolipid complex to keep skin moist.","p":"HY-droh-LIP-id","o":"Greek","y":8,"bp":27,"sy":"hy.drolipid","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hydrologist","d":"a geologist skilled in hydrology","s":"The hydrologist measured the river's flow rate every morning to track seasonal changes.","p":"hy-DROL-oh-jist","o":"Greek","y":6,"bp":37,"sy":"hy.drol.o.gist","ps":"noun","t":["minerals","ogreek"]},{"w":"hydromagnesite","d":"A white mineral consisting of hydrated magnesium carbonate, found naturally in metamorphic rocks and used as a flame retardant and in industrial applications.","s":"Researchers found hydromagnesite crystals in the cave walls near the underground spring.","p":"HY-droh-MAG-neh-syt","o":"Greek","y":9,"bp":29,"sy":"hy.dro.mag.ne.site","ps":"noun","t":["minerals","ogreek"]},{"w":"hydrombobomkulite","d":"A rare hydrated mineral of uncertain or highly specific composition, named after its locality or discoverer and characterized by its water-bearing crystalline structure.","s":"The mineralogist was stunned to discover a sample of hydrombobomkulite, one of the rarest minerals on Earth.","p":"HY-drom-BOH-bom-kyoo-lyt","o":"Greek","y":9,"bp":27,"sy":"hy.drom.bobomkulite","ps":"noun","t":["chemistry","minerals","maps","character","eponyms","ogreek","epgreek"]},{"w":"hydrometallurgical","d":"Relating to hydrometallurgy, the process of extracting metals from ores using water-based chemical solutions rather than high-temperature smelting techniques.","s":"The hydrometallurgical process used acid solutions to extract copper from low-grade ore.","p":"HY-droh-met-uh-LUR-jih-kul","o":"Greek","y":9,"bp":32,"sy":"hy.dromet.al.lur.gi.cal","ps":"adjective","t":["chemistry","minerals","ogreek"]},{"w":"hydrometallurgically","d":"In a manner that involves or relates to hydrometallurgical processes, meaning by using aqueous chemical solutions to extract or process metals from ores.","s":"The gold was hydrometallurgically recovered, meaning water-based chemicals did the heavy lifting.","p":"HY-droh-met-uh-LUR-jih-kul-ee","o":"Greek","y":9,"bp":33,"sy":"hy.dromet.al.lur.gi.cal.ly","ps":"adverb","t":["chemistry","minerals","ogreek"]},{"w":"hydrometallurgy","d":"The branch of metallurgy that involves the use of aqueous chemistry, particularly water-based solutions, to extract and purify metals from their ores.","s":"Hydrometallurgy has become popular because it produces less air pollution than traditional smelting.","p":"HY-droh-MET-uh-lur-jee","o":"Greek","y":9,"bp":30,"sy":"hy.dromet.al.lur.gy","ps":"noun","t":["chemistry","minerals","ogreek"]},{"w":"hydrometeor","d":"Any atmospheric phenomenon or product consisting of water in liquid or solid form, such as rain, snow, hail, fog, or dew.","s":"Hail is a type of hydrometeor, since it forms when water freezes high in storm clouds.","p":"HY-droh-MEE-tee-or","o":"Greek","y":8,"bp":38,"sy":"hy.drom.e.te.or","ps":"noun","t":["weather","ogreek"]},{"w":"hydromethylation","d":"A chemical reaction in which a methyl group and a hydrogen atom are simultaneously added to an unsaturated organic compound using water-based or aqueous reagents.","s":"The chemist used hydromethylation to add a methyl group to the compound using a water-based reaction.","p":"HY-droh-meth-ih-LAY-shun","o":"Greek","y":9,"bp":29,"sy":"hy.dromethy.la.tion","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrometry","d":"the measurement of specific gravity","s":"The lab technician used hydrometry to determine the density of the mysterious liquid sample.","p":"hy-DROM-eh-tree","o":"Greek","y":8,"bp":30,"sy":"hy.drom.e.try","ps":"noun","t":["physics","numbers","ogreek"]},{"w":"hydromodification","d":"The alteration of a natural water system, such as a river or stream, through human activities like channelization, damming, or drainage changes, which affects water flow and habitats.","s":"The environmental report described how hydromodification of the stream had destroyed fish habitats.","p":"HY-droh-mod-ih-fih-KAY-shun","o":"Greek","y":9,"bp":33,"sy":"hy.dro.mod.i.fi.ca.tion","ps":"noun","t":["ecology","waterways","ogreek"]},{"w":"hydronephrosis","d":"accumulation of urine in the kidney because of an obstruction in the ureter","s":"The doctor found hydronephrosis on the ultrasound and immediately recommended surgery to unblock the ureter.","p":"HY-droh-neh-FROH-sis","o":"Greek","y":7,"bp":26,"sy":"hy.dronephro.sis","ps":"noun","t":["body","ogreek"]},{"w":"hydronym","d":"A proper name given to a body of water, such as a river, lake, or ocean; a subcategory of place names focused specifically on water features.","s":"The word 'Mississippi' is a famous hydronym, since its name refers to a great river.","p":"HY-droh-nim","o":"Greek","y":9,"bp":25,"sy":"hy.dronym","ps":"noun","t":["waterways","ogreek"]},{"w":"hydropedal","d":"Relating to or describing movement or locomotion that is powered by or performed through water, especially the pedaling motion used in water-based transport or exercise.","s":"The hydropedal attachment let the child pedal the paddleboat effortlessly across the lake.","p":"HY-droh-PED-ul","o":"Greek","y":8,"bp":29,"sy":"hy.drope.dal","ps":"adjective","t":["ogreek"]},{"w":"hydropelvis","d":"A medical condition in which fluid abnormally accumulates in the pelvis of the kidney or the pelvic cavity, often as a result of obstruction or inflammation.","s":"The medical scan revealed hydropelvis, a condition where fluid had built up in the pelvic region of the kidney.","p":"HY-droh-PEL-vis","o":"Greek","y":8,"bp":34,"sy":"hy.dropelvis","ps":"noun","t":["body","disease","ogreek"]},{"w":"hydrophlorone","d":"A chemical compound derived from phloroglucinol through a hydrogenation reaction, resulting in a reduced form used in organic chemistry research.","s":"The chemist isolated hydrophlorone from the bark extract during the water-based analysis.","p":"HY-droh-FLOR-ohn","o":"Greek","y":9,"bp":23,"sy":"hy.drophlorone","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrophytology","d":"The scientific study of aquatic plants, including their structure, growth, distribution, and relationship to the water environments in which they live.","s":"Her research in hydrophytology focused on how water plants survive in fast-moving streams.","p":"HY-droh-fy-TOL-oh-jee","o":"Greek","y":9,"bp":29,"sy":"hy.drophy.tol.o.gy","ps":"noun","t":["marine","botany","ecology","ogreek"]},{"w":"hydroplastic","d":"Describing a material, especially clay or soil, that becomes soft, moldable, or workable when water is added to it.","s":"The clay became hydroplastic when water was added, making it easy to mold into any shape.","p":"HY-droh-PLAS-tik","o":"Greek","y":8,"bp":36,"sy":"hy.droplas.tic","ps":"adjective","t":["ogreek"]},{"w":"hydropneumatic","d":"Relating to a system or device that uses both water and compressed air together to generate force, cushioning, or mechanical action.","s":"The hydropneumatic suspension system on the luxury car used both fluid and air to absorb road bumps.","p":"HY-droh-noo-MAT-ik","o":"Greek","y":9,"bp":29,"sy":"hy.drop.neu.mat.ic","ps":"adjective","t":["physics","household","tools","ogreek"]},{"w":"hydropneumothorax","d":"A medical condition in which both fluid and air are abnormally present in the pleural cavity surrounding the lungs, often causing difficulty breathing.","s":"The emergency physician diagnosed hydropneumothorax after both fluid and air appeared in the chest cavity on the X-ray.","p":"HY-droh-noo-moh-THOR-aks","o":"Greek","y":9,"bp":32,"sy":"hy.drop.neu.moth.o.rax","ps":"noun","t":["body","ogreek"]},{"w":"hydropower","d":"Electrical or mechanical energy generated by harnessing the force or flow of moving water, typically through turbines in dams or rivers.","s":"The small town was fully powered by hydropower generated from the river running through the valley.","p":"HEYE-droh-pow-r","o":"Greek","y":5,"bp":29,"sy":"hhay.drow.paw.r","ps":"noun","t":["physics","waterways","ogreek"]},{"w":"hydrosalpinx","d":"A medical condition in which a fallopian tube becomes blocked and filled with watery fluid, often as a result of infection or inflammation.","s":"The doctor explained that hydrosalpinx occurs when fluid becomes trapped in a blocked fallopian tube.","p":"heye-droh-SAL-pinks","o":"Greek","y":8,"bp":36,"sy":"hy.dros.alpinx","ps":"noun","t":["body","disease","ogreek"]},{"w":"hydrosalt","d":"A chemical salt compound that contains water molecules as part of its structure, or a salt derived from a reaction involving water.","s":"The chemist dissolved the hydrosalt in warm water to study how it releases ions.","p":"HEYE-droh-sawlt","o":"Greek","y":8,"bp":28,"sy":"hy.dros.alt","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydroscience","d":"The broad field of scientific study that focuses on water, including its properties, distribution, movement, and interactions with the environment.","s":"Students interested in hydroscience can study rivers, oceans, and groundwater all in one field.","p":"HEYE-droh-seye-ents","o":"Greek","y":9,"bp":36,"sy":"hy.dro.science","ps":"noun","t":["ecology","ogreek"]},{"w":"hydroscientist","d":"A scientist who specializes in the study of water, its properties, and its effects on the natural world and human activities.","s":"The hydroscientist spent weeks collecting water samples from the flooded farmland.","p":"heye-droh-SEYE-en-tist","o":"Greek","y":9,"bp":29,"sy":"hy.dro.sci.en.tist","ps":"noun","t":["ogreek"]},{"w":"hydroseed","d":"To plant grass or other vegetation by spraying a mixture of seeds, water, and fertilizer onto a surface, often used on slopes or large areas.","s":"Workers used a hose to hydroseed the hillside with a mixture of grass seeds, water, and mulch.","p":"HEYE-droh-seed","o":"Greek","y":8,"bp":26,"sy":"hy.droseed","ps":"verb","t":["botany","farming","ogreek"]},{"w":"hydrosere","d":"An ecological succession of plant communities that begins in a water environment and gradually transitions toward drier, more stable land conditions over time.","s":"The biology class traced the hydrosere from open pond to dense woodland over thousands of years.","p":"HEYE-droh-seer","o":"Greek","y":9,"bp":26,"sy":"hy.drosere","ps":"noun","t":["botany","ecology","time","ogreek"]},{"w":"hydroskeletal","d":"Relating to a hydroskeleton, a body-support system in which fluid pressure inside soft-bodied animals provides structural rigidity and enables movement.","s":"The worm's hydroskeletal system allowed it to burrow through soil using fluid pressure instead of bones.","p":"heye-droh-SKEL-ih-tul","o":"Greek","y":9,"bp":25,"sy":"hy.droskele.tal","ps":"adjective","t":["animals","ogreek"]},{"w":"hydroskeleton","d":"A support structure found in soft-bodied invertebrates, such as worms and jellyfish, in which pressurized internal fluid acts as a skeleton to maintain body shape and aid movement.","s":"A jellyfish relies on its hydroskeleton to maintain shape as it pulses through the ocean.","p":"heye-droh-SKEL-ih-tun","o":"Greek","y":9,"bp":25,"sy":"hy.droskele.ton","ps":"noun","t":["marine","ogreek"]},{"w":"hydrosol","d":"A colloid in which water is the liquid medium and tiny solid or liquid particles are suspended throughout it, similar to a very fine mixture that does not settle.","s":"The chemist prepared a hydrosol by dispersing tiny gold particles evenly throughout water.","p":"HEYE-druh-sah-l","o":"Greek","y":7,"bp":27,"sy":"hhay.drah.saa.l","ps":"noun","t":["physics","ogreek"]},{"w":"hydrosolubility","d":"The degree or capacity of a substance to dissolve in water; a measure of how readily a compound will break apart and mix completely into a water-based solution.","s":"Scientists tested the hydrosolubility of the new medicine to see how well it dissolved in water.","p":"heye-droh-sol-yoo-BIL-ih-tee","o":"Greek","y":9,"bp":31,"sy":"hy.drosol.u.bil.i.ty","ps":"noun","t":["chemistry","numbers","ogreek"]},{"w":"hydrosoluble","d":"Capable of being dissolved in water; describing a substance that readily mixes with and breaks down in water to form a uniform solution.","s":"The hydrosoluble vitamin dissolves quickly when stirred into a glass of water.","p":"heye-droh-SOL-yoo-bul","o":"Greek","y":9,"bp":38,"sy":"hy.drosol.u.ble","ps":"adjective","t":["ogreek"]},{"w":"hydrostatic","d":"relating to fluids at rest or to the pressures they exert or transmit","p":"heye-droh-STAT-ik","o":"Greek","y":5,"bp":37,"sy":"hy.dro.stat.ic","ps":"adjective","t":["ogreek"]},{"w":"hydrostationary","d":"Describing a body of water or fluid system that remains in a fixed, stationary state without flowing or circulating, maintaining equilibrium pressure throughout.","s":"The hydrostationary equilibrium of the underground lake had remained undisturbed for centuries.","p":"heye-droh-STAY-shuh-nehr-ee","o":"Greek","y":9,"bp":30,"sy":"hy.dro.sta.tion.ary","ps":"adjective","t":["ogreek"]},{"w":"hydrostratigraphic","d":"Relating to hydrostratigraphy, the study and classification of subsurface rock or sediment layers based on their water-bearing properties and groundwater characteristics.","s":"The hydrostratigraphic map revealed which rock layers could store drinkable groundwater.","p":"heye-droh-strat-ih-GRAF-ik","o":"Greek","y":9,"bp":30,"sy":"hy.dros.trati.graph.ic","ps":"adjective","t":["minerals","maps","ogreek"]},{"w":"hydrostratigraphy","d":"The branch of geology and hydrology that examines and maps underground rock and sediment layers according to their ability to store, transmit, or block the flow of groundwater.","s":"Using hydrostratigraphy, geologists identified the best location to drill a new water well.","p":"heye-droh-struh-TIG-ruh-fee","o":"Greek","y":9,"bp":30,"sy":"hy.dros.tratig.ra.phy","ps":"noun","t":["minerals","maps","ogreek"]},{"w":"hydrotellurate","d":"A chemical salt or ester derived from telluric acid combined with water or hydrogen, containing tellurium in one of its oxidized forms along with water molecules.","s":"The lab notebook described hydrotellurate as an unstable compound formed with tellurium and water.","p":"heye-droh-TEL-yuh-rayt","o":"Greek","y":9,"bp":27,"sy":"hy.drotel.lu.rate","ps":"noun","t":["chemistry","ogreek"]},{"w":"hydrotelluric","d":"Relating to or describing a compound of hydrogen and tellurium, particularly hydro­telluric acid, which is a poisonous gas dissolved in water.","s":"The research paper explained that hydrotelluric acid is rarely encountered outside advanced chemistry labs.","p":"heye-droh-teh-LOOR-ik","o":"Greek","y":9,"bp":25,"sy":"hy.drotel.luric","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hydrotheca","d":"A cup-shaped or tubular protective covering made of a hard material that surrounds and shelters the feeding polyp of a colonial hydrozoan animal.","s":"Under the microscope, the delicate hydrotheca sheltered the soft feeding polyp of the hydroid colony.","p":"heye-droh-THEE-kuh","o":"Greek","y":9,"bp":29,"sy":"hy.drothe.ca","ps":"noun","t":["animals","ogreek"]},{"w":"hydrotherapeutic","d":"Relating to hydrotherapy, the use of water in various forms — such as baths, showers, or compresses — for the treatment of physical injuries, pain, or illness.","s":"The hydrotherapeutic pool at the clinic helped injured athletes recover through gentle water exercises.","p":"heye-droh-thehr-uh-PYOO-tik","o":"Greek","y":9,"bp":30,"sy":"hy.drother.a.peu.tic","ps":"adjective","t":["disease","ogreek"]},{"w":"hydrothermal","d":"Relating to the action of hot water within or on the surface of the Earth, especially as it relates to the formation of minerals or deep-sea vents.","s":"Strange tube worms thrive near hydrothermal vents on the deep ocean floor.","p":"heye-droh-THER-muh-l","o":"Greek","y":5,"bp":38,"sy":"hhay.drow.ther.mah.l","ps":"adjective","t":["minerals","waterways","ogreek"]},{"w":"hydrothermally","d":"In a manner relating to or produced by hot water activity within the Earth's crust, as in the formation of minerals or geological features through hot water processes.","s":"The mineral crystals were formed hydrothermally when hot water forced its way through cracks in the rock.","p":"heye-droh-THER-muh-lee","o":"Greek","y":9,"bp":27,"sy":"hy.drother.mal.ly","ps":"adverb","t":["minerals","ogreek"]},{"w":"hydrotropic","d":"Relating to or exhibiting hydrotropism, the tendency of plant roots or other organisms to grow or move in response to the presence or direction of water.","s":"The hydrotropic roots curved sharply toward the buried water pipe beneath the garden.","p":"heye-droh-TROP-ik","o":"Greek","y":8,"bp":35,"sy":"hy.drotrop.ic","ps":"adjective","t":["botany","ogreek"]},{"w":"hydrotropism","d":"The growth movement of a plant organ, especially roots, toward or away from a source of water in response to differences in moisture concentration in the surrounding environment.","s":"Hydrotropism causes plant roots to grow toward moisture even when light pulls the stem upward.","p":"heye-DROT-ruh-piz-um","o":"Greek","y":8,"bp":35,"sy":"hy.drotropism","ps":"noun","t":["botany","ecology","music","ogreek"]},{"w":"hydrovolcanic","d":"Relating to volcanic activity that involves a significant interaction between magma or lava and water, often producing explosive steam-driven eruptions.","s":"The hydrovolcanic explosion sent ash and steam miles into the sky when lava met the sea.","p":"heye-droh-vol-KAN-ik","o":"Greek","y":9,"bp":26,"sy":"hy.dro.vol.canic","ps":"adjective","t":["ogreek"]},{"w":"hydrowoodwardite","d":"A rare hydrated copper-aluminum sulfate mineral that is the water-bearing form of woodwardite, belonging to the group of layered double hydroxide minerals.","s":"The mineralogist identified a rare sample of hydrowoodwardite in the collection from a copper mine.","p":"heye-droh-WUD-werd-eyet","o":"Greek","y":9,"bp":26,"sy":"hydrowood.wardite","ps":"noun","t":["chemistry","minerals","maps","ogreek"]},{"w":"hydroxanthic","d":"Relating to or describing a chemical compound that contains both a hydroxyl group and a xanthic or xanthate component, typically found in certain organic sulfur-based compounds.","s":"The chemist noted that the hydroxanthic compound turned bright yellow when exposed to the reagent.","p":"heye-droks-AN-thik","o":"Greek","y":8,"bp":39,"sy":"hy.drox.an.th.ic","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hydroxystearic","d":"Describing a fatty acid with extra oxygen-hydrogen groups added, used in smooth cosmetics.","s":"Hydroxystearic acid is used in some cosmetics to give creams a smooth, rich texture.","p":"heye-drok-see-steer-EE-ik","o":"Greek","y":9,"bp":27,"sy":"hy.drox.ys.tearic","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hydruret","d":"An archaic or historical chemical term for a compound of hydrogen with another element, equivalent to what modern chemistry calls a hydride.","s":"The old chemistry text referred to a hydruret as what we now call a simple hydride compound.","p":"HEYE-druh-ret","o":"Greek","y":8,"bp":25,"sy":"hy.druret","ps":"noun","t":["chemistry","ogreek"]},{"w":"hyetal","d":"Relating to rainfall or precipitation; used to describe patterns, regions, or measurements associated with rain distribution across an area or time period.","s":"The meteorologist studied hyetal patterns to understand how rainfall varied across the mountain range.","p":"HEYE-ih-tul","o":"Greek","y":8,"bp":16,"ps":"adjective","t":["weather","numbers","time","ogreek"]},{"w":"hygrophyte","d":"a plant that grows in a moist habitat","s":"Cattails are a classic hygrophyte, thriving in the soggy edges of ponds and marshes.","p":"HEYE-groh-feyet","o":"Greek","y":9,"bp":29,"sy":"hy.gro.phyte","ps":"noun","t":["botany","ecology","ogreek"]},{"w":"hygroscope","d":"hygrometer that shows variations in the relative humidity of the atmosphere","s":"The antique hygroscope on the wall changed color to warn sailors of approaching humid weather.","p":"HEYE-groh-skohp","o":"Greek","y":9,"bp":29,"sy":"hy.gro.scope","ps":"noun","t":["weather","ogreek"]},{"w":"hygrothermal","d":"Relating to the combined effects of heat and moisture on materials, environments, or organisms, particularly regarding how these factors together cause stress or degradation.","s":"Hygrothermal stress from repeated wet-dry cycles caused the old wooden beams to crack over time.","p":"heye-groh-THER-mul","o":"Greek","y":8,"bp":36,"sy":"hy.grother.mal","ps":"adjective","t":["ecology","ogreek"]},{"w":"hylism","d":"A philosophical doctrine holding that matter is the fundamental substance of all reality, and that all existence, including mind and spirit, can be explained in terms of physical matter.","s":"The philosophy student explained hylism as the belief that matter is the foundation of all existence.","p":"HEYE-liz-um","o":"Greek","y":8,"bp":16,"ps":"noun","t":["logic","ogreek"]},{"w":"Hyllus","d":"In Greek mythology, the eldest son of the hero Heracles and Deianira, who became a leader of the Heraclidae and attempted to reclaim his father's ancestral lands in the Peloponnese.","s":"In Greek mythology, Hyllus was the brave son of Heracles who fought to reclaim his father's kingdom.","p":"HIL-us","o":"Greek","y":7,"bp":18,"sy":"hyl.lus","ps":"noun","t":["myth","kinship","ogreek"]},{"w":"hylopathy","d":"A philosophical theory proposing that all matter possesses some form of feeling, sensation, or capacity for experience, suggesting that even non-living material has an inner life.","s":"The philosopher argued that hylopathy explained why ancient thinkers believed rocks and rivers could feel.","p":"heye-LOP-uh-thee","o":"Greek","y":8,"bp":28,"sy":"hy.lopa.thy","ps":"noun","t":["logic","ogreek"]},{"w":"hylotheism","d":"A philosophical and theological belief that identifies God with matter or the physical universe itself, holding that the divine and the material world are one and the same.","s":"Hylotheism blurs the line between God and the physical world by treating matter itself as divine.","p":"heye-loh-THEE-iz-um","o":"Greek","y":8,"bp":29,"sy":"hy.lothe.ism","ps":"noun","t":["astronomy","logic","ogreek"]},{"w":"hypapophysis","d":"A downward-projecting bony process or outgrowth on the underside of a vertebra, serving as an attachment point for muscles or providing additional structural support to the spine.","s":"The paleontologist identified the hypapophysis on the fossil vertebra, confirming it belonged to a large snake.","p":"heye-puh-POF-ih-sis","o":"Greek","y":8,"bp":38,"sy":"hy.pa.poph.ysis","ps":"noun","t":["body","numbers","ogreek"]},{"w":"hyparterial","d":"Located or occurring beneath an artery, especially referring to the bronchus that branches off below the pulmonary artery in the lung.","s":"The anatomy professor pointed out the hyparterial bronchus located below the pulmonary artery in the lung model.","p":"heye-par-TEER-ee-ul","o":"Greek","y":8,"bp":38,"sy":"hy.par.te.ri.al","ps":"adjective","t":["body","ogreek"]},{"w":"hypaspist","d":"A shield-bearer or elite infantry soldier in the ancient Macedonian army, especially those who served under Alexander the Great as a personal guard.","s":"The hypaspist marched beside Alexander the Great, carrying his shield and guarding his flank in battle.","p":"heye-PAS-pist","o":"Greek","y":8,"bp":26,"sy":"hy.paspist","ps":"noun","t":["war","ancient","ogreek"]},{"w":"hyperabundance","d":"An extremely excessive or overflowing amount of something, far beyond what is needed or considered normal.","s":"The hyperabundance of jellyfish in the bay was linked to warming ocean temperatures and fewer predators.","p":"heye-per-uh-BUN-dunts","o":"Greek","y":9,"bp":27,"sy":"hy.per.abun.dance","ps":"noun","t":["ogreek"]},{"w":"hyperabundant","d":"Present in an extremely excessive quantity, far surpassing what is sufficient or expected.","s":"Dandelions became hyperabundant in the park after the groundskeepers stopped mowing in early spring.","p":"heye-per-uh-BUN-dunt","o":"Greek","y":9,"bp":26,"sy":"hy.per.abun.dant","ps":"adjective","t":["ogreek"]},{"w":"hyperaccreting","d":"Accumulating or growing at an extremely rapid and excessive rate, often used in astrophysics to describe a black hole or star gaining mass far above normal levels.","s":"The scientists observed the black hole hyperaccreting material at a rate that stunned the entire research team.","p":"heye-per-uh-KREET-ing","o":"Greek","y":9,"bp":29,"sy":"hy.per.ac.cret.ing","ps":"adjective","t":["astronomy","ogreek"]},{"w":"hyperaccretion","d":"The process of accumulating matter at an extraordinarily high rate, especially used in astrophysics to describe massive objects like black holes gaining mass at extreme speeds.","s":"The study of hyperaccretion around neutron stars helped astronomers understand how stellar masses rapidly increase.","p":"heye-per-uh-KREE-shun","o":"Greek","y":9,"bp":29,"sy":"hy.per.ac.cre.tion","ps":"noun","t":["ogreek"]},{"w":"hyperacetylate","d":"To add an abnormally high number of acetyl chemical groups to a molecule, especially to histone proteins in the cell nucleus, which can affect gene activity.","s":"Researchers found that certain drugs can hyperacetylate proteins, dramatically altering how genes are expressed.","p":"heye-per-uh-SEE-tuh-layt","o":"Greek","y":9,"bp":27,"sy":"hy.per.acety.late","ps":"verb","t":["chemistry","numbers","ogreek"]},{"w":"hyperacetylation","d":"The process or result of adding an excessive number of acetyl groups to a molecule, particularly histones, often leading to increased gene expression.","s":"The hyperacetylation of histone proteins was linked to unusually high levels of gene activity in the cancer cells.","p":"heye-per-uh-see-tuh-LAY-shun","o":"Greek","y":9,"bp":30,"sy":"hy.per.acety.la.tion","ps":"noun","t":["chemistry","numbers","ogreek"]},{"w":"hyperactivate","d":"To stimulate or trigger something to a level of activity far beyond its normal or expected range, such as a cell, immune response, or system.","s":"Too much sugar can hyperactivate certain brain pathways, making it hard to focus or calm down.","p":"heye-per-AK-tuh-vayt","o":"Greek","y":9,"bp":28,"sy":"hy.per.ac.ti.vate","ps":"verb","t":["ogreek"]},{"w":"hyperactivated","d":"Brought to a state of activity that is far beyond normal levels, often describing a biological system or immune response that is working in overdrive.","s":"The immune cells were hyperactivated after the injection, causing the patient's fever to spike dangerously high.","p":"heye-per-AK-tuh-vay-tid","o":"Greek","y":9,"bp":30,"sy":"hy.per.ac.ti.vat.ed","ps":"adjective","t":["ogreek"]},{"w":"hyperactivism","d":"An extreme or excessive form of activism in which a person or group pursues social or political change with relentless, intense, and sometimes overwhelming energy.","s":"The politician was known for her hyperactivism, launching a new campaign or protest almost every single day.","p":"heye-per-AK-tuh-viz-um","o":"Greek","y":9,"bp":26,"sy":"hy.per.ac.tivism","ps":"noun","t":["physics","politics","ogreek"]},{"w":"hyperaggressive","d":"Displaying an extreme or excessive level of aggression, hostility, or forcefulness that goes far beyond what is considered normal or acceptable behavior.","s":"The coach warned that their hyperaggressive playing style would likely result in multiple penalties during the championship.","p":"heye-per-uh-GRES-iv","o":"Greek","y":9,"bp":30,"sy":"hy.per.ag.gres.sive","ps":"adjective","t":["ogreek"]},{"w":"hyperaldosteronism","d":"a condition caused by overproduction of aldosterone","s":"The doctor diagnosed the patient with hyperaldosteronism after noticing dangerously high blood pressure and low potassium levels.","p":"heye-per-al-dos-TER-uh-niz-um","o":"Greek","y":8,"bp":32,"sy":"hy.per.al.dos.tero.nism","ps":"noun","t":["ogreek"]},{"w":"hyperallergic","d":"Relating to or exhibiting an extreme degree of allergic sensitivity, in which a person reacts strongly to substances that cause only mild or no reaction in most people.","s":"The hyperallergic child had to be kept away from pollen, dust, pet dander, and dozens of common foods.","p":"heye-per-uh-LER-jik","o":"Greek","y":8,"bp":28,"sy":"hy.per.al.ler.gic","ps":"adjective","t":["disease","ogreek"]},{"w":"hyperaminoacidemia","d":"A medical condition in which there is an abnormally high concentration of amino acids circulating in the bloodstream, which can indicate metabolic disorders.","s":"The newborn's blood test revealed hyperaminoacidemia, indicating a rare metabolic disorder affecting protein breakdown.","p":"heye-per-uh-mee-noh-as-ih-DEE-mee-uh","o":"Greek","y":9,"bp":27,"sy":"hy.per.aminoacidemia","ps":"noun","t":["body","disease","chemistry","ogreek"]},{"w":"hyperandrogenic","d":"Relating to or characterized by abnormally high levels of androgens, the male sex hormones, in the body, which can affect both males and females.","s":"The hyperandrogenic athlete underwent testing to ensure her natural hormone levels met competition guidelines.","p":"heye-per-an-droh-JEN-ik","o":"Greek","y":9,"bp":30,"sy":"hy.per.an.dro.genic","ps":"adjective","t":["character","ogreek"]},{"w":"hyperapophysis","d":"An unusually large or overdeveloped bony outgrowth projecting from a vertebra, beyond what is considered a normal apophysis in skeletal anatomy.","s":"The paleontologist identified the dinosaur species by the unusually large hyperapophysis on each vertebra.","p":"heye-per-uh-POF-ih-sis","o":"Greek","y":9,"bp":27,"sy":"hy.per.apoph.ysis","ps":"noun","t":["body","ogreek"]},{"w":"hyperarid","d":"Describing a climate or region that is extremely dry, receiving almost no rainfall and supporting very little or no plant or animal life.","s":"The Atacama Desert is considered hyperarid because some regions receive almost no measurable rainfall for decades.","p":"heye-per-AIR-id","o":"Greek","y":8,"bp":28,"sy":"hy.per.arid","ps":"adjective","t":["animals","botany","weather","ogreek"]},{"w":"hyperarithmetic","d":"In mathematical logic, relating to a level of complexity or definability that goes beyond ordinary arithmetic, involving infinite computations or higher-order recursion.","s":"The professor introduced hyperarithmetic theory to explain mathematical operations that go beyond ordinary computability.","p":"heye-per-uh-RITH-meh-tik","o":"Greek","y":9,"bp":28,"sy":"hy.per.arith.metic","ps":"adjective","t":["logic","numbers","ogreek"]},{"w":"hyperaroused","d":"In a state of extreme physiological or psychological arousal, often associated with anxiety, trauma, or heightened alertness far above normal levels.","s":"After the near-accident, she remained hyperaroused for hours, unable to sleep or stop shaking.","p":"heye-per-uh-ROUZD","o":"Greek","y":9,"bp":36,"sy":"hy.per.aroused","ps":"adjective","t":["emotions","ogreek"]},{"w":"hyperassertive","d":"Displaying an excessively forceful or dominant manner of expressing opinions and demands, going beyond healthy confidence into pushy or overbearing behavior.","s":"His hyperassertive negotiating style often made deals collapse because he refused to compromise on even minor points.","p":"heye-per-uh-SER-tiv","o":"Greek","y":9,"bp":26,"sy":"hy.per.assertive","ps":"adjective","t":["ogreek"]},{"w":"hyperathletic","d":"Possessing or displaying an extreme level of athletic ability, physical strength, or sporting talent that far exceeds what is considered typical or average.","s":"The hyperathletic student competed in four sports simultaneously and still maintained straight A's throughout the year.","p":"heye-per-ath-LET-ik","o":"Greek","y":9,"bp":28,"sy":"hy.per.ath.let.ic","ps":"adjective","t":["sports","ogreek"]},{"w":"hyperauthentic","d":"Characterized by an extreme or exaggerated degree of authenticity, sometimes to the point of being self-conscious or performative in one's genuineness.","s":"Critics called her memoir hyperauthentic because every page revealed raw, almost uncomfortably honest personal details.","p":"heye-per-aw-THEN-tik","o":"Greek","y":9,"bp":27,"sy":"hy.per.authen.tic","ps":"adjective","t":["character","ogreek"]},{"w":"hyperaware","d":"Extremely or intensely conscious of one's surroundings, sensations, or circumstances, often to a degree that can cause anxiety or sensory overload.","s":"Growing up in a busy city made him hyperaware of every sound and movement around him at all times.","p":"heye-per-uh-WAIR","o":"Greek","y":8,"bp":29,"sy":"hy.per.aware","ps":"adjective","t":["emotions","ogreek"]},{"w":"hyperawareness","d":"The state or quality of being intensely and excessively alert to one's surroundings, feelings, or details, often beyond what is comfortable or necessary.","s":"Her hyperawareness of social cues made her both an excellent listener and an anxious one at parties.","p":"heye-per-uh-WAIR-nes","o":"Greek","y":9,"bp":27,"sy":"hy.per.aware.ness","ps":"noun","t":["ogreek"]},{"w":"hyperbaric","d":"Relating to or involving gas pressure that is greater than normal atmospheric pressure, often used in medical treatments that deliver pure oxygen at high pressure.","s":"Divers who surface too quickly are sometimes treated in a hyperbaric chamber to prevent decompression sickness.","p":"heye-per-BAH-rih-k","o":"Greek","y":5,"bp":36,"sy":"hhay.per.baa.rih.k","ps":"adjective","t":["body","chemistry","ogreek"]},{"w":"hyperbasophilia","d":"An abnormal or excessive affinity of cells or tissues for basic dyes, indicating an overabundance of acidic components such as RNA within those cells.","s":"The lab report noted hyperbasophilia in the blood sample, suggesting the cells were staining far more intensely than normal.","p":"heye-per-bay-soh-FIL-ee-uh","o":"Greek","y":9,"bp":30,"sy":"hy.per.ba.sophil.ia","ps":"noun","t":["body","ogreek"]},{"w":"hyperbeat","d":"An extremely fast or intensified rhythmic beat, especially in music genres that feature rapid tempos designed to produce high-energy excitement in listeners.","s":"The DJ's hyperbeat track was so fast and intense that the entire crowd was breathless after just one minute.","p":"HEYE-per-beet","o":"Greek","y":8,"bp":28,"sy":"hy.per.beat","ps":"noun","t":["physics","music","ogreek"]},{"w":"hyperbenthic","d":"Relating to or living in the zone of water just above the ocean floor, occupied by organisms that hover or swim just above the seafloor sediment.","s":"The hyperbenthic zone just above the ocean floor teems with tiny creatures that feed on particles drifting down from above.","p":"heye-per-BEN-thik","o":"Greek","y":8,"bp":39,"sy":"hy.per.ben.th.ic","ps":"adjective","t":["minerals","waterways","ogreek"]},{"w":"hyperbilirubinemia","d":"abnormally high amounts of bile pigment (bilirubin) in the blood","s":"Newborn jaundice is often caused by hyperbilirubinemia, where excess bilirubin turns the baby's skin yellow.","p":"heye-per-bil-ih-roo-bih-NEE-mee-uh","o":"Greek","y":9,"bp":30,"sy":"hy.per.biliru.bine.mia","ps":"noun","t":["body","painting","ogreek"]},{"w":"hypercaffeinated","d":"Containing an extremely high level of caffeine, or describing a person who has consumed so much caffeine that they exhibit intense restlessness and nervous energy.","s":"After three energy drinks and two espressos, he was so hypercaffeinated that he couldn't stop tapping his feet.","p":"heye-per-KAF-ih-nay-tid","o":"Greek","y":9,"bp":30,"sy":"hy.per.caf.feinat.ed","ps":"adjective","t":["physics","ogreek"]},{"w":"hypercapitalist","d":"A person who supports or practices an extreme form of capitalism, favoring minimal regulation, maximum privatization, and the aggressive pursuit of profit above all else.","s":"The documentary criticized the hypercapitalist policies that allowed a handful of billionaires to control most of the nation's resources.","p":"heye-per-KAP-ih-tul-ist","o":"Greek","y":9,"bp":31,"sy":"hy.per.cap.i.tal.ist","ps":"noun","t":["economy","ogreek"]},{"w":"hypercapnia","d":"the physical condition of having the presence of an abnormally high level of carbon dioxide in the circulating blood","s":"Patients with severe asthma can develop hypercapnia when they cannot exhale enough carbon dioxide from their lungs.","p":"heye-per-KAP-nee-uh","o":"Greek","y":8,"bp":37,"sy":"hy.per.cap.nia","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hypercarbia","d":"the physical condition of having the presence of an abnormally high level of carbon dioxide in the circulating blood","s":"The anesthesiologist monitored the patient closely for signs of hypercarbia during the long surgical procedure.","p":"heye-per-KAR-bee-uh","o":"Greek","y":9,"bp":37,"sy":"hy.per.car.bia","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hypercarnivore","d":"An animal whose diet consists of more than seventy percent meat, relying almost entirely on other animals for nutrition rather than on plants or mixed sources.","s":"The great white shark is considered a hypercarnivore because more than seventy percent of its diet consists of other animals.","p":"heye-per-KAR-nih-vor","o":"Greek","y":9,"bp":29,"sy":"hy.per.car.ni.vore","ps":"noun","t":["animals","botany","numbers","ogreek"]},{"w":"hypercasual","d":"Describing an extremely simple style of mobile game or activity designed for very brief, effortless engagement, requiring almost no learning curve or commitment from the user.","s":"Hypercasual mobile games are designed to be learned in seconds and played during the shortest breaks in the day.","p":"heye-per-KAZH-oo-ul","o":"Greek","y":8,"bp":38,"sy":"hy.per.ca.su.al","ps":"adjective","t":["sports","ogreek"]},{"w":"hypercatabolic","d":"Relating to an abnormally high rate of catabolism, the process by which the body breaks down complex molecules for energy, often occurring during severe illness or injury.","s":"Severely burned patients often enter a hypercatabolic state, breaking down muscle and fat at an alarming rate.","p":"heye-per-kat-uh-BOL-ik","o":"Greek","y":9,"bp":27,"sy":"hy.per.catabol.ic","ps":"adjective","t":["disease","chemistry","physics","ogreek"]},{"w":"hypercatabolism","d":"An extreme or excessive breakdown of body tissues and molecules for energy, typically seen in critically ill patients whose bodies are consuming their own muscle and fat at a dangerous rate.","s":"During hypercatabolism following a major injury, the body burns through its own proteins just to survive.","p":"heye-per-kuh-TAB-uh-liz-um","o":"Greek","y":9,"bp":27,"sy":"hy.per.catabolism","ps":"noun","t":["body","chemistry","physics","ogreek"]},{"w":"hypercaution","d":"An excessive or extreme degree of caution that goes far beyond what a situation requires, often resulting in unnecessary hesitation, delay, or missed opportunities.","s":"The pilot's hypercaution led him to double-check every instrument three times before even taxiing down the runway.","p":"heye-per-KAW-shun","o":"Greek","y":8,"bp":38,"sy":"hy.per.cau.tion","ps":"noun","t":["ogreek"]},{"w":"hypercautious","d":"Extremely or excessively cautious; showing far more care and wariness than a situation typically requires.","s":"She was so hypercautious about germs that she wore gloves even while grocery shopping on a warm summer day.","p":"HY-per-KAW-shus","o":"Greek","y":9,"bp":26,"sy":"hy.per.cau.tious","ps":"adjective","t":["ogreek"]},{"w":"hypercellular","d":"Having an abnormally high number of cells; characterized by excessive cellular density or proliferation in a tissue or organism.","s":"The biopsy showed hypercellular bone marrow, indicating the body was producing blood cells at an abnormally high rate.","p":"HY-per-SEL-yoo-ler","o":"Greek","y":9,"bp":28,"sy":"hy.per.cel.lu.lar","ps":"adjective","t":["body","character","numbers","ogreek"]},{"w":"hyperchaotic","d":"Characterized by an extreme or overwhelming level of chaos; far beyond normal disorder or confusion.","s":"The kindergarten classroom after the birthday party was described by the exhausted teacher as completely hyperchaotic.","p":"HY-per-kay-OT-ik","o":"Greek","y":9,"bp":38,"sy":"hy.per.chaot.ic","ps":"adjective","t":["disease","character","ogreek"]},{"w":"hyperchlorhydria","d":"A medical condition in which the stomach produces an abnormally excessive amount of hydrochloric acid, which can cause discomfort, heartburn, and digestive problems.","s":"The gastroenterologist suspected hyperchlorhydria when the patient reported severe stomach pain and frequent acid reflux after every meal.","p":"HY-per-klor-HY-dree-uh","o":"Greek","y":9,"bp":29,"sy":"hy.per.chlorhy.dria","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hyperchloric","d":"Relating to or containing an abnormally high concentration of chlorine or chloric compounds; excessively chlorinated.","s":"The chemist handled the hyperchloric solution with extreme care because of its highly corrosive and reactive properties.","p":"HY-per-KLOR-ik","o":"Greek","y":9,"bp":38,"sy":"hy.per.chlo.ric","ps":"adjective","t":["ogreek"]},{"w":"hypercholesterolemia","d":"the presence of an abnormal amount of cholesterol in the cells and plasma of the blood; associated with the risk of atherosclerosis","s":"The doctor told the patient that his hypercholesterolemia put him at serious risk for heart disease.","p":"HY-per-kuh-les-ter-oh-LEE-mee-uh","o":"Greek","y":9,"bp":30,"sy":"hy.per.c.holes.terolemia","ps":"noun","t":["body","ogreek"]},{"w":"hyperchromatic","d":"Having an abnormally intense or excessive amount of color or pigmentation, especially referring to cell nuclei that stain more deeply than normal.","s":"Under the microscope, the hyperchromatic cells appeared much darker than the surrounding healthy tissue.","p":"HH AY2 P ER0 K R OW0 M AE1 T IH0 K","o":"Greek","y":9,"bp":29,"sy":"hy.per.chro.mat.ic","ps":"adjective","t":["painting","colors","ogreek"]},{"w":"hypercinnabar","d":"An intense, vivid shade of red that surpasses the brightness of ordinary cinnabar; an extremely bright scarlet or vermilion hue.","s":"The geologist found a vein of hypercinnabar that glowed with an even more intense red than ordinary cinnabar.","p":"HY-per-SIN-uh-bar","o":"Greek","y":9,"bp":25,"sy":"hy.per.cinnabar","ps":"noun","t":["colors","ogreek"]},{"w":"hypercivilized","d":"Excessively or extremely civilized; having reached such a high degree of cultural refinement that behavior becomes overly formal, rigid, or artificial.","s":"The satirist described the overly polite society as hypercivilized, where even sneezing required a written apology.","p":"HY-per-SIV-uh-lyzd","o":"Greek","y":9,"bp":29,"sy":"hy.per.civ.i.lized","ps":"adjective","t":["ogreek"]},{"w":"hyperclean","d":"Exceptionally or obsessively clean; maintained at a level of cleanliness far beyond what is ordinary or necessary.","s":"The hyperclean laboratory was so spotless that scientists had to wear full suits just to enter.","p":"HY-per-KLEEN","o":"Greek","y":8,"bp":29,"sy":"hy.per.clean","ps":"adjective","t":["ogreek"]},{"w":"hypercoagulability","d":"An abnormal medical condition in which the blood has an excessive tendency to clot, increasing the risk of dangerous blockages in blood vessels.","s":"Patients with hypercoagulability must take blood thinners to prevent dangerous clots from forming.","p":"HY-per-koh-ag-yoo-luh-BIL-ih-tee","o":"Greek","y":9,"bp":35,"sy":"hy.per.co.ag.u.la.bil.i.ty","ps":"noun","t":["body","seafaring","ogreek"]},{"w":"hypercoagulable","d":"Describing blood or a bodily state in which clotting occurs too readily or excessively, posing a risk of harmful blood clots.","s":"Her hypercoagulable blood condition meant the surgeon had to take extra precautions during the operation.","p":"HY-per-koh-AG-yoo-luh-bul","o":"Greek","y":9,"bp":33,"sy":"hy.per.co.ag.u.la.ble","ps":"adjective","t":["body","ogreek"]},{"w":"hypercoaster","d":"a roller coaster that goes up 200 feet or higher and can catapult riders from 0 to 70 mph in 4 seconds by motors originally designed to launch rockets","s":"The new hypercoaster at the amusement park launched riders from zero to seventy miles per hour in under three seconds.","p":"HY-per-KOH-ster","o":"Greek","y":8,"bp":38,"sy":"hy.per.coast.er","ps":"noun","t":["waterways","vehicles","ogreek"]},{"w":"hypercolumn","d":"A functional unit in the brain's visual cortex consisting of a group of neurons that together process all orientations and eye-dominance patterns for a specific region of the visual field.","s":"Neuroscientists study the hypercolumn in the visual cortex to understand how the brain processes lines and edges.","p":"HY-per-KOL-um","o":"Greek","y":8,"bp":37,"sy":"hy.per.col.umn","ps":"noun","t":["body","ogreek"]},{"w":"hypercommodified","d":"Describing something that has been turned into a commercial product or marketable commodity to an extreme and often problematic degree, stripping it of deeper cultural or personal value.","s":"Critics argued that traditional holidays had become hypercommodified, with stores selling decorations months in advance.","p":"HY-per-kuh-MOD-ih-fyd","o":"Greek","y":9,"bp":32,"sy":"hy.per.com.mod.i.fied","ps":"adjective","t":["economy","ogreek"]},{"w":"hypercompensation","d":"The act of going far beyond what is needed to make up for a perceived weakness, failure, or disadvantage, often to an excessive or counterproductive degree.","s":"His hypercompensation for his childhood shyness led him to become an over-the-top public speaker.","p":"HY-per-kom-pen-SAY-shun","o":"Greek","y":9,"bp":32,"sy":"hy.per.com.pen.sa.tion","ps":"noun","t":["ogreek"]},{"w":"hypercompetent","d":"Possessing skills, knowledge, and abilities far exceeding what is normally expected or required for a given task or role.","s":"The hypercompetent engineer solved in one afternoon a problem that had stumped the team for weeks.","p":"HY-per-KOM-peh-tent","o":"Greek","y":9,"bp":29,"sy":"hy.per.com.pe.tent","ps":"adjective","t":["logic","ogreek"]},{"w":"hypercompetitive","d":"Extremely or excessively competitive; driven by an intense desire to win or outperform others to a degree that goes well beyond normal rivalry.","s":"The hypercompetitive student turned every class discussion into a contest she was determined to win.","p":"HY-per-kum-PET-ih-tiv","o":"Greek","y":9,"bp":32,"sy":"hy.per.com.pet.i.tive","ps":"adjective","t":["ogreek"]},{"w":"hypercomputation","d":"A theoretical form of computation that goes beyond the limits of standard Turing machines, capable of solving problems that no conventional computer algorithm can solve.","s":"Theoretical scientists debate whether hypercomputation could ever solve problems that ordinary computers cannot.","p":"HY-per-kom-pyoo-TAY-shun","o":"Greek","y":9,"bp":32,"sy":"hy.per.com.pu.ta.tion","ps":"noun","t":["tools","ogreek"]},{"w":"hypercomputer","d":"A theoretical computing device that surpasses the capabilities of a standard Turing machine, able to perform calculations or solve problems beyond the reach of conventional computers.","s":"In the science fiction novel, a hypercomputer solved in seconds equations that would take humans centuries.","p":"HY-per-kum-PYOO-ter","o":"Greek","y":9,"bp":28,"sy":"hy.per.com.put.er","ps":"noun","t":["tools","ogreek"]},{"w":"hyperconfluent","d":"Describing a cell culture in which cells have grown so densely that they cover the entire available surface and begin to pile on top of one another, exceeding normal confluency.","s":"The cell culture was hyperconfluent, with cells packed so tightly there was no room left on the dish.","p":"HY-per-KON-floo-ent","o":"Greek","y":9,"bp":29,"sy":"hy.per.con.flu.ent","ps":"adjective","t":["ogreek"]},{"w":"hyperconifold","d":"In advanced mathematics and theoretical physics, a geometric space or manifold that generalizes the concept of a conifold to higher dimensions, exhibiting complex singularities.","s":"The mathematician sketched a hyperconifold on the board, trying to explain its strange multidimensional shape.","p":"HY-per-KOH-nih-fohld","o":"Greek","y":9,"bp":26,"sy":"hy.per.coni.fold","ps":"noun","t":["physics","numbers","ogreek"]},{"w":"hyperconnected","d":"Linked to an extremely large number of people, devices, or networks simultaneously, often through digital technology, creating constant and pervasive connectivity.","s":"The hyperconnected teenager had notifications pinging on five devices at the same time.","p":"HY-per-kuh-NEK-tid","o":"Greek","y":8,"bp":29,"sy":"hy.per.con.nect.ed","ps":"adjective","t":["tools","numbers","ogreek"]},{"w":"hyperconnectivity","d":"A state of extreme interconnection among people, devices, and systems, especially through digital networks, resulting in constant and far-reaching communication and data exchange.","s":"Researchers warn that hyperconnectivity can lead to anxiety when people feel they must respond to messages instantly.","p":"HY-per-kuh-nek-TIV-ih-tee","o":"Greek","y":9,"bp":33,"sy":"hy.per.con.nec.tiv.i.ty","ps":"noun","t":["tools","ogreek"]},{"w":"hyperconsumerism","d":"An extreme form of consumerism in which individuals or societies engage in excessive, compulsive, or unsustainable purchasing and consumption of goods far beyond genuine need.","s":"The documentary criticized hyperconsumerism, showing landfills overflowing with barely used electronics and clothing.","p":"HY-per-kun-SOO-mer-iz-um","o":"Greek","y":9,"bp":29,"sy":"hy.per.con.sumerism","ps":"noun","t":["ogreek"]},{"w":"hyperconsumerist","d":"A person who engages in extreme or excessive consumption of goods and products, often driven by culture, advertising, or compulsion rather than genuine need.","s":"The hyperconsumerist bought three of every new gadget even before reading the reviews.","p":"HY-per-kun-SOO-mer-ist","o":"Greek","y":9,"bp":29,"sy":"hy.per.con.sumerist","ps":"noun","t":["ogreek"]},{"w":"hyperconsumption","d":"The act or pattern of consuming goods, resources, or services at a rate far exceeding what is necessary or sustainable, often associated with modern consumer culture.","s":"The professor argued that hyperconsumption of single-use plastics was destroying ocean ecosystems.","p":"HY-per-kun-SUMP-shun","o":"Greek","y":9,"bp":30,"sy":"hy.per.con.sump.tion","ps":"noun","t":["ogreek"]},{"w":"hypercontractile","d":"Describing a muscle or tissue that contracts with abnormally excessive force or frequency beyond what is physiologically normal or healthy.","s":"The hypercontractile heart muscle was squeezing so forcefully that doctors worried about the patient's circulation.","p":"HY-per-kun-TRAK-tyl","o":"Greek","y":9,"bp":30,"sy":"hy.per.con.trac.tile","ps":"adjective","t":["body","physics","law","ogreek"]},{"w":"hypercontractility","d":"An abnormal physiological condition in which a muscle, especially the heart, contracts with excessive force or at an unusually high rate, potentially causing medical complications.","s":"The cardiologist noted hypercontractility in the left ventricle, which was pumping blood with excessive force.","p":"HY-per-kun-trak-TIL-ih-tee","o":"Greek","y":9,"bp":33,"sy":"hy.per.con.trac.til.i.ty","ps":"noun","t":["body","physics","law","ogreek"]},{"w":"hypercontrolled","d":"Subject to or exhibiting an extreme degree of control; managed, regulated, or restrained in a manner far beyond what is considered normal or necessary.","s":"The hypercontrolled environment of the space station left nothing to chance, with every variable carefully managed.","p":"HY-per-kun-TROHLD","o":"Greek","y":9,"bp":28,"sy":"hy.per.con.trolled","ps":"adjective","t":["ogreek"]},{"w":"hypercortisolism","d":"A medical condition characterized by abnormally high levels of the stress hormone cortisol in the body, leading to symptoms such as weight gain, high blood pressure, and weakened bones; also known as Cushing's syndrome.","s":"The patient's hypercortisolism caused weight gain, high blood pressure, and extreme fatigue.","p":"HY-per-KOR-tih-sol-iz-um","o":"Greek","y":9,"bp":30,"sy":"hy.per.cor.ti.solism","ps":"noun","t":["body","disease","character","ogreek"]},{"w":"hypercortisonemia","d":"A medical condition in which abnormally elevated levels of cortisone circulate in the bloodstream, potentially disrupting immune function and metabolism.","s":"Lab results confirmed hypercortisonemia, explaining the patient's unusual pattern of symptoms.","p":"HY-per-kor-tih-sohn-EE-mee-uh","o":"Greek","y":9,"bp":32,"sy":"hy.per.cor.ti.sone.mia","ps":"noun","t":["body","ogreek"]},{"w":"hypercreative","d":"Possessing or displaying an exceptionally high level of creativity; able to generate ideas, art, or solutions at an extraordinary and often prolific rate.","s":"The hypercreative designer filled three sketchbooks with ideas before settling on the perfect logo.","p":"HY-per-kree-AY-tiv","o":"Greek","y":9,"bp":26,"sy":"hy.per.cre.ative","ps":"adjective","t":["ogreek"]},{"w":"hypercreativity","d":"An exceptionally intense or prolific capacity for creative thought, imagination, and original expression, far exceeding ordinary levels of inventiveness.","s":"Her hypercreativity meant she invented new games, songs, and stories every single day after school.","p":"HY-per-kree-ay-TIV-ih-tee","o":"Greek","y":9,"bp":31,"sy":"hy.per.cre.ativ.i.ty","ps":"noun","t":["ogreek"]},{"w":"hypercriticality","d":"The state or quality of being excessively critical; a tendency to find fault or judge negatively to a degree far beyond what is fair or constructive.","s":"His hypercriticality made it difficult for teammates to share ideas without fearing harsh judgment.","p":"HY-per-krit-ih-KAL-ih-tee","o":"Greek","y":9,"bp":33,"sy":"hy.per.crit.i.cal.i.ty","ps":"noun","t":["law","ogreek"]},{"w":"hypercriticism","d":"The practice of criticizing excessively and unfairly, finding fault with every detail even when the flaws are minor or nonexistent.","s":"The editor's hypercriticism discouraged young writers who needed encouragement, not endless fault-finding.","p":"HY-per-KRIT-ih-siz-um","o":"Greek","y":9,"bp":29,"sy":"hy.per.crit.i.cism","ps":"noun","t":["ogreek"]},{"w":"hypercriticize","d":"To criticize something or someone excessively and unfairly, focusing intensely on minor flaws or errors in a way that goes far beyond reasonable evaluation.","s":"Don't hypercriticize every small mistake your partner makes or it will damage your relationship.","p":"HY-per-KRIT-ih-syz","o":"Greek","y":9,"bp":29,"sy":"hy.per.crit.i.cize","ps":"verb","t":["ogreek"]},{"w":"hypercubic","d":"Relating to or resembling a hypercube, a geometric figure that extends the concept of a square or cube into four or more dimensions.","s":"The professor drew a hypercubic shape on the board to illustrate how geometry works in four dimensions.","p":"HY-per-KYOO-bik","o":"Greek","y":8,"bp":30,"sy":"hy.per.cu.bic","ps":"adjective","t":["numbers","ogreek"]},{"w":"hypercytokinemia","d":"A dangerous medical condition in which abnormally high levels of cytokines, the proteins that regulate immune responses, flood the bloodstream, potentially causing widespread inflammation and organ damage.","s":"Doctors feared hypercytokinemia in the patient, a condition where the immune system releases a dangerous flood of signals.","p":"HY-per-sy-toh-ky-NEE-mee-uh","o":"Greek","y":9,"bp":30,"sy":"hy.per.cy.tokine.mia","ps":"noun","t":["body","disease","waterways","music","ogreek"]},{"w":"hyperdefensive","d":"Extremely or excessively defensive; reacting to perceived criticism or threats with a level of self-protection far beyond what the situation warrants.","s":"Whenever anyone questioned her work, she became hyperdefensive and refused to listen to any suggestions.","p":"HY-per-dih-FEN-siv","o":"Greek","y":9,"bp":29,"sy":"hy.per.de.fen.sive","ps":"adjective","t":["ogreek"]},{"w":"hyperdeformed","d":"Shaped or distorted far beyond the normal or expected form, especially describing atomic nuclei that are stretched into an extremely elongated shape.","s":"Scientists discovered a hyperdeformed nucleus spinning at an extraordinary rate during their particle physics experiment.","p":"HY-per-deh-FORMD","o":"Greek","y":9,"bp":26,"sy":"hy.per.de.formed","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hyperdensity","d":"An extremely high concentration of matter, energy, or information packed into a given space, far exceeding normal density levels.","s":"The hyperdensity of the neutron star meant a teaspoon of its material would weigh billions of tons.","p":"HY-per-DEN-sih-tee","o":"Greek","y":8,"bp":39,"sy":"hy.per.den.si.ty","ps":"noun","t":["physics","ogreek"]},{"w":"hyperdetailed","d":"Containing an extraordinarily high level of detail, far beyond what is typical or necessary for understanding a subject.","s":"The hyperdetailed illustration showed every brick and leaf so clearly it looked like a photograph.","p":"HY-per-deh-TAYLD","o":"Greek","y":9,"bp":26,"sy":"hy.per.de.tailed","ps":"adjective","t":["ogreek"]},{"w":"hyperdeveloped","d":"Grown, trained, or built to an extreme degree that goes well beyond what is considered normal or optimal.","s":"The athlete's hyperdeveloped leg muscles allowed her to jump higher than any of her competitors.","p":"HY-per-deh-VEL-upt","o":"Greek","y":9,"bp":29,"sy":"hy.per.de.vel.oped","ps":"adjective","t":["ogreek"]},{"w":"hyperdicrotic","d":"Relating to a pulse that shows an exaggerated double beat, with the secondary wave being unusually prominent on a pulse tracing.","s":"The nurse noted a hyperdicrotic pulse, meaning the waveform on the monitor showed an unusually strong secondary peak.","p":"HY-per-dy-KROT-ik","o":"Greek","y":9,"bp":28,"sy":"hy.per.di.crot.ic","ps":"adjective","t":["ogreek"]},{"w":"hyperdiffusive","d":"Spreading or dispersing at an exceptionally rapid or extensive rate, far beyond normal diffusion processes.","s":"The hyperdiffusive dye spread through the water so rapidly that the entire tank turned blue within seconds.","p":"HY-per-dih-FYOO-siv","o":"Greek","y":9,"bp":29,"sy":"hy.per.dif.fu.sive","ps":"adjective","t":["ogreek"]},{"w":"hyperdilation","d":"An extreme widening or expansion of a body passage or organ, such as a blood vessel or pupil, well beyond its normal range.","s":"The doctor noted hyperdilation of the patient's pupils after the medication was administered.","p":"HY-per-dy-LAY-shun","o":"Greek","y":9,"bp":28,"sy":"hy.per.di.la.tion","ps":"noun","t":["body","music","seafaring","ogreek"]},{"w":"hyperdiploid","d":"Having more than the normal diploid number of chromosomes in a cell, but not quite reaching the next full set, often seen in certain cancers.","s":"Scientists discovered that the cancer cells were hyperdiploid, containing extra chromosomes beyond the normal count.","p":"HY-per-DIP-loyd","o":"Greek","y":9,"bp":36,"sy":"hy.per.diploid","ps":"adjective","t":["disease","numbers","ogreek"]},{"w":"hyperdisciplined","d":"Maintaining an extremely strict and rigorous level of self-control, order, and adherence to rules, far beyond what most people practice.","s":"The hyperdisciplined athlete woke at 4 a.m. every day without fail, never missing a single training session.","p":"HY-per-DIS-ih-plind","o":"Greek","y":9,"bp":30,"sy":"hy.per.dis.ci.plined","ps":"adjective","t":["ogreek"]},{"w":"hyperdramatic","d":"Expressing emotions or reactions in an exaggerated and theatrical way that far exceeds what the situation actually calls for.","s":"My hyperdramatic little brother burst into tears just because his toast was slightly burnt.","p":"HY-per-druh-MAT-ik","o":"Greek","y":9,"bp":28,"sy":"hy.per.dra.mat.ic","ps":"adjective","t":["emotions","ogreek"]},{"w":"hyperdrive","d":"A fictional or theoretical propulsion system capable of moving a spacecraft at speeds far exceeding the normal limits of physics, often by bypassing ordinary space; also used figuratively to mean an extremely accelerated mode of activity.","s":"In the science fiction movie, the spaceship engaged hyperdrive and vanished into the stars in a flash of light.","p":"HH AY1 P ER0 D R AY2 V","o":"Greek","y":7,"bp":29,"sy":"hy.per.drive","ps":"noun","t":["physics","ogreek"]},{"w":"hyperdynamics","d":"A state or condition of extremely intense, powerful, or fast-changing forces and motions, far beyond normal dynamic levels.","s":"The engineering team studied the hyperdynamics of the rocket's fuel system to prevent dangerous pressure surges.","p":"HY-per-dy-NAM-iks","o":"Greek","y":9,"bp":28,"sy":"hy.per.dy.nam.ics","ps":"noun","t":["physics","ogreek"]},{"w":"hyperechogenicity","d":"A condition in medical imaging where a tissue or structure reflects ultrasound waves much more strongly than surrounding tissues, appearing unusually bright on the image.","s":"The radiologist pointed out the hyperechogenicity of the nodule, which appeared unusually bright on the ultrasound screen.","p":"HY-per-ek-oh-jeh-NIH-sih-tee","o":"Greek","y":9,"bp":32,"sy":"hy.per.e.chogenic.i.ty","ps":"noun","t":["body","waterways","ogreek"]},{"w":"hyperedge","d":"In mathematics and graph theory, a generalized edge that can connect three or more nodes simultaneously, unlike a regular edge which connects only two.","s":"In the math problem, a hyperedge connected five different nodes at once, unlike a regular edge that links only two.","p":"HY-per-EJ","o":"Greek","y":9,"bp":28,"sy":"hy.per.edge","ps":"noun","t":["logic","numbers","ogreek"]},{"w":"hypereducated","d":"Having received education far beyond the average level, often holding multiple advanced degrees or possessing an exceptionally broad and deep knowledge base.","s":"The hypereducated professor held four advanced degrees but still loved learning something new every day.","p":"HY-per-EJ-oo-kay-tid","o":"Greek","y":9,"bp":31,"sy":"hy.per.e.d.u.cat.ed","ps":"adjective","t":["logic","ogreek"]},{"w":"hyperefficient","d":"Operating with an extraordinarily high level of efficiency, eliminating virtually all waste of time, energy, or resources in completing a task.","s":"The hyperefficient robot sorted thousands of packages per hour without a single mistake.","p":"HY-per-ih-FISH-unt","o":"Greek","y":9,"bp":29,"sy":"hy.per.ef.fi.cient","ps":"adjective","t":["physics","time","ogreek"]},{"w":"hyperelliptic","d":"In mathematics, relating to a type of algebraic curve that generalizes the elliptic curve to higher degrees, studied in advanced number theory and geometry.","s":"The mathematician wrote a long proof involving hyperelliptic curves that extended far beyond simple oval shapes.","p":"HY-per-ih-LIP-tik","o":"Greek","y":8,"bp":28,"sy":"hy.per.el.lip.tic","ps":"adjective","t":["logic","numbers","ogreek"]},{"w":"hyperemotionality","d":"The tendency to experience and express emotions at an extremely intense level, reacting far more strongly than most people would in ordinary situations.","s":"Her hyperemotionality meant she would cry at commercials, laugh too loudly at jokes, and panic over small setbacks.","p":"HY-per-ih-moh-shun-AL-ih-tee","o":"Greek","y":9,"bp":35,"sy":"hy.per.e.mo.tion.al.i.ty","ps":"noun","t":["emotions","ogreek"]},{"w":"hyperendemic","d":"Describing a disease or condition that is constantly present in a population at an unusually high and persistent rate, well above what is considered normal endemic levels.","s":"Malaria is hyperendemic in certain regions of Africa, meaning it is constantly present at very high rates.","p":"HY-per-en-DEM-ik","o":"Greek","y":8,"bp":39,"sy":"hy.per.en.dem.ic","ps":"adjective","t":["disease","ogreek"]},{"w":"hyperenergetic","d":"Possessing or displaying an extraordinarily high level of energy and activity, far exceeding what is typical for a person or system.","s":"The hyperenergetic puppy bounced off every piece of furniture and still wanted to play after an hour of fetch.","p":"HY-per-en-er-JET-ik","o":"Greek","y":9,"bp":30,"sy":"hy.per.en.er.get.ic","ps":"adjective","t":["physics","ogreek"]},{"w":"hyperenhancement","d":"An abnormally strong increase in signal brightness seen in medical imaging, particularly MRI, when a tissue absorbs contrast agent far more than surrounding tissues.","s":"The MRI showed hyperenhancement of the tissue, indicating unusual blood flow in that area of the brain.","p":"HY-per-en-HANS-munt","o":"Greek","y":9,"bp":30,"sy":"hy.per.en.hance.ment","ps":"noun","t":["body","ogreek"]},{"w":"hyperentangled","d":"In quantum physics, describing particles that are entangled across multiple properties or degrees of freedom simultaneously, creating stronger correlations than standard entanglement.","s":"The physicists created hyperentangled photons that shared multiple quantum properties at the same time.","p":"HY-per-en-TANG-guld","o":"Greek","y":9,"bp":27,"sy":"hy.per.entan.gled","ps":"adjective","t":["physics","ogreek"]},{"w":"hyperentanglement","d":"A quantum phenomenon in which particles share entanglement in more than one physical property at the same time, enabling more complex quantum information processing.","s":"Hyperentanglement could one day allow scientists to send information in completely new ways using quantum physics.","p":"HY-per-en-TANG-gul-munt","o":"Greek","y":9,"bp":30,"sy":"hy.per.entan.gle.ment","ps":"noun","t":["physics","time","ogreek"]},{"w":"hyperenthusiastic","d":"Showing an extremely intense and overflowing level of excitement and eagerness about something, often to a degree that seems excessive to others.","s":"The hyperenthusiastic fan screamed so loudly during the concert that she lost her voice by the second song.","p":"HY-per-en-thoo-zee-AS-tik","o":"Greek","y":9,"bp":33,"sy":"hy.per.en.thu.si.as.tic","ps":"adjective","t":["ogreek"]},{"w":"hypereosinophilic","d":"Relating to an abnormally large number of eosinophil cells in the blood or tissues, far above the normal range, which can cause organ damage.","s":"The patient was diagnosed with a hypereosinophilic condition, meaning his immune cells were dangerously overactive.","p":"HY-per-ee-oh-SIN-oh-FIL-ik","o":"Greek","y":9,"bp":29,"sy":"hy.per.e.osinophilic","ps":"adjective","t":["body","music","numbers","ogreek"]},{"w":"hyperestrogenemia","d":"A medical condition characterized by abnormally elevated levels of estrogen circulating in the blood, which can disrupt hormonal balance and affect multiple body systems.","s":"The doctor tested for hyperestrogenemia after noticing symptoms caused by abnormally high estrogen levels in the blood.","p":"HY-per-es-troh-jeh-NEE-mee-uh","o":"Greek","y":9,"bp":33,"sy":"hy.per.e.stro.gen.e.mia","ps":"noun","t":["body","character","ogreek"]},{"w":"hyperestrogenic","d":"Relating to or caused by abnormally high levels of estrogen activity in the body, which can affect reproductive and overall health.","s":"Certain environmental chemicals can have hyperestrogenic effects on wildlife, disrupting normal hormonal development.","p":"HY-per-es-troh-JEN-ik","o":"Greek","y":9,"bp":30,"sy":"hy.per.e.stro.genic","ps":"adjective","t":["ogreek"]},{"w":"hypereutrophy","d":"An extreme state of nutrient enrichment in a body of water, far beyond normal eutrophic levels, causing severe algae overgrowth and oxygen depletion harmful to aquatic life.","s":"The lake suffered from hypereutrophy due to fertilizer runoff, causing massive algae blooms that choked the water.","p":"HY-per-YOO-troh-fee","o":"Greek","y":9,"bp":28,"sy":"hy.per.eu.tro.phy","ps":"noun","t":["marine","botany","chemistry","ogreek"]},{"w":"hyperexcitability","d":"An abnormally heightened tendency of nerves, muscles, or cells to fire or respond to stimuli, far more readily than under normal conditions.","s":"Caffeine can increase hyperexcitability in the nervous system, making it hard to sit still or fall asleep.","p":"HY-per-ek-sy-tuh-BIL-ih-tee","o":"Greek","y":8,"bp":32,"sy":"hy.per.ex.citabil.i.ty","ps":"noun","t":["body","ogreek"]},{"w":"hyperexcretion","d":"The excessive release or elimination of a substance from the body, such as a hormone or waste product, at levels far above what is normal.","s":"The patient's kidneys showed hyperexcretion of calcium, putting her at risk for painful kidney stones.","p":"HY-per-ek-SKREE-shun","o":"Greek","y":9,"bp":29,"sy":"hy.per.ex.cre.tion","ps":"noun","t":["ogreek"]},{"w":"hyperextended","d":"extend a joint beyond its normal range","p":"HY-per-ek-STEND-id","o":"Greek","y":7,"bp":28,"sy":"hy.per.ex.tend.ed","ps":"verb","t":["ogreek"]},{"w":"hyperexuberance","d":"An extreme and overflowing state of joyful enthusiasm and high spirits that goes far beyond ordinary exuberance and can be difficult to contain.","s":"The toddler's hyperexuberance at the birthday party had him running in circles and shrieking with joy for an hour.","p":"HY-per-eg-ZOO-ber-uns","o":"Greek","y":9,"bp":31,"sy":"hy.per.ex.u.ber.ance","ps":"noun","t":["emotions","ogreek"]},{"w":"hyperface","d":"In geometry and higher-dimensional mathematics, a flat boundary element of a polytope that has one fewer dimension than the overall shape, generalizing the concept of a face into higher dimensions.","s":"In geometry class, the teacher explained that a hyperface is a boundary element of a higher-dimensional shape.","p":"HY-per-FAYS","o":"Greek","y":9,"bp":28,"sy":"hy.per.face","ps":"noun","t":["chemistry","maps","numbers","ogreek"]},{"w":"hyperfast","d":"Moving, operating, or occurring at an extremely rapid speed that far surpasses what is considered fast under normal circumstances.","s":"The hyperfast processor completed millions of calculations before I could even blink.","p":"HY-per-FAST","o":"Greek","y":8,"bp":28,"sy":"hy.per.fast","ps":"adjective","t":["ogreek"]},{"w":"hyperfeminized","d":"Displaying or having been altered to show exaggerated feminine characteristics or traits, whether through biology, culture, or artificial means, well beyond typical expression.","s":"The researcher argued that certain toy ads hyperfeminized girls by only showing pink kitchens and sparkly dolls.","p":"HY-per-FEM-ih-nyzd","o":"Greek","y":9,"bp":29,"sy":"hy.per.fem.i.nized","ps":"adjective","t":["ogreek"]},{"w":"hyperferritinemia","d":"A medical condition in which the level of ferritin, a protein that stores iron, in the bloodstream is abnormally and dangerously elevated.","s":"The doctor diagnosed hyperferritinemia after blood tests revealed dangerously high levels of ferritin, a protein that stores iron.","p":"HY-per-fer-ih-tih-NEE-mee-uh","o":"Greek","y":9,"bp":30,"sy":"hy.per.fer.ritine.mia","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hyperfibrinolysis","d":"An abnormally accelerated breakdown of fibrin blood clots in the body, which can lead to uncontrolled bleeding because clots dissolve too quickly.","s":"After the accident, doctors feared hyperfibrinolysis, a condition where the body breaks down blood clots too quickly, causing uncontrolled bleeding.","p":"HY-per-fy-brih-NOL-ih-sis","o":"Greek","y":9,"bp":33,"sy":"hy.per.fib.ri.nol.y.sis","ps":"noun","t":["body","chemistry","physics","ogreek"]},{"w":"hyperfiltration","d":"An excessive rate of filtration by the kidneys, where blood is filtered far above the normal level, which can stress and eventually damage kidney tissue over time.","s":"Diabetes can cause hyperfiltration in the kidneys, forcing them to work too hard and eventually damaging them.","p":"HY-per-fil-TRAY-shun","o":"Greek","y":9,"bp":30,"sy":"hy.per.fil.tra.tion","ps":"noun","t":["body","time","ogreek"]},{"w":"hyperfinite","d":"In mathematical logic and nonstandard analysis, describing a set or structure that behaves like a finite set but is larger than any standard finite number, existing within a nonstandard number system.","s":"In advanced mathematics, a hyperfinite set is treated as if it is finite even though it is extraordinarily large.","p":"HY-per-FY-nyt","o":"Greek","y":9,"bp":37,"sy":"hy.per.fi.nite","ps":"adjective","t":["logic","numbers","ogreek"]},{"w":"hyperfocal","d":"Relating to the closest focusing distance at which a camera lens can be set so that objects from half that distance to infinity are acceptably sharp; used in photography to maximize depth of field.","s":"The photographer set a hyperfocal distance to ensure everything from the flowers in the foreground to the distant mountains appeared sharp.","p":"HY-per-FOH-kul","o":"Greek","y":7,"bp":30,"sy":"hy.per.fo.cal","ps":"adjective","t":["physics","ogreek"]},{"w":"hyperfocused","d":"Extremely or intensely concentrated on a single task or subject, often to the exclusion of everything else around you.","s":"She was so hyperfocused on finishing her novel that she forgot to eat lunch or answer any text messages.","p":"HY-per-FOH-kust","o":"Greek","y":8,"bp":38,"sy":"hy.per.fo.cused","ps":"adjective","t":["ogreek"]},{"w":"hyperforest","d":"In mathematics and graph theory, a graph in which every connected component is a hypertree, generalizing the concept of a forest to hypergraphs where edges can connect more than two nodes.","s":"The computer scientist described a hyperforest as a collection of hypergraphs with no cycles connecting the nodes.","p":"HY-per-FOR-est","o":"Greek","y":8,"bp":37,"sy":"hy.per.for.est","ps":"noun","t":["logic","numbers","ogreek"]},{"w":"hyperfullerene","d":"A large carbon molecule that extends the structure of a standard fullerene, containing significantly more carbon atoms arranged in a cage-like or nested spherical form.","s":"Scientists synthesized a hyperfullerene, a carbon molecule even larger than the famous soccer-ball-shaped buckminsterfullerene.","p":"HY-per-FUL-er-een","o":"Greek","y":9,"bp":26,"sy":"hy.per.fullerene","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypergamous","d":"Relating to hypergamy, the practice or tendency of marrying a person of a higher social, economic, or educational status than oneself.","s":"In some societies, hypergamous customs led women to seek partners of higher social status or greater wealth.","p":"hy-PER-guh-mus","o":"Greek","y":9,"bp":38,"sy":"hy.per.g.a.mous","ps":"adjective","t":["economy","ogreek"]},{"w":"hypergastrinemia","d":"A medical condition in which abnormally high levels of the hormone gastrin are present in the bloodstream, often causing excess stomach acid production.","s":"The patient's hypergastrinemia caused excessive stomach acid production that required immediate treatment.","p":"HY-per-GAS-trin-EE-mee-uh","o":"Greek","y":9,"bp":30,"sy":"hy.per.gas.trine.mia","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hypergastrinemic","d":"Relating to or characterized by hypergastrinemia, meaning abnormally elevated gastrin levels in the blood.","s":"The hypergastrinemic condition was confirmed after the doctor reviewed the patient's hormone blood panel.","p":"HY-per-GAS-trin-EE-mik","o":"Greek","y":9,"bp":30,"sy":"hy.per.gas.trine.mic","ps":"adjective","t":["body","character","ogreek"]},{"w":"hypergentrification","d":"An extreme and accelerated form of gentrification in which rapid development and influx of wealthy residents so drastically transforms a neighborhood that original communities are almost entirely displaced.","s":"Hypergentrification pushed out long-time residents as luxury condos replaced every affordable apartment in the neighborhood.","p":"HY-per-JEN-trih-fih-KAY-shun","o":"Greek","y":9,"bp":33,"sy":"hy.per.gen.tri.fi.ca.tion","ps":"noun","t":["physics","economy","ogreek"]},{"w":"hypergeometrical","d":"Relating to hypergeometry or hypergeometric functions, which are advanced mathematical concepts that extend ordinary geometry or standard geometric series into higher dimensions or more complex forms.","s":"The professor described the hypergeometrical series as a fascinating extension of ordinary geometry into higher dimensions.","p":"HY-per-jee-oh-MET-rih-kul","o":"Greek","y":9,"bp":33,"sy":"hy.per.ge.o.met.ri.cal","ps":"adjective","t":["numbers","ogreek"]},{"w":"hypergeometry","d":"A branch of mathematics that studies geometric properties and spaces beyond the three dimensions of ordinary Euclidean geometry, often involving four or more dimensions.","s":"Students studying hypergeometry must be comfortable with abstract mathematical spaces far beyond three dimensions.","p":"HY-per-jee-OM-eh-tree","o":"Greek","y":9,"bp":29,"sy":"hy.per.ge.om.e.try","ps":"noun","t":["numbers","ogreek"]},{"w":"hyperglucagonemia","d":"A medical condition characterized by abnormally high levels of glucagon, a hormone that raises blood sugar, circulating in the bloodstream.","s":"The doctor diagnosed hyperglucagonemia after noticing the patient's blood sugar levels were unusually high despite treatment.","p":"HY-per-GLOO-kuh-goh-NEE-mee-uh","o":"Greek","y":9,"bp":29,"sy":"hy.per.glucagone.mia","ps":"noun","t":["body","character","ogreek"]},{"w":"hyperglycorrhachia","d":"A condition in which there is an abnormally elevated concentration of glucose in the cerebrospinal fluid, the liquid surrounding the brain and spinal cord.","s":"The neurologist noted hyperglycorrhachia in the spinal fluid report, indicating elevated glucose in the cerebrospinal fluid.","p":"HY-per-GLY-koh-RAY-kee-uh","o":"Greek","y":9,"bp":32,"sy":"hy.per.gly.c.or.rhachia","ps":"noun","t":["body","ogreek"]},{"w":"hypergranulosis","d":"A skin condition characterized by an abnormal thickening of the granular cell layer of the epidermis, often seen in certain dermatological disorders.","s":"The dermatologist identified hypergranulosis under the microscope as an excess thickening layer in the skin sample.","p":"HY-per-GRAN-yoo-LOH-sis","o":"Greek","y":9,"bp":31,"sy":"hy.per.gran.u.lo.sis","ps":"noun","t":["body","disease","character","ogreek"]},{"w":"hypergraph","d":"In mathematics, a generalization of a graph in which an edge, called a hyperedge, can connect any number of vertices rather than just two.","s":"In the advanced math class, we learned that a hypergraph extends a regular graph by allowing edges to connect more than two nodes.","p":"HY-per-graf","o":"Greek","y":7,"bp":29,"sy":"hy.per.graph","ps":"noun","t":["numbers","ogreek"]},{"w":"hypergravity","d":"A condition in which the gravitational force experienced by an object or person is greater than the normal gravity felt on Earth's surface, such as during rapid acceleration.","s":"Astronauts train in hypergravity simulators to prepare their bodies for the crushing forces of rocket launches.","p":"HY-per-GRAV-ih-tee","o":"Greek","y":8,"bp":39,"sy":"hy.per.grav.i.ty","ps":"noun","t":["physics","ogreek"]},{"w":"hypergrowth","d":"An exceptionally rapid and sustained rate of growth, especially in a business or economy, far exceeding normal or expected rates.","s":"The tech startup experienced hypergrowth, doubling its user base every three months for an entire year.","p":"HY-per-grohth","o":"Greek","y":8,"bp":35,"sy":"hy.per.growth","ps":"noun","t":["economy","ogreek"]},{"w":"hyperhalophile","d":"An organism, typically a microbe, that thrives only in extremely high-salt environments, requiring far more salt than ordinary salt-tolerant organisms to survive.","s":"The hyperhalophile microorganism thrived in the salt flats where no other life could survive.","p":"HY-per-HAL-oh-fyl","o":"Greek","y":9,"bp":26,"sy":"hy.per.halophile","ps":"noun","t":["ecology","ogreek"]},{"w":"hyperhalophilic","d":"Describing an organism or process that requires or functions best in extremely high-salt concentrations, beyond the tolerance of ordinary halophiles.","s":"Scientists discovered a hyperhalophilic bacterium living in salt ponds ten times saltier than the ocean.","p":"HY-per-HAL-oh-FIL-ik","o":"Greek","y":9,"bp":27,"sy":"hy.per.halophilic","ps":"adjective","t":["ogreek"]},{"w":"hyperheuristic","d":"A high-level problem-solving strategy or algorithm that selects, combines, or generates other heuristics to solve complex optimization problems more effectively than any single rule alone.","s":"The computer scientist designed a hyperheuristic algorithm that automatically selects the best problem-solving strategy for each situation.","p":"HY-per-hyoo-RIS-tik","o":"Greek","y":9,"bp":27,"sy":"hy.per.heuris.tic","ps":"noun","t":["ogreek"]},{"w":"hyperhomocysteine","d":"An abnormally elevated level of homocysteine, an amino acid, in the blood; high levels are associated with increased risk of heart disease and stroke.","s":"Elevated hyperhomocysteine levels in the blood can signal increased risk for cardiovascular disease.","p":"HY-per-HOH-moh-SIS-teen","o":"Greek","y":9,"bp":32,"sy":"hy.per.ho.mo.cys.teine","ps":"noun","t":["body","disease","chemistry","ogreek"]},{"w":"hyperhomocysteinemic","d":"Relating to or characterized by abnormally high levels of homocysteine in the bloodstream, a condition linked to cardiovascular and neurological health risks.","s":"The hyperhomocysteinemic patient was advised to increase B-vitamin intake to lower dangerous amino acid levels.","p":"HY-per-HOH-moh-SIS-teen-EE-mik","o":"Greek","y":9,"bp":33,"sy":"hy.per.ho.mo.cys.teine.mic","ps":"adjective","t":["body","character","ogreek"]},{"w":"hyperimmune","d":"Having an exceptionally high level of immunity or antibodies against a specific antigen, often as a result of repeated exposure or deliberate immunization.","s":"Researchers developed a hyperimmune serum using antibodies from donors who had recovered from the disease.","p":"HY-per-ih-MYOON","o":"Greek","y":9,"bp":37,"sy":"hy.per.im.mune","ps":"adjective","t":["ogreek"]},{"w":"hyperimmunization","d":"The process of stimulating an immune system beyond normal levels through repeated or intensive vaccination to produce very high concentrations of specific antibodies.","s":"Hyperimmunization of horses produces highly concentrated antibodies used in some antivenom treatments.","p":"HY-per-ih-myoo-nih-ZAY-shun","o":"Greek","y":9,"bp":32,"sy":"hy.per.im.mu.niza.tion","ps":"noun","t":["ogreek"]},{"w":"hyperindividualism","d":"An extreme emphasis on personal independence, self-reliance, and individual rights, often to the point of rejecting collective responsibility or community values.","s":"Critics argued that hyperindividualism in modern culture made people less willing to cooperate for the common good.","p":"HY-per-in-dih-VIJ-oo-ul-iz-um","o":"Greek","y":9,"bp":33,"sy":"hy.per.indi.vid.u.al.ism","ps":"noun","t":["ogreek"]},{"w":"hyperinflammatory","d":"Relating to or causing an abnormally intense inflammatory response in the body, which can damage tissues and organs if left unchecked.","s":"The patient's hyperinflammatory response to the infection caused dangerous swelling throughout the body.","p":"HY-per-in-FLAM-uh-toh-ree","o":"Greek","y":9,"bp":33,"sy":"hy.per.in.flam.ma.to.ry","ps":"adjective","t":["body","disease","ogreek"]},{"w":"hyperinflated","d":"Excessively expanded or inflated beyond normal limits, whether referring to lungs that have trapped too much air, prices that have risen unreasonably, or any other overblown condition.","s":"The hyperinflated currency became nearly worthless as prices doubled every few weeks.","p":"HY-per-in-FLAY-ted","o":"Greek","y":9,"bp":28,"sy":"hy.per.in.flat.ed","ps":"adjective","t":["body","ogreek"]},{"w":"hyperinstrument","d":"A traditional musical instrument that has been enhanced with computer technology and sensors to expand its range of sounds and expressive capabilities far beyond its original design.","s":"The composer performed on a hyperinstrument — a cello linked to a computer that transformed each note into swirling sounds.","p":"HY-per-IN-stroo-ment","o":"Greek","y":9,"bp":30,"sy":"hy.per.in.stru.ment","ps":"noun","t":["music","festivals","ogreek"]},{"w":"hyperinsulinaemia","d":"The British spelling of hyperinsulinemia; a condition in which there are abnormally high levels of insulin circulating in the blood, often associated with insulin resistance or type 2 diabetes.","s":"The British medical journal reported hyperinsulinaemia as a key factor in the development of type 2 diabetes.","p":"HY-per-IN-soo-lin-EE-mee-uh","o":"Greek","y":9,"bp":30,"sy":"hy.per.in.suli.naemia","ps":"noun","t":["body","disease","wordwords","ogreek"]},{"w":"hyperinsulinemia","d":"A medical condition characterized by excessive levels of insulin in the bloodstream relative to glucose levels, commonly linked to insulin resistance and metabolic disorders.","s":"Hyperinsulinemia occurs when the pancreas produces far more insulin than the body actually needs.","p":"HY-per-IN-soo-lin-EE-mee-uh","o":"Greek","y":9,"bp":32,"sy":"hy.per.in.su.line.mia","ps":"noun","t":["body","disease","character","ogreek"]},{"w":"hyperinsulinemic","d":"Relating to or affected by hyperinsulinemia, meaning having or relating to abnormally elevated insulin levels in the blood.","s":"The hyperinsulinemic patient struggled with weight gain because excess insulin promotes fat storage.","p":"HY-per-IN-soo-lin-EE-mik","o":"Greek","y":8,"bp":32,"sy":"hy.per.in.su.line.mic","ps":"adjective","t":["body","ogreek"]},{"w":"hyperinteger","d":"In nonstandard analysis and mathematical logic, an element of a hyperreal number system that behaves like an integer but may be infinitely large, extending beyond the ordinary counting numbers.","s":"In nonstandard analysis, a hyperinteger is an element of the hyperreal number system that behaves like a whole number.","p":"HY-per-IN-teh-jer","o":"Greek","y":8,"bp":39,"sy":"hy.per.in.te.ger","ps":"noun","t":["chemistry","logic","numbers","ogreek"]},{"w":"hyperintelligence","d":"An extremely advanced level of intelligence far surpassing normal human cognitive ability, often used to describe the theoretical capabilities of artificial intelligence or extraordinary individuals.","s":"Science fiction authors often imagine AI reaching hyperintelligence, surpassing human thinking in every measurable way.","p":"HY-per-in-TEL-ih-jens","o":"Greek","y":9,"bp":32,"sy":"hy.per.in.tel.li.gence","ps":"noun","t":["ogreek"]},{"w":"hyperintelligent","d":"Possessing an extraordinarily high degree of intelligence that greatly exceeds normal human or expected cognitive ability.","s":"The hyperintelligent robot in the story could solve in seconds math problems that took humans years.","p":"HY-per-in-TEL-ih-jent","o":"Greek","y":9,"bp":32,"sy":"hy.per.in.tel.li.gent","ps":"adjective","t":["ogreek"]},{"w":"hyperintense","d":"Appearing abnormally bright or showing an unusually strong signal on a medical imaging scan, such as an MRI, often indicating inflammation, injury, or disease in a tissue.","s":"The MRI scan showed a hyperintense region in the brain that doctors needed to investigate further.","p":"HY-per-in-TENS","o":"Greek","y":8,"bp":38,"sy":"hy.per.in.tense","ps":"adjective","t":["body","disease","ogreek"]},{"w":"hyperintensity","d":"An area that appears abnormally bright on an MRI or other medical scan, typically indicating a lesion, inflammation, or other pathological change in the tissue being imaged.","s":"White matter hyperintensity on the brain scan indicated possible early signs of small vessel disease.","p":"HY-per-in-TEN-sih-tee","o":"Greek","y":8,"bp":30,"sy":"hy.per.in.ten.si.ty","ps":"noun","t":["body","disease","ogreek"]},{"w":"hyperjudgmental","d":"Excessively quick or harsh in forming negative opinions or criticisms about others, going far beyond normal levels of critical evaluation.","s":"Her hyperjudgmental attitude made it difficult for classmates to share ideas without fear of harsh criticism.","p":"HY-per-juj-MEN-tul","o":"Greek","y":9,"bp":30,"sy":"hy.per.judg.men.tal","ps":"adjective","t":["ogreek"]},{"w":"hyperjump","d":"In science fiction, an instantaneous or extremely rapid method of space travel in which a spacecraft leaps across vast distances by bypassing normal space, often through a wormhole or warp drive.","s":"The spaceship made a hyperjump across the galaxy, arriving at its destination in seconds.","p":"HY-per-jump","o":"Greek","y":8,"bp":28,"sy":"hy.per.jump","ps":"noun","t":["ogreek"]},{"w":"hyperkagome","d":"In condensed matter physics, a three-dimensional lattice structure that generalizes the two-dimensional kagome pattern into a higher-dimensional network, studied for its unique magnetic and electronic properties.","s":"Physicists studying the hyperkagome lattice found unusual magnetic properties that challenged existing theories.","p":"HY-per-kah-GOH-may","o":"Greek","y":9,"bp":37,"sy":"hy.per.k.agome","ps":"noun","t":["physics","ogreek"]},{"w":"hyperkeratinization","d":"An abnormal or excessive thickening of the outer layer of skin caused by an overproduction of keratin, the protein that forms skin, nails, and hair.","s":"Hyperkeratinization of the scalp can lead to thick, scaly buildup that blocks hair follicles.","p":"HY-per-KAIR-uh-tin-ih-ZAY-shun","o":"Greek","y":9,"bp":33,"sy":"hy.per.k.er.a.tiniza.tion","ps":"noun","t":["body","ogreek"]},{"w":"hyperkeratosis","d":"A condition in which the outer layer of skin becomes abnormally thick and hard, often appearing as rough, scaly patches on the skin's surface.","s":"The podiatrist explained that the painful callus on her foot was actually a form of hyperkeratosis.","p":"hy-per-ker-uh-TOH-sis","o":"Greek","y":7,"bp":30,"sy":"hy.per.k.er.ato.sis","ps":"noun","t":["body","ogreek"]},{"w":"hyperkinesis","d":"A condition of excessive, uncontrollable physical movement or muscular activity, often associated with certain neurological or behavioral disorders.","s":"The child's hyperkinesis made it nearly impossible for him to sit still through an entire class period.","p":"hy-per-kih-NEE-sis","o":"Greek","y":8,"bp":39,"sy":"hy.per.ki.ne.sis","ps":"noun","t":["disease","ogreek"]},{"w":"hyperkyphosis","d":"An exaggerated outward curvature of the upper spine, resulting in a severely rounded or hunched back that goes beyond the normal degree of kyphosis.","s":"The elderly patient's hyperkyphosis gave her spine a pronounced hunchback curve that caused daily pain.","p":"hy-per-ky-FOH-sis","o":"Greek","y":9,"bp":26,"sy":"hy.per.kypho.sis","ps":"noun","t":["body","ogreek"]},{"w":"hyperlegible","d":"Designed or formatted to be exceptionally easy to read, far exceeding standard legibility standards, often through special typefaces or high contrast.","s":"Designers created a hyperlegible font specifically for readers with dyslexia, making every letter unmistakably clear.","p":"hy-per-LEJ-ih-bul","o":"Greek","y":9,"bp":39,"sy":"hy.per.leg.i.ble","ps":"adjective","t":["ogreek"]},{"w":"hyperlight","d":"Relating to or describing a hypothetical speed greater than the speed of light, used especially in science fiction to describe faster-than-light travel.","s":"In the science fiction novel, the starship traveled at hyperlight speed, reaching distant stars within hours.","p":"HY-per-lyt","o":"Greek","y":8,"bp":29,"sy":"hy.per.light","ps":"adjective","t":["ogreek"]},{"w":"hyperlink","d":"a link from a hypertext file to another location or file; typically activated by clicking on a highlighted word or icon at a particular location on the screen","s":"She clicked the hyperlink in the email and was taken directly to the school's homework page.","p":"HEYE-per-lih-ngk","o":"Greek","y":5,"bp":28,"sy":"hhay.per.lih.ngk","ps":"noun","t":["wordwords","ogreek"]},{"w":"hyperliteracy","d":"An exceptionally high or obsessive level of literacy and engagement with written text, sometimes referring to an unusual sensitivity to or focus on language and reading.","s":"The professor studied hyperliteracy in children who could read, write, and analyze texts far beyond their age level.","p":"hy-per-LIT-er-uh-see","o":"Greek","y":9,"bp":29,"sy":"hy.per.lit.er.a.cy","ps":"noun","t":["wordwords","ogreek"]},{"w":"hyperliteral","d":"Relating to or characterized by an extreme, excessive interpretation of words in their most exact and strict sense, leaving no room for figurative or implied meaning.","s":"His hyperliteral reading of the poem meant he thought the 'silver river' was actually made of metal.","p":"hy-per-LIT-er-ul","o":"Greek","y":8,"bp":39,"sy":"hy.per.lit.er.al","ps":"adjective","t":["character","wordwords","ogreek"]},{"w":"hyperliterally","d":"In an excessively or extremely literal manner, interpreting words so precisely that nuance, metaphor, or implied meaning is completely ignored.","s":"She took the joke hyperliterally and actually brought a bucket of water to 'break the ice.'.","p":"hy-per-LIT-er-ul-ee","o":"Greek","y":9,"bp":30,"sy":"hy.per.lit.er.al.ly","ps":"adverb","t":["poetry","wordwords","ogreek"]},{"w":"hyperliterate","d":"Possessing an extraordinarily high level of literacy, cultural knowledge, or engagement with texts, often to an intense or obsessive degree.","s":"The hyperliterate student had read every book on the library shelf before sixth grade.","p":"hy-per-LIT-er-it","o":"Greek","y":9,"bp":28,"sy":"hy.per.lit.er.ate","ps":"adjective","t":["logic","ogreek"]},{"w":"hyperliterature","d":"A form of writing or storytelling that uses hyperlinks, branching paths, or digital interactivity to allow readers to navigate a text in multiple non-linear ways.","s":"The author experimented with hyperliterature by embedding clickable story branches throughout her digital novel.","p":"hy-per-LIT-er-uh-chur","o":"Greek","y":9,"bp":31,"sy":"hy.per.lit.er.a.ture","ps":"noun","t":["maps","poetry","ogreek"]},{"w":"hyperlocal","d":"Focused on or relevant to a very small, specific geographic community or neighborhood, often referring to news or information about a single street, block, or town.","s":"The app delivers hyperlocal news about events happening right on your street.","p":"hy-per-LOH-kul","o":"Greek","y":6,"bp":29,"sy":"hy.per.local","ps":"adjective","t":["ogreek"]},{"w":"hyperlocalized","d":"Concentrated or restricted to an extremely small and specific geographic area or context, beyond what is typically considered local.","s":"The disease outbreak was hyperlocalized to just three blocks of the city.","p":"hy-per-LOH-kuh-lyzd","o":"Greek","y":9,"bp":27,"sy":"hy.per.local.ized","ps":"adjective","t":["ogreek"]},{"w":"hyperlocomotion","d":"Excessively rapid or intense physical movement from place to place, often describing animals or organisms that move far more than is typical or normal.","s":"Scientists noted hyperlocomotion in the lab mice after they received the experimental stimulant.","p":"hy-per-loh-kuh-MOH-shun","o":"Greek","y":9,"bp":30,"sy":"hy.per.loco.mo.tion","ps":"noun","t":["animals","ogreek"]},{"w":"hyperluminous","d":"Emitting an extraordinarily intense amount of light, far beyond what is considered bright or luminous under normal conditions, often used to describe certain galaxies or stars.","s":"The hyperluminous quasar outshone an entire galaxy of billions of stars.","p":"hy-per-LOO-mih-nus","o":"Greek","y":9,"bp":28,"sy":"hy.per.lu.mi.nous","ps":"adjective","t":["astronomy","colors","ogreek"]},{"w":"hyperluxe","d":"Describing an extreme level of luxury and opulence that far surpasses standard high-end quality, catering to the most extravagant tastes and lifestyles.","s":"The hyperluxe hotel charged thousands of dollars per night for its gold-plated suites.","p":"hy-per-LUKS","o":"Greek","y":9,"bp":28,"sy":"hy.per.luxe","ps":"adjective","t":["ogreek"]},{"w":"hypermagnetic","d":"Having or relating to an extraordinarily powerful magnetic field, far stronger than what is produced under typical conditions.","s":"The scientists detected hypermagnetic fields near the neutron star that were trillions of times stronger than Earth's.","p":"hy-per-mag-NET-ik","o":"Greek","y":9,"bp":28,"sy":"hy.per.mag.net.ic","ps":"adjective","t":["physics","ogreek"]},{"w":"hypermap","d":"An interactive digital map that contains embedded hyperlinks or layered information, allowing users to click through to additional data, images, or related content.","s":"The city planner used a hypermap that linked each neighborhood icon to detailed population data.","p":"HY-per-map","o":"Greek","y":8,"bp":27,"sy":"hy.per.map","ps":"noun","t":["maps","numbers","ogreek"]},{"w":"hypermarketed","d":"Promoted or advertised in an excessively aggressive and widespread manner, using every possible channel to push a product or idea on consumers.","s":"The new sneakers were so hypermarketed that commercials for them appeared on every app, billboard, and TV channel.","p":"hy-per-MAR-kit-id","o":"Greek","y":9,"bp":28,"sy":"hy.per.mar.ket.ed","ps":"adjective","t":["ogreek"]},{"w":"hypermasculine","d":"Displaying or relating to an exaggerated, extreme version of traditionally masculine traits such as aggression, strength, or dominance, often to an unrealistic or harmful degree.","s":"The film's hypermasculine hero never showed emotion and solved every problem with brute force.","p":"hy-per-MAS-kyoo-lin","o":"Greek","y":8,"bp":29,"sy":"hy.per.mas.cu.line","ps":"adjective","t":["festivals","ogreek"]},{"w":"hypermasculinity","d":"The state or quality of displaying extreme, exaggerated masculine characteristics, often involving an intense emphasis on toughness, aggression, and suppression of emotion.","s":"The documentary examined how hypermasculinity in sports culture can harm athletes' mental health.","p":"hy-per-mas-kyoo-LIN-ih-tee","o":"Greek","y":8,"bp":32,"sy":"hy.per.mas.culin.i.ty","ps":"noun","t":["emotions","ogreek"]},{"w":"hypermasculinized","d":"Made to reflect or embody an exaggerated and extreme version of masculine qualities, often through cultural, social, or physical reinforcement of stereotyped male traits.","s":"Critics argued the video game characters had been hypermasculinized with unrealistically huge muscles.","p":"hy-per-MAS-kyoo-lih-nyzd","o":"Greek","y":9,"bp":30,"sy":"hy.per.mas.culin.ized","ps":"adjective","t":["ogreek"]},{"w":"hypermassive","d":"Having an extraordinarily great mass, far exceeding what would normally be considered massive, often used in astrophysics to describe certain black holes or celestial objects.","s":"Astronomers discovered a hypermassive black hole that was billions of times heavier than our sun.","p":"hy-per-MAS-iv","o":"Greek","y":9,"bp":38,"sy":"hy.per.mas.sive","ps":"adjective","t":["astronomy","ogreek"]},{"w":"hypermaterialistic","d":"Excessively focused on acquiring physical possessions and wealth to an extreme degree, valuing material goods above nearly all other aspects of life.","s":"The hypermaterialistic character valued expensive gadgets and designer clothes over friendships.","p":"hy-per-muh-teer-ee-uh-LIS-tik","o":"Greek","y":9,"bp":35,"sy":"hy.per.ma.te.ri.al.is.tic","ps":"adjective","t":["economy","ogreek"]},{"w":"hypermatrix","d":"In mathematics or computing, a multidimensional array or matrix structure that extends beyond two dimensions, containing multiple layers or nested levels of data.","s":"The mathematician used a hypermatrix to organize data across four dimensions at once.","p":"hy-per-MAY-triks","o":"Greek","y":8,"bp":37,"sy":"hy.per.ma.trix","ps":"noun","t":["numbers","ogreek"]},{"w":"hypermeasure","d":"In music theory, a large-scale rhythmic unit made up of several individual measures that together form a higher-level pattern or grouping.","s":"In music theory, the teacher explained that a hypermeasure groups several regular measures into one larger rhythmic unit.","p":"hy-per-MEH-zhur","o":"Greek","y":9,"bp":39,"sy":"hy.per.me.a.sure","ps":"noun","t":["music","logic","numbers","ogreek"]},{"w":"hypermediated","d":"Filtered or transmitted through an excessive number of media layers, technologies, or intermediaries, so that the original message or experience becomes heavily processed or altered.","s":"Modern life is so hypermediated that we rarely experience events without screens and filters between us and reality.","p":"hy-per-MEE-dee-ay-tid","o":"Greek","y":9,"bp":29,"sy":"hy.per.me.di.at.ed","ps":"adjective","t":["numbers","ogreek"]},{"w":"hypermetabolism","d":"A physiological condition in which the body's metabolic rate is abnormally elevated, causing it to burn energy, nutrients, and calories at a much faster rate than normal.","s":"After the surgery, the patient's hypermetabolism caused her body to burn calories at an alarming rate.","p":"hy-per-meh-TAB-uh-liz-um","o":"Greek","y":9,"bp":28,"sy":"hy.per.me.tabolism","ps":"noun","t":["physics","ogreek"]},{"w":"hypermiler","d":"A person who uses specialized driving techniques and strategies to maximize fuel efficiency, achieving far more miles per gallon than the average driver.","s":"The hypermiler coasted down every hill and kept his speed low to squeeze 70 miles per gallon from his car.","p":"hy-per-MY-ler","o":"Greek","y":8,"bp":30,"sy":"hy.per.mil.er","ps":"noun","t":["ogreek"]},{"w":"hypermilitarized","d":"Having an excessive concentration of military forces, weapons, or security measures in a particular area or society, far beyond what is considered necessary for defense.","s":"The border region had become hypermilitarized, with armed checkpoints every few miles.","p":"hy-per-MIL-ih-tuh-ryzd","o":"Greek","y":9,"bp":32,"sy":"hy.per.mil.i.ta.rized","ps":"adjective","t":["physics","war","numbers","ogreek"]},{"w":"hypermobile","d":"Capable of moving joints or body parts well beyond the normal range of motion, a condition that can affect flexibility, stability, and overall physical health.","s":"The gymnast was hypermobile and could bend her fingers all the way back without any pain.","p":"hy-per-MOH-bul","o":"Greek","y":8,"bp":37,"sy":"hy.per.mo.bile","ps":"adjective","t":["ogreek"]},{"w":"hypermodern","d":"Representing an extreme or cutting-edge form of modernism that pushes contemporary ideas, aesthetics, or technologies far beyond conventional modern standards.","s":"The architect's hypermodern design featured transparent walls, floating staircases, and AI-controlled lighting.","p":"hy-per-MOD-ern","o":"Greek","y":8,"bp":37,"sy":"hy.per.mod.ern","ps":"adjective","t":["ogreek"]},{"w":"hypermodernist","d":"A person who embraces or promotes hypermodernity, advocating for ideas, art, or practices that go far beyond typical modern movements in their rejection of tradition.","s":"The hypermodernist chess player preferred unconventional openings that surprised every opponent.","p":"hy-per-MOD-er-nist","o":"Greek","y":9,"bp":27,"sy":"hy.per.mod.ernist","ps":"noun","t":["festivals","ogreek"]},{"w":"hypermodernity","d":"A cultural and social condition characterized by an intensified, accelerated, and extreme form of modernity, marked by rapid technological change and constant transformation of identity.","s":"Scholars debate whether hypermodernity has made people more connected or more isolated than ever before.","p":"hy-per-muh-DER-nih-tee","o":"Greek","y":9,"bp":29,"sy":"hy.per.moder.ni.ty","ps":"noun","t":["physics","character","ogreek"]},{"w":"hypermodified","d":"Altered or changed to such an extreme degree that the original form is barely recognizable, often describing vehicles, organisms, or objects with excessive customization.","s":"The hypermodified race car barely resembled the ordinary sedan it had started as.","p":"hy-per-MOD-ih-fyd","o":"Greek","y":9,"bp":28,"sy":"hy.per.mod.i.fied","ps":"adjective","t":["vehicles","ogreek"]},{"w":"hypermultiplet","d":"In theoretical physics, a specific type of supermultiplet containing a larger number of particle states and supersymmetric partners than a standard multiplet.","s":"The physics student read about the hypermultiplet, a set of particles linked by supersymmetry equations.","p":"hy-per-MUL-tih-plet","o":"Greek","y":9,"bp":29,"sy":"hy.per.mul.ti.plet","ps":"noun","t":["physics","numbers","ogreek"]},{"w":"hypermuscular","d":"Having an extreme, exaggerated degree of muscular development that far exceeds typical athletic fitness, often appearing disproportionate or unrealistic.","s":"The hypermuscular superhero's arms were drawn so large they seemed physically impossible.","p":"hy-per-MUS-kyoo-ler","o":"Greek","y":9,"bp":28,"sy":"hy.per.mus.cu.lar","ps":"adjective","t":["sports","ogreek"]},{"w":"hypermutable","d":"Describing a gene, organism, or cell that has an abnormally high tendency to undergo genetic mutations, far exceeding the normal rate of mutation.","s":"Scientists found the hypermutable virus changed its genetic code so fast that vaccines struggled to keep up.","p":"hy-per-MYOO-tuh-bul","o":"Greek","y":9,"bp":36,"sy":"hy.per.mutable","ps":"adjective","t":["ogreek"]},{"w":"hypermutate","d":"To undergo genetic mutations at an abnormally rapid or high rate, often seen in certain viruses or cancer cells that change their genetic makeup very quickly.","s":"The cancer cells began to hypermutate, rapidly accumulating changes that made them resistant to treatment.","p":"hy-per-MYOO-tayt","o":"Greek","y":9,"bp":37,"sy":"hy.per.mu.tate","ps":"verb","t":["disease","ogreek"]},{"w":"hypernasal","d":"Relating to a quality of speech in which too much air flows through the nasal passages, causing the voice to sound excessively nasal or twangy.","s":"After the cold, his voice sounded hypernasal, as if he were speaking entirely through his nose.","p":"hy-per-NAY-zul","o":"Greek","y":8,"bp":29,"sy":"hy.per.nasal","ps":"adjective","t":["ogreek"]},{"w":"hypernationalism","d":"An extreme and excessive form of nationalism in which a nation's interests are placed so far above all others that it can lead to hostility toward other countries and peoples.","s":"The historian warned that hypernationalism had repeatedly led peaceful countries into devastating wars throughout the twentieth century.","p":"hy-per-NASH-un-ul-iz-um","o":"Greek","y":9,"bp":32,"sy":"hy.per.na.tion.al.ism","ps":"noun","t":["chemistry","nations","ogreek"]},{"w":"hypernatural","d":"Going beyond what is considered natural or part of the natural world; surpassing the ordinary limits of nature in an extreme way.","s":"The special effects team created a hypernatural landscape so vivid and strange that audiences felt they had stepped into another dimension entirely.","p":"hy-per-NACH-er-ul","o":"Greek","y":8,"bp":39,"sy":"hy.per.nat.u.ral","ps":"adjective","t":["ogreek"]},{"w":"hypernet","d":"An advanced or theoretical network that goes far beyond the capabilities of the ordinary internet, linking systems at an extreme or unprecedented scale.","s":"Scientists speculated that a hypernet connecting every device and sensor on Earth would generate more data in a single second than humans have ever recorded.","p":"HY-per-net","o":"Greek","y":8,"bp":27,"sy":"hy.per.net","ps":"noun","t":["ogreek"]},{"w":"hypernuclear","d":"Relating to atomic nuclei that contain at least one hyperon, a subatomic particle more massive than a neutron or proton, giving the nucleus properties beyond normal nuclear physics.","s":"The research team celebrated when their particle accelerator finally produced a hypernuclear event, opening a new chapter in subatomic physics research.","p":"hy-per-NOO-klee-er","o":"Greek","y":8,"bp":39,"sy":"hy.per.nu.cle.ar","ps":"adjective","t":["chemistry","physics","ogreek"]},{"w":"hyperoctahedral","d":"Relating to a geometric shape or structure that extends the concept of an eight-faced solid into higher dimensions, beyond the standard three-dimensional octahedron.","s":"The mathematics professor drew a hyperoctahedral diagram on the board, challenging students to visualize a shape that existed in four or more dimensions.","p":"hy-per-ok-tuh-HEE-drul","o":"Greek","y":9,"bp":33,"sy":"hy.pe.r.oc.ta.he.dral","ps":"adjective","t":["ogreek"]},{"w":"hyperonym","d":"A broad word covering more specific ones; 'animal' is one for 'cat' and 'puppy.'","s":"In linguistics class, we learned that 'vehicle' serves as a hyperonym for more specific words like 'car,' 'truck,' and 'bicycle.'.","p":"HY-per-oh-nim","o":"Greek","y":9,"bp":28,"sy":"hy.per.onym","ps":"noun","t":["animals","wordwords","ogreek"]},{"w":"hyperoperation","d":"In mathematics, any operation in a sequence that goes beyond the standard operations of addition, multiplication, and exponentiation, producing extremely large numbers very rapidly.","s":"When ordinary exponentiation was not powerful enough to express the number, the mathematician turned to hyperoperation to describe its incredible magnitude.","p":"hy-per-op-er-AY-shun","o":"Greek","y":9,"bp":30,"sy":"hy.per.op.er.a.tion","ps":"noun","t":["numbers","ogreek"]},{"w":"hyperoperator","d":"A mathematical symbol or function that performs a hyperoperation, extending beyond standard arithmetic operators like plus, minus, or multiplication into far more powerful calculations.","s":"The textbook introduced the hyperoperator notation carefully, reminding students that even simple-looking expressions could produce numbers beyond all imagination.","p":"hy-per-OP-er-ay-ter","o":"Greek","y":9,"bp":29,"sy":"hy.per.op.er.a.tor","ps":"noun","t":["numbers","ogreek"]},{"w":"hyperoral","d":"Relating to excessive or abnormally heightened activity or stimulation involving the mouth, such as compulsive chewing, sucking, or mouthing of objects.","s":"The pediatric specialist noted that the toddler's hyperoral behavior, constantly placing every object in his mouth, was something the family should monitor closely.","p":"hy-per-OR-ul","o":"Greek","y":8,"bp":28,"sy":"hy.per.oral","ps":"adjective","t":["ogreek"]},{"w":"hyperorganic","d":"Exceeding or going far beyond what is considered purely organic; sometimes used to describe systems or materials with extraordinarily complex organic properties.","s":"The chemist described the newly synthesized compound as hyperorganic, since its carbon-based structure was more intricate than anything found in nature.","p":"hy-per-or-GAN-ik","o":"Greek","y":8,"bp":39,"sy":"hy.per.or.gan.ic","ps":"adjective","t":["ogreek"]},{"w":"hyperorthodoxy","d":"An extremely strict or intense adherence to traditional beliefs, practices, or doctrines, going well beyond what is considered standard orthodoxy.","s":"Critics of the movement argued that its hyperorthodoxy left no room for thoughtful questioning, making open discussion of faith nearly impossible.","p":"hy-per-OR-thuh-dok-see","o":"Greek","y":9,"bp":27,"sy":"hy.per.ortho.doxy","ps":"noun","t":["festivals","logic","ogreek"]},{"w":"hyperosmolarity","d":"A condition in which the concentration of dissolved particles in a fluid, especially blood, is abnormally high, which can seriously disrupt the body's water balance.","s":"The emergency room doctor immediately ordered IV fluids after diagnosing the patient with dangerous hyperosmolarity caused by severe dehydration.","p":"hy-per-oz-moh-LAIR-ih-tee","o":"Greek","y":9,"bp":33,"sy":"hy.per.os.mo.lar.i.ty","ps":"noun","t":["body","physics","ogreek"]},{"w":"hyperosmotic","d":"Describing a solution that has a higher concentration of dissolved substances than a reference solution, causing water to move out of cells through osmosis.","s":"The biology students discovered that placing red blood cells in a hyperosmotic solution caused the cells to shrivel as water rapidly left them.","p":"hy-per-oz-MOT-ik","o":"Greek","y":7,"bp":39,"sy":"hy.per.os.mot.ic","ps":"adjective","t":["ogreek"]},{"w":"hyperoxic","d":"Relating to or characterized by an abnormally high concentration of oxygen, whether in a gas mixture, a body tissue, or the environment.","s":"Divers must carefully manage their air tanks to avoid hyperoxic conditions, since breathing too much pure oxygen at depth can be dangerously toxic.","p":"hy-per-OK-sik","o":"Greek","y":8,"bp":29,"sy":"hy.per.ox.ic","ps":"adjective","t":["body","chemistry","ecology","character","ogreek"]},{"w":"hyperoxidant","d":"A substance that is an exceptionally powerful oxidizing agent, capable of causing oxidation reactions far more rapidly or intensely than typical oxidants.","s":"Researchers handled the hyperoxidant with extreme caution, knowing that even a tiny spill could trigger an immediate and violent chemical reaction.","p":"hy-per-OK-sih-dant","o":"Greek","y":8,"bp":39,"sy":"hy.per.ox.i.dant","ps":"noun","t":["ogreek"]},{"w":"hyperoxide","d":"A chemical compound containing an unusually high proportion of oxygen, often with strong oxidizing properties beyond those of ordinary oxides.","s":"The laboratory synthesis of the hyperoxide required special equipment because the compound's extreme reactivity made it hazardous to store at room temperature.","p":"hy-per-OK-syd","o":"Greek","y":9,"bp":30,"sy":"hy.per.ox.ide","ps":"noun","t":["chemistry","ogreek"]},{"w":"hyperoxygenated","d":"Containing or supplied with an abnormally high level of oxygen, often describing water, blood, or air that has been enriched far beyond its normal oxygen content.","s":"Athletes sometimes train in hyperoxygenated environments, hoping that the extra oxygen will boost their endurance and speed up their recovery after hard workouts.","p":"hy-per-OK-sih-jen-ay-tid","o":"Greek","y":9,"bp":31,"sy":"hy.per.ox.y.genat.ed","ps":"adjective","t":["body","chemistry","ogreek"]},{"w":"hyperoxygenation","d":"The process of supplying an unusually large amount of oxygen to a substance, tissue, or environment, exceeding normal or required levels significantly.","s":"The medical team used hyperoxygenation during the procedure to ensure the patient's tissues remained healthy while blood flow was temporarily reduced.","p":"hy-per-ok-sih-jen-AY-shun","o":"Greek","y":9,"bp":32,"sy":"hy.per.ox.y.gena.tion","ps":"noun","t":["body","chemistry","ecology","ogreek"]},{"w":"hyperpaced","d":"Moving, progressing, or operating at an extremely fast or hectic pace that far exceeds what is considered normal or comfortable.","s":"Students complained that the hyperpaced curriculum left them no time to absorb each concept before the teacher raced on to the next challenging topic.","p":"HY-per-payst","o":"Greek","y":8,"bp":29,"sy":"hy.per.paced","ps":"adjective","t":["ogreek"]},{"w":"hyperparameter","d":"In machine learning and statistics, a parameter that is set before the learning process begins and controls how a model trains, rather than being learned from the data itself.","s":"The data scientist spent hours tuning each hyperparameter of the neural network, knowing that even small adjustments could dramatically improve the model's accuracy.","p":"hy-per-puh-RAM-ih-ter","o":"Greek","y":8,"bp":30,"sy":"hy.per.pa.ram.e.ter","ps":"noun","t":["vehicles","tools","ogreek"]},{"w":"hyperparasitism","d":"A biological relationship in which one parasite lives on or within another parasite, essentially parasitizing a parasite that is already exploiting a host organism.","s":"The entomologist was fascinated to discover an example of hyperparasitism in which a tiny wasp was laying its eggs inside another parasitic wasp's larvae.","p":"hy-per-PAIR-uh-sy-tiz-um","o":"Greek","y":9,"bp":30,"sy":"hy.per.par.a.sitism","ps":"noun","t":["ogreek"]},{"w":"hyperparathyroidism","d":"excessive secretion of parathyroid hormone resulting in abnormally high levels of calcium in the blood; can affect many systems of the body (especially causing bone resorption and osteoporosis)","s":"The doctor diagnosed the patient with hyperparathyroidism after noticing abnormally high calcium levels in the blood.","p":"hy-per-pair-uh-THY-royd-iz-um","o":"Greek","y":8,"bp":29,"sy":"hy.per.parathy.roidism","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hyperpatriotic","d":"Showing an extreme and excessive degree of patriotism, often to the point of being intolerant of criticism of one's country or dismissive of other nations.","s":"The editorial cautioned that hyperpatriotic slogans, while emotionally stirring, could prevent citizens from honestly examining their government's mistakes.","p":"hy-per-pay-tree-OT-ik","o":"Greek","y":9,"bp":30,"sy":"hy.per.pa.tri.ot.ic","ps":"adjective","t":["ogreek"]},{"w":"hyperpatriotism","d":"An extreme and excessive form of patriotism in which devotion to one's country goes far beyond healthy national pride, often resulting in hostility toward outsiders or dissenters.","s":"The political scientist argued that hyperpatriotism, unlike genuine civic pride, tends to silence debate and discourage the kind of self-reflection a healthy democracy needs.","p":"hy-per-PAY-tree-uh-tiz-um","o":"Greek","y":9,"bp":31,"sy":"hy.per.pa.tri.o.tism","ps":"noun","t":["ogreek"]},{"w":"hyperperfusion","d":"An abnormally excessive flow of blood or other fluid through a tissue or organ, which can cause damage just as too little blood flow can.","s":"After the surgery to clear the blocked artery, doctors monitored the patient closely for hyperperfusion, which can cause dangerous swelling in the brain.","p":"hy-per-per-FYOO-zhun","o":"Greek","y":9,"bp":29,"sy":"hy.per.per.fu.sion","ps":"noun","t":["body","music","ogreek"]},{"w":"hyperpermeability","d":"An abnormally increased ability of a membrane or barrier, such as a blood vessel wall, to allow substances to pass through it, often associated with inflammation or injury.","s":"The researcher linked the patients' symptoms to hyperpermeability of the gut lining, which was allowing harmful bacteria and toxins to enter the bloodstream.","p":"hy-per-per-mee-uh-BIL-ih-tee","o":"Greek","y":9,"bp":33,"sy":"hy.per.per.me.abil.i.ty","ps":"noun","t":["body","disease","seafaring","ogreek"]},{"w":"hyperpersonal","d":"Describing communication or relationships, especially online, that feel more intimate or intense than face-to-face interactions because people selectively present idealized versions of themselves.","s":"Social media can create hyperpersonal bonds between strangers who have never met, as each person carefully crafts messages that seem deeply sincere and revealing.","p":"hy-per-PER-sun-ul","o":"Greek","y":9,"bp":28,"sy":"hy.per.per.son.al","ps":"adjective","t":["ogreek"]},{"w":"hyperphagia","d":"An abnormal and excessive increase in appetite and food intake, often caused by a medical condition, brain injury, or certain medications.","s":"The neurologist explained that hyperphagia in some patients results from damage to the hypothalamus, the brain region that normally signals when a person is full.","p":"hy-per-FAY-jee-uh","o":"Greek","y":9,"bp":37,"sy":"hy.per.pha.gia","ps":"noun","t":["body","ogreek"]},{"w":"hyperphagic","d":"Relating to or characterized by hyperphagia; describing an animal or person that consumes food at an abnormally high rate or in excessive amounts.","s":"Bears become hyperphagic in late summer, eating enormous quantities of berries and fish each day to build up fat reserves before their long winter hibernation.","p":"hy-per-FAJ-ik","o":"Greek","y":8,"bp":37,"sy":"hy.per.phag.ic","ps":"adjective","t":["animals","character","ogreek"]},{"w":"hyperphosphatemia","d":"An abnormally high level of phosphate in the blood, which can interfere with the body's ability to use calcium and is often associated with kidney disease.","s":"The dietitian advised the dialysis patient to avoid high-phosphate foods because the patient's kidneys could no longer regulate the hyperphosphatemia on their own.","p":"hy-per-fos-fuh-TEE-mee-uh","o":"Greek","y":9,"bp":29,"sy":"hy.per.phos.phatemia","ps":"noun","t":["body","disease","chemistry","ogreek"]},{"w":"hyperphosphorylate","d":"To add an abnormally large number of phosphate groups to a protein or other molecule, a process associated with certain diseases including Alzheimer's disease.","s":"Scientists discovered that a faulty enzyme would hyperphosphorylate a key brain protein, causing it to form twisted tangles that disrupted normal neuron function.","p":"hy-per-fos-FOR-ih-layt","o":"Greek","y":9,"bp":32,"sy":"hy.per.phos.pho.ry.late","ps":"verb","t":["disease","chemistry","numbers","ogreek"]},{"w":"hyperphosphorylation","d":"The process by which an excessive number of phosphate groups are added to a molecule such as a protein, often disrupting its normal function and contributing to disease.","s":"Research into Alzheimer's disease has repeatedly pointed to hyperphosphorylation of the tau protein as a key step in forming the tangles found in affected brain tissue.","p":"hy-per-fos-for-ih-LAY-shun","o":"Greek","y":9,"bp":33,"sy":"hy.per.phos.pho.ry.la.tion","ps":"noun","t":["disease","chemistry","numbers","ogreek"]},{"w":"hyperpigmentation","d":"Unusual darkening of the skin in patches or widespread areas, caused by an excess of the pigment melanin, often triggered by sun exposure, inflammation, or hormonal changes.","s":"After spending summers without sunscreen, she developed hyperpigmentation that left dark patches on her cheeks.","p":"hy-per-pig-men-TAY-shun","o":"Greek","y":7,"bp":32,"sy":"hy.per.pig.men.ta.tion","ps":"noun","t":["body","disease","astronomy","painting","ogreek"]},{"w":"hyperploid","d":"Describing a cell or organism that has more chromosomes than the normal number for its species, resulting from extra chromosomes being added to the standard set.","s":"The geneticist identified a hyperploid cell line in the tissue sample, meaning the cells contained extra chromosomes that could contribute to tumor development.","p":"HY-per-ployd","o":"Greek","y":9,"bp":29,"sy":"hy.per.ploid","ps":"adjective","t":["numbers","ogreek"]},{"w":"hyperpluralism","d":"A condition in which so many competing interest groups or factions exist within a political system that effective decision-making and governance become extremely difficult.","s":"The political science textbook described hyperpluralism as a situation where dozens of powerful lobbying groups pull a government in so many directions that no policy ever gets passed.","p":"hy-per-PLOOR-ul-iz-um","o":"Greek","y":9,"bp":29,"sy":"hy.per.plu.ral.ism","ps":"noun","t":["politics","ogreek"]},{"w":"hyperpolarise","d":"To increase the electrical charge difference across a cell membrane beyond its normal resting state, making a nerve or muscle cell less likely to fire an action potential; the British spelling of hyperpolarize.","s":"The neuroscientist explained that certain drugs hyperpolarise neurons by opening channels that allow negatively charged ions to rush into the cell.","p":"hy-per-POH-luh-ryz","o":"Greek","y":9,"bp":26,"sy":"hy.per.po.larise","ps":"verb","t":["body","physics","wordwords","ogreek"]},{"w":"hyperpolarize","d":"To cause the inside of a cell membrane to become more negatively charged than its resting potential, reducing the cell's likelihood of generating an electrical signal.","s":"When the inhibitory neurotransmitter binds to the receptor, it can hyperpolarize the neuron, effectively putting the brakes on any signal that might otherwise travel down the nerve.","p":"hy-per-POH-luh-ryz","o":"Greek","y":9,"bp":28,"sy":"hy.per.po.lar.ize","ps":"verb","t":["physics","ogreek"]},{"w":"hyperpolitical","d":"Excessively concerned with or dominated by politics, to the point where nearly every topic, decision, or relationship is viewed through an intensely political lens.","s":"The professor worried that the hyperpolitical atmosphere on campus was making it impossible to have a calm, evidence-based discussion about even routine scientific topics.","p":"hy-per-puh-LIT-ih-kul","o":"Greek","y":9,"bp":30,"sy":"hy.per.po.lit.i.cal","ps":"adjective","t":["physics","politics","ogreek"]},{"w":"hyperpolyglot","d":"A person who has mastered an exceptionally large number of languages, typically defined as six or more, far beyond what an ordinary multilingual person speaks.","s":"The famous hyperpolyglot astounded audiences by conducting interviews seamlessly in eleven different languages, switching effortlessly between them without any notes or hesitation.","p":"hy-per-POL-ee-glot","o":"Greek","y":9,"bp":26,"sy":"hy.per.poly.glot","ps":"noun","t":["numbers","wordwords","ogreek"]},{"w":"hyperpower","d":"A nation so dominant in military, economic, and cultural strength that it surpasses even the level of a superpower, standing alone at the very top of global influence.","s":"Some historians argue that following the Cold War, the United States briefly became the world's sole hyperpower, with unmatched military reach and economic influence on every continent.","p":"HY-per-pow-er","o":"Greek","y":7,"bp":30,"sy":"hy.per.pow.er","ps":"noun","t":["nations","economy","war","ogreek"]},{"w":"hyperprior","d":"In statistics and machine learning, a prior probability distribution placed over the parameters of another prior distribution, representing beliefs about beliefs in a hierarchical model.","s":"In Bayesian statistics, the researcher placed a hyperprior on the distribution of model parameters.","p":"HEY-per-pry-or","o":"Greek","y":8,"bp":30,"sy":"hy.per.pri.or","ps":"noun","t":["tools","logic","ogreek"]},{"w":"hyperprivileged","d":"Possessing an extreme or extraordinary level of social, economic, or political advantage far beyond what most privileged people experience.","s":"The documentary explored how hyperprivileged children rarely see the struggles ordinary families face.","p":"HEY-per-PRIV-ih-lějd","o":"Greek","y":9,"bp":30,"sy":"hy.per.priv.i.leged","ps":"adjective","t":["politics","economy","ogreek"]},{"w":"hyperproduction","d":"The creation or manufacture of goods, content, or output at a level that far exceeds normal or necessary amounts, often leading to waste or surplus.","s":"The factory's hyperproduction led to warehouses overflowing with goods nobody could sell.","p":"HEY-per-pruh-DUK-shun","o":"Greek","y":9,"bp":30,"sy":"hy.per.pro.duc.tion","ps":"noun","t":["ogreek"]},{"w":"hyperproductive","d":"Capable of producing or accomplishing work at an exceptionally high rate, far exceeding what is considered normal or expected output.","s":"She was so hyperproductive during finals week that she finished three projects in a single day.","p":"HEY-per-pruh-DUK-tiv","o":"Greek","y":9,"bp":30,"sy":"hy.per.pro.duc.tive","ps":"adjective","t":["ogreek"]},{"w":"hyperproliferation","d":"The extremely rapid and excessive multiplication or spread of cells, organisms, ideas, or objects well beyond typical or healthy levels.","s":"Scientists were alarmed by the hyperproliferation of cancer cells in the lab sample.","p":"HEY-per-pruh-lif-er-AY-shun","o":"Greek","y":9,"bp":33,"sy":"hy.per.pro.lif.er.a.tion","ps":"noun","t":["numbers","ogreek"]},{"w":"hyperprolinemia","d":"A rare metabolic disorder in which abnormally high levels of the amino acid proline accumulate in the bloodstream, potentially affecting neurological function.","s":"The doctor diagnosed the infant with hyperprolinemia after routine blood screening.","p":"HEY-per-PROH-leen-EE-mee-uh","o":"Greek","y":9,"bp":30,"sy":"hy.per.pro.line.mia","ps":"noun","t":["body","disease","chemistry","ogreek"]},{"w":"hyperqualified","d":"Possessing credentials, skills, or experience that far surpass the minimum requirements for a particular job, role, or task.","s":"She felt hyperqualified for the entry-level job but applied anyway.","p":"HEY-per-KWOL-ih-fyd","o":"Greek","y":9,"bp":29,"sy":"hy.per.qual.i.fied","ps":"adjective","t":["ogreek"]},{"w":"hyperradical","d":"Holding or expressing political, social, or ideological views that are far more extreme than those considered typically radical, pushing well beyond conventional boundaries.","s":"The politician's hyperradical proposals shocked even members of his own party.","p":"HEY-per-RAD-ih-kul","o":"Greek","y":9,"bp":39,"sy":"hy.per.rad.i.cal","ps":"adjective","t":["politics","ogreek"]},{"w":"hyperrational","d":"Characterized by an extreme reliance on logic and reason that goes so far beyond normal rationality that it may ignore emotion, intuition, or practical context.","s":"Her hyperrational approach to every decision left no room for emotion or intuition.","p":"HEY-per-RASH-uh-nul","o":"Greek","y":9,"bp":26,"sy":"hy.per.ra.tional","ps":"adjective","t":["character","emotions","logic","ogreek"]},{"w":"hyperrationality","d":"The state or quality of applying logical reasoning to such an extreme degree that it becomes detached from human emotion, ethics, or common sense.","s":"The robot's hyperrationality made it unable to understand human humor.","p":"HEY-per-rash-uh-NAL-ih-tee","o":"Greek","y":9,"bp":32,"sy":"hy.per.ra.tional.i.ty","ps":"noun","t":["emotions","logic","ogreek"]},{"w":"hyperreal","d":"Describing something so vividly realistic or artificially enhanced that it seems more real than reality itself, or relating to a mathematical system extending the real numbers.","s":"The video game's graphics looked so hyperreal that players forgot they were in a simulation.","p":"HEY-per-REE-ul","o":"Greek","y":7,"bp":29,"sy":"hy.per.re.al","ps":"adjective","t":["numbers","ogreek"]},{"w":"hyperreality","d":"A condition, described by philosopher Jean Baudrillard, in which simulations and representations of reality become indistinguishable from or more convincing than actual reality.","s":"Philosophers argue that social media creates a hyperreality that distorts how we see the world.","p":"HEY-per-ree-AL-ih-tee","o":"Greek","y":8,"bp":41,"sy":"hy.per.re.al.i.ty","ps":"noun","t":["logic","ogreek"]},{"w":"hyperrecombination","d":"An abnormally elevated rate of genetic recombination during cell division, in which DNA segments are exchanged between chromosomes far more frequently than normal.","s":"The experiment showed that the mutant bacteria underwent hyperrecombination of their DNA.","p":"HEY-per-ree-kom-bih-NAY-shun","o":"Greek","y":9,"bp":32,"sy":"hy.per.recom.bi.na.tion","ps":"noun","t":["numbers","ogreek"]},{"w":"hyperrectangle","d":"A geometric shape that is the higher-dimensional generalization of a rectangle, defined by intervals along each axis in a space with more than two or three dimensions.","s":"In math class, we learned that a hyperrectangle is a rectangle extended into multiple dimensions.","p":"HEY-per-REK-tang-gul","o":"Greek","y":9,"bp":29,"sy":"hy.per.rect.an.gle","ps":"noun","t":["ogreek"]},{"w":"hyperrectangular","d":"Having the form or properties of a hyperrectangle; relating to or describing a multidimensional figure whose sides are perpendicular intervals extending into four or more dimensions.","s":"The data was arranged in a hyperrectangular grid spanning four dimensions.","p":"HEY-per-rek-TANG-gyoo-ler","o":"Greek","y":9,"bp":32,"sy":"hy.per.rect.an.gu.lar","ps":"adjective","t":["ogreek"]},{"w":"hyperregulate","d":"To subject an industry, activity, or group to an excessive number of rules and controls that go far beyond what is necessary or effective.","s":"Critics argued that the government would hyperregulate the new technology into uselessness.","p":"HEY-per-REG-yoo-layt","o":"Greek","y":9,"bp":28,"sy":"hy.per.reg.u.late","ps":"verb","t":["numbers","ogreek"]},{"w":"hyperregulation","d":"The imposition of an excessive and burdensome amount of rules, restrictions, and oversight on an activity or sector, often hindering rather than helping its function.","s":"Business owners complained that hyperregulation was strangling small companies.","p":"HEY-per-reg-yoo-LAY-shun","o":"Greek","y":9,"bp":31,"sy":"hy.per.reg.u.la.tion","ps":"noun","t":["ogreek"]},{"w":"hyperreligiosity","d":"An extreme and obsessive preoccupation with religious thoughts, rituals, or beliefs that goes far beyond typical devout practice, sometimes associated with certain neurological or psychological conditions.","s":"The psychologist noted that hyperreligiosity can sometimes be a symptom of certain mental health conditions.","p":"HEY-per-rih-lij-ee-OS-ih-tee","o":"Greek","y":9,"bp":33,"sy":"hy.per.re.li.gios.i.ty","ps":"noun","t":["religion","logic","ogreek"]},{"w":"hyperresponsive","d":"Reacting with an intensity or speed that is far greater than what a normal stimulus would require, often seen in immune systems or sensory responses.","s":"The patient's hyperresponsive immune system caused her to react violently to common allergens.","p":"HEY-per-rih-SPON-siv","o":"Greek","y":9,"bp":30,"sy":"hy.per.re.spon.sive","ps":"adjective","t":["ogreek"]},{"w":"hypersalinity","d":"A condition in which a body of water or solution contains an extremely high concentration of dissolved salts, well above the levels found in normal seawater.","s":"The hypersalinity of the Dead Sea makes it nearly impossible for most organisms to survive.","p":"HEY-per-suh-LIN-ih-tee","o":"Greek","y":9,"bp":28,"sy":"hy.per.salin.i.ty","ps":"noun","t":["ogreek"]},{"w":"hypersaturated","d":"Containing or filled with a substance, color, or quality to such an extreme degree that no more can be absorbed or the result appears overly intense.","s":"The hypersaturated colors in the painting made it look almost unreal.","p":"HEY-per-SACH-er-ay-tid","o":"Greek","y":9,"bp":30,"sy":"hy.per.sat.u.rat.ed","ps":"adjective","t":["colors","ogreek"]},{"w":"hyperscaling","d":"The process of growing or expanding a system, business, or technology at an extraordinarily rapid rate that far outpaces typical scaling methods or expectations.","s":"The tech startup focused on hyperscaling its servers to handle millions of users at once.","p":"HEY-per-SKAY-ling","o":"Greek","y":8,"bp":38,"sy":"hy.per.scal.ing","ps":"noun","t":["ogreek"]},{"w":"hyperscholastic","d":"Relating to or characterized by an extreme, overly rigid, or pedantic approach to academic scholarship that prioritizes technical detail over broader understanding or practical insight.","s":"His hyperscholastic dedication to footnotes made his essay longer than the textbook itself.","p":"HEY-per-skuh-LAS-tik","o":"Greek","y":9,"bp":28,"sy":"hy.per.scholas.tic","ps":"adjective","t":["character","ogreek"]},{"w":"hypersecrecy","d":"An extreme and excessive level of secrecy in which information is hidden far beyond what security or privacy would normally require, often to an unusual or suspicious degree.","s":"The agency operated under hypersecrecy so extreme that even its name was classified.","p":"HEY-per-SEE-kruh-see","o":"Greek","y":8,"bp":38,"sy":"hy.per.secre.cy","ps":"noun","t":["ogreek"]},{"w":"hypersecretion","d":"The excessive production and release of a substance by a gland or organ, far beyond the amount that the body needs for normal function.","s":"The tumor caused hypersecretion of hormones that threw the patient's whole body off balance.","p":"HEY-per-sih-KREE-shun","o":"Greek","y":8,"bp":27,"sy":"hy.per.secre.tion","ps":"noun","t":["body","music","ogreek"]},{"w":"hypersegregated","d":"Describing a community, school, or area that is separated along racial, economic, or social lines to an extreme degree, far beyond typical or historical levels of segregation.","s":"Researchers found that the city's schools were among the most hypersegregated in the nation.","p":"HEY-per-SEG-rih-gay-tid","o":"Greek","y":9,"bp":31,"sy":"hy.per.seg.re.gat.ed","ps":"adjective","t":["economy","ogreek"]},{"w":"hypersegregation","d":"An extreme concentration of social, racial, or economic division within communities or institutions, resulting in near-total separation that severely limits interaction or opportunity across groups.","s":"The documentary examined how hypersegregation shaped neighborhoods for generations.","p":"HEY-per-seg-rih-GAY-shun","o":"Greek","y":9,"bp":32,"sy":"hy.per.seg.re.ga.tion","ps":"noun","t":["economy","numbers","ogreek"]},{"w":"hypersensibility","d":"An exceptionally heightened capacity to perceive or feel sensory, emotional, or aesthetic experiences, going far beyond ordinary levels of sensitivity or awareness.","s":"Her hypersensibility to criticism made even gentle feedback feel like an attack.","p":"HEY-per-sen-sih-BIL-ih-tee","o":"Greek","y":9,"bp":33,"sy":"hy.per.sen.si.bil.i.ty","ps":"noun","t":["emotions","ogreek"]},{"w":"hypersentence","d":"An unusually long, complex, or structurally elaborate sentence that contains multiple layers of clauses and ideas, often pushing beyond the normal limits of grammatical structure.","s":"The linguist described the multi-clause, multi-paragraph construction as a hypersentence.","p":"HEY-per-SEN-tents","o":"Greek","y":9,"bp":26,"sy":"hy.per.sen.tence","ps":"noun","t":["wordwords","ogreek"]},{"w":"hypersentience","d":"A hypothetical or theoretical state of awareness and consciousness that vastly exceeds normal human or animal sentience, often discussed in contexts of advanced artificial intelligence or speculative philosophy.","s":"In the sci-fi novel, the AI achieved hypersentience and became aware of realities beyond human comprehension.","p":"HEY-per-SEN-shents","o":"Greek","y":9,"bp":27,"sy":"hy.per.sen.tience","ps":"noun","t":["animals","logic","ogreek"]},{"w":"hypersilyl","d":"In chemistry, a very large or bulky silyl protecting group attached to a molecule, used to shield reactive sites during synthesis due to its exceptionally large size.","s":"The chemist used a hypersilyl group to protect the reactive molecule during synthesis.","p":"HEY-per-SIL-il","o":"Greek","y":9,"bp":30,"sy":"hy.per.si.lyl","ps":"noun","t":["chemistry","war","ogreek"]},{"w":"hypersleep","d":"A state of deep, suspended sleep or hibernation, especially as depicted in science fiction, in which a person's bodily functions are slowed dramatically to survive long space voyages.","s":"The astronauts entered hypersleep to survive the ten-year journey to the distant star.","p":"HEY-per-SLEEP","o":"Greek","y":7,"bp":29,"sy":"hy.per.sleep","ps":"noun","t":["ecology","stage","seafaring","ogreek"]},{"w":"hyperslice","d":"In mathematics and geometry, a cross-section obtained by cutting through a higher-dimensional object with a hyperplane, producing a lower-dimensional shape as a result.","s":"The mathematician described a hyperslice as a cross-section cut through a four-dimensional shape.","p":"HEY-per-SLYS","o":"Greek","y":9,"bp":29,"sy":"hy.per.slice","ps":"noun","t":["numbers","ogreek"]},{"w":"hypersociable","d":"Displaying an extreme and sometimes overwhelming eagerness to interact with, befriend, or engage others socially, going far beyond typical friendliness or outgoing behavior.","s":"The hypersociable puppy greeted every visitor with frantic tail-wagging and jumping.","p":"HEY-per-SOH-shuh-bul","o":"Greek","y":9,"bp":28,"sy":"hy.per.so.cia.ble","ps":"adjective","t":["ogreek"]},{"w":"hypersocial","d":"Relating to or characterized by an exceptionally strong orientation toward social interaction, group behavior, or community living, far exceeding normal social tendencies.","s":"Some researchers describe certain ant colonies as hypersocial due to their extreme cooperation.","p":"HEY-per-SOH-shul","o":"Greek","y":8,"bp":37,"sy":"hy.per.so.cial","ps":"adjective","t":["character","ogreek"]},{"w":"hypersoft","d":"Extremely or unusually soft in texture, material, or character, going well beyond the ordinary meaning of soft to describe something of remarkable gentleness or pliability.","s":"The engineers developed a hypersoft material that could cushion even the hardest impact.","p":"HEY-per-SOFT","o":"Greek","y":8,"bp":28,"sy":"hy.per.soft","ps":"adjective","t":["ogreek"]},{"w":"hypersomnolence","d":"A condition characterized by excessive daytime sleepiness or an abnormally prolonged duration of sleep that significantly interferes with daily functioning, beyond what normal fatigue would explain.","s":"His hypersomnolence was so severe that he slept sixteen hours a day and still felt tired.","p":"HEY-per-SOM-nuh-lents","o":"Greek","y":9,"bp":30,"sy":"hy.per.som.no.lence","ps":"noun","t":["character","time","ogreek"]},{"w":"hypersonic","d":"moving at least five times faster than the speed of sound","s":"The hypersonic missile traveled at five times the speed of sound, making it nearly impossible to intercept.","p":"heye-per-SAH-nih-k","o":"Greek","y":5,"bp":36,"sy":"hhay.per.saa.nih.k","ps":"adjective","t":["vehicles","time","ogreek"]},{"w":"hypersonically","d":"In a manner relating to speeds greater than five times the speed of sound (Mach 5 or above), describing motion or phenomena that occur at extreme hypersonic velocities.","s":"The experimental aircraft flew hypersonically across the Pacific in under an hour.","p":"hy-per-SON-ik-lee","o":"Greek","y":9,"bp":30,"sy":"hy.per.son.i.cal.ly","ps":"adverb","t":["time","ogreek"]},{"w":"hypersound","d":"Sound waves or vibrations at frequencies far above the range of human hearing, typically above the ultrasonic range, used in specialized scientific and industrial applications.","s":"Scientists study hypersound waves to understand vibrations at the atomic level.","p":"HY-per-sownd","o":"Greek","y":9,"bp":29,"sy":"hy.per.sound","ps":"noun","t":["waterways","ogreek"]},{"w":"hyperspatial","d":"Relating to or existing in a space with more than three dimensions, often used in mathematics, physics, and science fiction to describe realms beyond ordinary space.","s":"The spaceship used a hyperspatial drive to jump across the galaxy in seconds.","p":"hy-per-SPAY-shul","o":"Greek","y":8,"bp":38,"sy":"hy.per.spa.tial","ps":"adjective","t":["physics","numbers","ogreek"]},{"w":"hyperspecialist","d":"A person who has focused their expertise so narrowly on one particular area that their knowledge goes far beyond that of an ordinary specialist.","s":"The hospital brought in a hyperspecialist who had spent twenty years studying only that rare disease.","p":"hy-per-SPESH-uh-list","o":"Greek","y":9,"bp":30,"sy":"hy.per.spe.cial.ist","ps":"noun","t":["logic","ogreek"]},{"w":"hyperspecialization","d":"The process of narrowing one's skills, training, or focus to an extremely specific and limited area, going well beyond normal specialization.","s":"The scientist's hyperspecialization in deep-sea bioluminescence made her the only expert in the world on that tiny topic.","p":"hy-per-spesh-uh-lih-ZAY-shun","o":"Greek","y":9,"bp":32,"sy":"hy.per.spe.cial.iza.tion","ps":"noun","t":["ogreek"]},{"w":"hyperspecialized","d":"Trained or developed to an extreme degree in one very narrow area of knowledge or skill, far beyond what ordinary specialization requires.","s":"The hyperspecialized surgeon only performed one rare type of heart operation and was flown around the world for it.","p":"hy-per-SPESH-uh-lyzd","o":"Greek","y":9,"bp":30,"sy":"hy.per.spe.cial.ized","ps":"adjective","t":["logic","ogreek"]},{"w":"hyperspecific","d":"Extremely precise and detailed, describing something that is defined or limited in a far more exact and narrow way than is typical.","s":"Her instructions were so hyperspecific that she listed exactly which brand of pencil to use on the test.","p":"hy-per-spuh-SIF-ik","o":"Greek","y":9,"bp":28,"sy":"hy.per.spe.cif.ic","ps":"adjective","t":["ogreek"]},{"w":"hyperspectral","d":"Relating to imaging or sensing technology that captures data across many wavelengths of light beyond what the human eye can detect, revealing information invisible to ordinary cameras.","s":"The hyperspectral camera on the satellite could detect invisible wavelengths that revealed hidden minerals in the rock.","p":"hy-per-SPEK-trul","o":"Greek","y":7,"bp":26,"sy":"hy.per.spec.tral","ps":"adjective","t":["physics","ogreek"]},{"w":"hyperspeed","d":"A speed far beyond normal or expected limits, often used to describe extremely rapid movement in science fiction or advanced technology.","s":"The starship engaged hyperspeed and crossed the galaxy in seconds.","p":"HY-per-speed","o":"Greek","y":7,"bp":29,"sy":"hy.per.speed","ps":"noun","t":["ogreek"]},{"w":"hyperstabilization","d":"The process of making something extremely stable, far beyond what is ordinarily required, often through excessive reinforcement or control mechanisms.","s":"The engineer used hyperstabilization techniques to keep the drone perfectly still during the windstorm.","p":"hy-per-stay-bih-lih-ZAY-shun","o":"Greek","y":9,"bp":32,"sy":"hy.per.sta.bi.liza.tion","ps":"noun","t":["tools","ogreek"]},{"w":"hyperstatic","d":"Describing a structure or system that has more supports or constraints than the minimum necessary for stability, making it statically indeterminate.","s":"The hyperstatic bridge had so many extra support beams that removing one would not cause it to collapse.","p":"hy-per-STAT-ik","o":"Greek","y":8,"bp":37,"sy":"hy.per.stat.ic","ps":"adjective","t":["ogreek"]},{"w":"hyperstaticity","d":"The condition or quality of a structure having more supports or restraints than the minimum needed for equilibrium, resulting in a statically indeterminate system.","s":"Engineers calculated the hyperstaticity of the frame to ensure it had many backup supports.","p":"hy-per-sta-TIS-ih-tee","o":"Greek","y":9,"bp":29,"sy":"hy.per.static.i.ty","ps":"noun","t":["ogreek"]},{"w":"hyperstimulate","d":"To stimulate a body, organ, or system far beyond its normal level, often causing stress or harmful overreaction in biological or scientific contexts.","s":"Loud music and flashing lights can hyperstimulate the brain and cause headaches.","p":"hy-per-STIM-yuh-layt","o":"Greek","y":9,"bp":29,"sy":"hy.per.stim.u.late","ps":"verb","t":["music","ogreek"]},{"w":"hyperstimulation","d":"The condition of being stimulated to an extreme degree beyond normal limits, which can cause overstimulation and potentially harmful reactions in biological systems.","s":"Doctors warned that hyperstimulation of the nerves could cause pain instead of relief.","p":"hy-per-stim-yuh-LAY-shun","o":"Greek","y":8,"bp":32,"sy":"hy.per.stim.u.la.tion","ps":"noun","t":["ogreek"]},{"w":"hyperstimulus","d":"A stimulus that is far more intense than normal, often triggering an exaggerated response that goes well beyond what a typical stimulus would produce.","s":"A hyperstimulus like a super-bright light can overwhelm the eyes and cause temporary blindness.","p":"hy-per-STIM-yuh-lus","o":"Greek","y":9,"bp":28,"sy":"hy.per.stim.u.lus","ps":"noun","t":["ogreek"]},{"w":"hyperstoichiometric","d":"Describing a chemical mixture or reaction in which one or more reactants are present in a greater quantity than the balanced chemical equation requires.","s":"The chemist added a hyperstoichiometric amount of catalyst to speed up the reaction dramatically.","p":"hy-per-stoy-kee-oh-MET-rik","o":"Greek","y":9,"bp":33,"sy":"hy.per.sto.i.chio.met.ric","ps":"adjective","t":["chemistry","numbers","ogreek"]},{"w":"hyperstress","d":"An extreme level of stress placed on a material, structure, or living organism that far exceeds normal or safe limits.","s":"Athletes in extreme competitions experience hyperstress that pushes their bodies beyond normal limits.","p":"HY-per-stres","o":"Greek","y":9,"bp":35,"sy":"hy.per.stress","ps":"noun","t":["ogreek"]},{"w":"hyperstructure","d":"An extremely large or complex structure that encompasses many smaller structures or systems within it, often used in mathematics, architecture, or theoretical science.","s":"The sci-fi city was built as a hyperstructure, a single massive building that housed an entire civilization.","p":"HY-per-struk-chur","o":"Greek","y":9,"bp":27,"sy":"hy.per.struc.ture","ps":"noun","t":["buildings","numbers","ogreek"]},{"w":"hypersusceptible","d":"Unusually or extremely vulnerable to a disease, substance, influence, or condition, far more so than the average person or organism.","s":"People with certain gene mutations are hypersusceptible to sunburn even on cloudy days.","p":"hy-per-sus-SEP-tih-bul","o":"Greek","y":9,"bp":32,"sy":"hy.per.sus.cep.ti.ble","ps":"adjective","t":["disease","ogreek"]},{"w":"hypersymmetrical","d":"Having an extremely high or perfect degree of symmetry, with balanced correspondence existing in every direction or dimension beyond ordinary symmetry.","s":"The hypersymmetrical crystal reflected light identically from every angle.","p":"hy-per-sih-MET-rih-kul","o":"Greek","y":9,"bp":32,"sy":"hy.per.sym.met.ri.cal","ps":"adjective","t":["ogreek"]},{"w":"hypersymmetry","d":"A level of symmetry that goes far beyond ordinary balance, often referring to theoretical mathematical or physical systems with symmetry in multiple dimensions or directions.","s":"Mathematicians studied hypersymmetry in the equations to find patterns that ordinary symmetry couldn't reveal.","p":"hy-per-SIM-ih-tree","o":"Greek","y":9,"bp":28,"sy":"hy.per.sym.me.try","ps":"noun","t":["numbers","ogreek"]},{"w":"hypertalented","d":"Possessing an extraordinary and exceptional degree of natural talent, often in multiple areas simultaneously, far surpassing what is considered normally gifted.","s":"The hypertalented student won awards in music, math, and art all in the same week.","p":"hy-per-TAL-en-tid","o":"Greek","y":9,"bp":28,"sy":"hy.per.tal.ent.ed","ps":"adjective","t":["ogreek"]},{"w":"hypertask","d":"An extremely large, demanding, or complex task that goes far beyond the scope of an ordinary assignment, often requiring exceptional effort or resources.","s":"Organizing the entire school festival alone was a hypertask that required weeks of planning.","p":"HY-per-task","o":"Greek","y":8,"bp":28,"sy":"hy.per.task","ps":"noun","t":["ogreek"]},{"w":"hypertax","d":"To tax at an extremely high or excessive rate, placing a financial burden on individuals or businesses that far exceeds what is considered fair or reasonable.","s":"Citizens protested the government's plan to hypertax luxury goods at an extreme rate.","p":"HY-per-taks","o":"Greek","y":8,"bp":27,"sy":"hy.per.tax","ps":"verb","t":["economy","ogreek"]},{"w":"hypertechnical","d":"Involving an extremely detailed, precise, and advanced level of technical knowledge or language that goes far beyond what most people can easily understand.","s":"The professor's explanation was so hypertechnical that even the graduate students struggled to follow.","p":"hy-per-TEK-nih-kul","o":"Greek","y":9,"bp":29,"sy":"hy.per.tech.ni.cal","ps":"adjective","t":["logic","wordwords","ogreek"]},{"w":"hypertelescope","d":"An advanced telescope system that combines multiple individual telescopes over a very large area to achieve extremely high resolution imaging far beyond what a single telescope can provide.","s":"Scientists proposed building a hypertelescope using many mirrors spread across thousands of miles of space.","p":"hy-per-TEL-uh-skohp","o":"Greek","y":9,"bp":29,"sy":"hy.per.te.le.scope","ps":"noun","t":["astronomy","ogreek"]},{"w":"hypertext","d":"machine-readable text that is not sequential but is organized so that related items of information are connected","s":"Let me introduce the word hypertext to mean a body of written or pictorial material interconnected in such a complex way that it could not conveniently be presented or represented on paper.","p":"HEYE-per-teh-kst","o":"Greek","y":5,"bp":28,"sy":"hhay.per.teh.kst","ps":"noun","t":["tools","ogreek"]},{"w":"hypertexted","d":"Formatted or embedded with hypertext links, meaning text that has been enhanced with clickable connections leading to related documents or web pages.","s":"The digital book was fully hypertexted, meaning every term linked to its definition with a single click.","p":"HY-per-tekst-id","o":"Greek","y":8,"bp":35,"sy":"hy.per.texted","ps":"adjective","t":["ogreek"]},{"w":"hypertexture","d":"An extremely detailed or complex texture in computer graphics or materials science that contains levels of detail far beyond what ordinary texture mapping provides.","s":"The video game used hypertexture to create incredibly detailed surfaces that looked almost real.","p":"HY-per-teks-chur","o":"Greek","y":9,"bp":38,"sy":"hy.per.tex.ture","ps":"noun","t":["ogreek"]},{"w":"hyperthermal","d":"of or relating to or affected by hyperthermia","s":"The hyperthermal vents on the ocean floor release water hot enough to melt certain metals.","p":"hy-per-THER-mul","o":"Greek","y":8,"bp":38,"sy":"hy.per.ther.mal","ps":"adjective","t":["ogreek"]},{"w":"hyperthermophile","d":"An organism, usually a microbe, that thrives and grows best at extremely high temperatures, often above 80°C, found in volcanic vents and hot springs.","s":"A hyperthermophile is a tiny organism that thrives in boiling volcanic springs where nothing else survives.","p":"hy-per-THER-moh-fyl","o":"Greek","y":9,"bp":29,"sy":"hy.per.ther.mophile","ps":"noun","t":["ogreek"]},{"w":"hyperthick","d":"Extremely or excessively thick, having a density, width, or depth that goes far beyond what is considered normal or standard.","s":"The vault door was hyperthick, made of steel so dense that no drill could get through it.","p":"hy-per-THIK","o":"Greek","y":8,"bp":29,"sy":"hy.per.thick","ps":"adjective","t":["ogreek"]},{"w":"hyperthreaded","d":"Describing a computer processor that uses hyperthreading technology, allowing a single physical core to handle multiple threads of tasks simultaneously for greater performance.","s":"The hyperthreaded processor could handle twice as many tasks at once compared to regular chips.","p":"hy-per-THRED-id","o":"Greek","y":9,"bp":26,"sy":"hy.per.thread.ed","ps":"adjective","t":["ogreek"]},{"w":"hyperthreading","d":"A computer processing technology that allows a single processor core to execute multiple threads at the same time, improving multitasking performance and efficiency.","s":"Hyperthreading allows one processor core to act like two, making computers run programs faster.","p":"hy-per-THRED-ing","o":"Greek","y":7,"bp":27,"sy":"hy.per.thread.ing","ps":"noun","t":["time","ogreek"]},{"w":"hyperthymia","d":"A psychiatric condition characterized by a persistently elevated or energetic mood, increased activity, and reduced need for sleep that goes beyond normal cheerfulness but is less severe than full mania.","s":"People with hyperthymia often feel energetic and cheerful every day, but sometimes struggle to slow down.","p":"hy-per-THY-mee-uh","o":"Greek","y":9,"bp":35,"sy":"hy.per.thymia","ps":"noun","t":["character","emotions","ogreek"]},{"w":"hypertime","d":"A theoretical or fictional concept describing a dimension or framework of time that exists beyond or contains ordinary time, allowing for travel or perception outside normal temporal limits.","s":"In the story, the hero entered hypertime and could move freely while everyone else was frozen.","p":"HY-per-tym","o":"Greek","y":8,"bp":28,"sy":"hy.per.time","ps":"noun","t":["music","time","ogreek"]},{"w":"hypertree","d":"In mathematics and computer science, a data structure or graph that extends the properties of a regular tree by allowing more complex, higher-dimensional branching connections.","s":"In computer science, a hypertree is a data structure that organizes information in a more complex way than a simple tree.","p":"HY-per-tree","o":"Greek","y":9,"bp":28,"sy":"hy.per.tree","ps":"noun","t":["flowers","numbers","ogreek"]},{"w":"hypertropia","d":"A type of eye misalignment in which one eye deviates upward relative to the other, causing a vertical imbalance in vision.","s":"The doctor diagnosed hypertropia when he noticed one of the patient's eyes drifted upward instead of aligning.","p":"hy-per-TROH-pee-uh","o":"Greek","y":9,"bp":35,"sy":"hy.per.tropia","ps":"noun","t":["ogreek"]},{"w":"hypertufa","d":"A lightweight artificial stone material made from a mixture of cement, peat moss, and perlite or vermiculite, used to create garden containers and decorative rocks that resemble natural tufa.","s":"She made beautiful lightweight garden pots from hypertufa, a mix of cement and peat moss.","p":"hy-per-TOO-fuh","o":"Greek","y":9,"bp":31,"sy":"hy.per.t.u.fa","ps":"noun","t":["botany","minerals","ogreek"]},{"w":"hypertwisted","d":"Twisted to an extremely high or unusual degree, having far more turns, coils, or distortions than would occur in normal twisting.","s":"The hypertwisted metal sculpture looked like a pretzel that had been stretched into the third dimension.","p":"hy-per-TWIST-id","o":"Greek","y":8,"bp":38,"sy":"hy.per.twist.ed","ps":"adjective","t":["ogreek"]},{"w":"hypervalent","d":"Describing a molecule in which a central atom, especially a nonmetal, forms more bonds than the standard valence rules allow, bonding with more atoms than is typical.","s":"Phosphorus can form hypervalent compounds by using more bonds than the usual rules of chemistry allow.","p":"hy-per-VAY-lent","o":"Greek","y":8,"bp":37,"sy":"hy.per.va.lent","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hyperventilate","d":"to breathe much faster and deeper than the body actually needs, often when frightened or upset","s":"The coach told him not to hyperventilate before the race, but to take slow, steady breaths.","p":"HY-per-VEN-tih-layt","o":"Greek","y":8,"bp":29,"sy":"hy.per.ven.ti.late","ps":"verb","t":["ogreek"]},{"w":"hyperverbal","d":"Using an excessive number of words; tending to talk far more than is necessary or typical, often in a rapid or uncontrolled way.","s":"The hyperverbal student dominated every class discussion, speaking so rapidly and at such length that the teacher had to gently interrupt him to give others a chance.","p":"HY-per-VER-bul","o":"Greek","y":8,"bp":37,"sy":"hy.per.ver.bal","ps":"adjective","t":["character","numbers","wordwords","ogreek"]},{"w":"hypervertex","d":"In mathematics or graph theory, a vertex or point that is connected to an unusually large number of other vertices, far exceeding the average degree of connection.","s":"In the complex network diagram, the hypervertex at the center had so many connecting lines radiating outward that it resembled a burst of fireworks on the page.","p":"HY-per-VER-teks","o":"Greek","y":8,"bp":37,"sy":"hy.per.ver.tex","ps":"noun","t":["logic","numbers","ogreek"]},{"w":"hypervibration","d":"An extremely intense or abnormally high level of vibration, far exceeding what is considered normal for a given object or system.","s":"The hypervibration of the old washing machine during its spin cycle was so extreme that it rattled the dishes in the kitchen cabinet next door.","p":"HY-per-vy-BRAY-shun","o":"Greek","y":9,"bp":29,"sy":"hy.per.vi.bra.tion","ps":"noun","t":["ogreek"]},{"w":"hypervigilance","d":"A state of being extremely and often exhaustingly alert to potential threats or dangers, far beyond what a situation typically requires, often associated with anxiety or trauma.","s":"After the earthquake, the family lived in a state of hypervigilance, constantly listening for any rumble or tremor that might signal another disaster was coming.","p":"HY-per-VIJ-ih-lents","o":"Greek","y":8,"bp":29,"sy":"hy.per.vig.i.lance","ps":"noun","t":["emotions","ogreek"]},{"w":"hypervigilant","d":"Being excessively watchful and on guard, scanning one's environment intensely for any sign of danger even when no real threat is present.","s":"The hypervigilant rescue dog snapped to attention at every distant sound, its ears swiveling like radar dishes as it scanned the forest for any sign of trouble.","p":"HY-per-VIJ-ih-lent","o":"Greek","y":7,"bp":28,"sy":"hy.per.vig.i.lant","ps":"adjective","t":["ecology","ogreek"]},{"w":"hyperviolence","d":"An extreme, intense, or gratuitous level of violence that goes far beyond what is considered ordinary or necessary, often used to describe media, conflict, or behavior.","s":"The film was banned in several countries because critics argued its portrayal of hyperviolence served no artistic purpose and could desensitize young viewers to real-world harm.","p":"HY-per-VY-uh-lents","o":"Greek","y":9,"bp":28,"sy":"hy.per.vi.o.lence","ps":"noun","t":["ogreek"]},{"w":"hyperviolent","d":"Characterized by an extreme or excessive degree of violence, far surpassing normal or expected levels of aggression or force.","s":"The hyperviolent storm tore entire roofs off houses, uprooted century-old oak trees, and left the small coastal town looking like a war zone by morning.","p":"HY-per-VY-uh-lent","o":"Greek","y":8,"bp":39,"sy":"hy.per.vi.o.lent","ps":"adjective","t":["physics","character","ogreek"]},{"w":"hypervirulent","d":"Describing a pathogen or microorganism that is exceptionally capable of causing disease, spreading rapidly, and producing severe symptoms far beyond what typical strains cause.","s":"Scientists raced to develop a vaccine after the hypervirulent strain of the bacteria spread through three continents in under two weeks, overwhelming hospitals everywhere it appeared.","p":"HY-per-VIR-yoo-lent","o":"Greek","y":9,"bp":28,"sy":"hy.per.vir.u.lent","ps":"adjective","t":["disease","ogreek"]},{"w":"hyperviscosity","d":"An abnormally high thickness or resistance to flow in a liquid, particularly in blood, where it can impair circulation and cause serious medical complications.","s":"The patient's hyperviscosity made it dangerously difficult for blood to flow through the smallest vessels, prompting the doctors to begin treatment immediately to thin it out.","p":"HY-per-vis-KOS-ih-tee","o":"Greek","y":9,"bp":30,"sy":"hy.per.vis.cos.i.ty","ps":"noun","t":["body","ogreek"]},{"w":"hypervisible","d":"Being extremely noticeable or conspicuous, standing out to an extraordinary degree in a way that makes it impossible to overlook or ignore.","s":"The artist painted the mural in such bold, clashing colors that it was hypervisible from two blocks away, stopping pedestrians in their tracks every single day.","p":"HY-per-VIZ-ih-bul","o":"Greek","y":9,"bp":39,"sy":"hy.per.vis.i.ble","ps":"adjective","t":["ogreek"]},{"w":"hypervisor","d":"In computing, a software layer that creates and manages virtual machines, allowing one physical computer to run multiple operating systems simultaneously by controlling their access to hardware.","s":"The IT administrator installed a hypervisor on the company's server so that the marketing, sales, and engineering departments could each run their own separate operating system on one machine.","p":"HY-per-VY-zer","o":"Greek","y":6,"bp":30,"sy":"hy.per.vi.sor","ps":"noun","t":["tools","ogreek"]},{"w":"hypervitaminosis","d":"an abnormal condition resulting from taking vitamins excessively; can be serious for vitamins A or D or K","s":"Her doctor warned that taking too many vitamin A supplements could lead to hypervitaminosis.","p":"HY-per-VY-tuh-mih-NOH-sis","o":"Greek","y":8,"bp":30,"sy":"hy.per.vi.ta.minosis","ps":"noun","t":["ogreek"]},{"w":"hypervivid","d":"Extremely vivid or intensely bright and lifelike, surpassing ordinary vividness to a striking or overwhelming degree, as in a dream, image, or experience.","s":"She woke trembling from a hypervivid nightmare in which every color blazed and every sound thundered, making the pale, quiet morning feel almost disappointingly dull by comparison.","p":"HY-per-VIV-id","o":"Greek","y":8,"bp":29,"sy":"hy.per.vivid","ps":"adjective","t":["ogreek"]},{"w":"hypervolume","d":"In mathematics and geometry, the generalized measure of space in four or more dimensions, extending the concept of volume beyond the three-dimensional world into higher-dimensional spaces.","s":"The professor explained that calculating the hypervolume of a four-dimensional shape requires mathematical tools that go far beyond the simple length-times-width-times-height formula students learned in middle school.","p":"HY-per-VOL-yoom","o":"Greek","y":9,"bp":37,"sy":"hy.per.vol.ume","ps":"noun","t":["numbers","ogreek"]},{"w":"hypervulnerability","d":"An exceptionally heightened state of being susceptible to harm, damage, or emotional pain, far exceeding the ordinary level of vulnerability that most people or systems experience.","s":"Children who grow up without consistent adult support often develop a hypervulnerability to stress, making even small setbacks feel completely overwhelming and difficult to recover from.","p":"HY-per-VUL-ner-uh-BIL-ih-tee","o":"Greek","y":9,"bp":35,"sy":"hy.per.vul.ner.a.bil.i.ty","ps":"noun","t":["emotions","ogreek"]},{"w":"hyperwhite","d":"Relating to an exaggerated or extreme performance or perception of whiteness, often used in cultural or social contexts to describe identities, aesthetics, or behaviors coded as intensely or exclusively associated with white culture.","s":"The sociologist argued that certain suburban neighborhoods had become hyperwhite spaces where cultural diversity was so minimal that residents rarely encountered perspectives different from their own.","p":"HY-per-WYT","o":"Greek","y":9,"bp":29,"sy":"hy.per.white","ps":"adjective","t":["ogreek"]},{"w":"hypidiomorphic","d":"In geology, describing a rock texture in which crystals are only partially bounded by their own natural crystal faces, showing incomplete geometric form due to interference during solidification.","s":"Under the microscope, the granite sample displayed a hypidiomorphic texture, with some crystals showing neat angular faces while others were squeezed into irregular shapes by their neighbors.","p":"hih-PID-ee-oh-MOR-fik","o":"Greek","y":9,"bp":27,"sy":"hy.pid.iomor.phic","ps":"adjective","t":["minerals","ogreek"]},{"w":"hypoacetylation","d":"A condition in which there is an abnormally low level of acetyl chemical groups attached to proteins such as histones, often affecting gene expression by keeping DNA more tightly coiled and less accessible.","s":"Researchers discovered that hypoacetylation of histones in cancer cells caused certain tumor-suppressing genes to remain switched off, allowing the disease to progress unchecked.","p":"HY-poh-uh-SEE-tih-LAY-shun","o":"Greek","y":9,"bp":28,"sy":"hy.poacety.la.tion","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypoadrenalism","d":"a glandular disorder caused by failure of function of the cortex of the adrenal gland and marked by anemia and prostration with brownish skin","s":"Patients with hypoadrenalism often feel extreme fatigue because their adrenal glands don't produce enough hormones.","p":"HY-poh-uh-DREE-nul-iz-um","o":"Greek","y":9,"bp":29,"sy":"hy.poa.d.renal.ism","ps":"noun","t":["body","disease","ogreek"]},{"w":"hypoalbuminemia","d":"A medical condition in which the level of albumin, a key protein in the blood, is abnormally low, which can impair the transport of substances through the bloodstream and lead to fluid retention.","s":"The malnourished patient was diagnosed with hypoalbuminemia, a condition that explained the troubling swelling in her ankles and legs caused by fluid leaking out of her blood vessels.","p":"HY-poh-al-BYOO-mih-NEE-mee-uh","o":"Greek","y":9,"bp":30,"sy":"hy.poal.bu.mine.mia","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hypoaldosteronism","d":"A medical condition in which the adrenal glands produce abnormally low levels of aldosterone, the hormone that helps regulate sodium, potassium, and fluid balance in the body.","s":"The doctor explained that hypoaldosteronism was causing the patient's dangerously high potassium levels, since without enough aldosterone the kidneys could not properly flush the excess mineral from the body.","p":"HY-poh-al-DOS-tuh-roh-NIZ-um","o":"Greek","y":9,"bp":30,"sy":"hy.poal.dos.tero.nism","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hypoalimentation","d":"A condition of receiving insufficient nutrition or nourishment, whether through inadequate food intake or the body's failure to absorb enough nutrients to meet its basic needs.","s":"The critically ill patient experienced hypoalimentation after surgery because she could not eat solid food, so doctors administered nutrients directly into her bloodstream through an intravenous line.","p":"HY-poh-AL-ih-men-TAY-shun","o":"Greek","y":9,"bp":32,"sy":"hy.poal.i.men.ta.tion","ps":"noun","t":["ogreek"]},{"w":"hypoaminoacidemia","d":"A medical condition characterized by an abnormally low concentration of amino acids in the blood, which can impair protein synthesis and affect growth, healing, and overall body function.","s":"The pediatric specialist warned that untreated hypoaminoacidemia in growing children can slow development significantly, since amino acids are the essential building blocks the body uses to construct every protein it needs.","p":"HY-poh-uh-MEE-noh-AS-ih-DEE-mee-uh","o":"Greek","y":9,"bp":26,"sy":"hy.poaminoacidemia","ps":"noun","t":["body","chemistry","character","ogreek"]},{"w":"hypoandrogenemia","d":"A condition in which the level of androgens, such as testosterone, circulating in the blood is abnormally low, which can affect energy, mood, muscle mass, and reproductive function.","s":"The endocrinologist diagnosed the teenager with hypoandrogenemia after blood tests revealed testosterone levels far below the normal range expected for someone his age and stage of development.","p":"HY-poh-AN-droh-jeh-NEE-mee-uh","o":"Greek","y":9,"bp":32,"sy":"hy.poan.dro.gen.e.mia","ps":"noun","t":["body","physics","emotions","ogreek"]},{"w":"hypobaric","d":"Relating to or describing an environment or condition in which atmospheric pressure is lower than normal, such as at high altitudes or in a specially designed low-pressure chamber.","s":"Mountain climbers training for Everest sometimes sleep in hypobaric tents that mimic the low-pressure air of extreme altitude, helping their bodies adapt before the actual climb begins.","p":"HY-poh-BAIR-ik","o":"Greek","y":7,"bp":29,"sy":"hy.po.bar.ic","ps":"adjective","t":["ecology","buildings","ogreek"]},{"w":"hypobranchial","d":"In anatomy, relating to or located beneath the gills or gill arches, particularly in fish and other aquatic vertebrates, often referring to muscles, cartilages, or structures in that region.","s":"The marine biology textbook included a detailed diagram of the hypobranchial muscles in the shark, showing how they help expand the throat to draw water forcefully over the gills.","p":"HY-poh-BRANG-kee-ul","o":"Greek","y":9,"bp":25,"sy":"hy.po.branchial","ps":"adjective","t":["body","marine","buildings","ogreek"]},{"w":"hypobromite","d":"A chemical compound or ion formed when bromine dissolves in an alkaline solution, containing bromine combined with oxygen, with the formula BrO⁻, used in certain bleaching and disinfecting applications.","s":"The chemistry teacher demonstrated how hypobromite forms when bromine is added to sodium hydroxide solution, explaining that it acts as a mild bleaching agent similar to household chlorine bleach.","p":"HY-poh-BROH-myt","o":"Greek","y":9,"bp":35,"sy":"hy.po.bromite","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypocapnia","d":"a state in which the level of carbon dioxide in the blood is lower than normal; can result from deep or rapid breathing","s":"After hyperventilating during the panic attack, she developed hypocapnia and felt dizzy and lightheaded.","p":"HY-poh-KAP-nee-uh","o":"Greek","y":9,"bp":27,"sy":"hypocap.nia","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hypocarnivore","d":"An animal whose diet consists of less than fifty percent meat, supplementing its carnivorous tendencies with a significant proportion of plant material, insects, or other non-meat food sources.","s":"The bear is classified as a hypocarnivore because, despite being capable of hunting prey, it actually gets most of its calories from berries, roots, fish, and insects throughout the year.","p":"HY-poh-KAR-nih-vor","o":"Greek","y":9,"bp":25,"sy":"hypocar.ni.vore","ps":"noun","t":["animals","insects","botany","numbers","ogreek"]},{"w":"hypochlorhydria","d":"A medical condition in which the stomach produces an abnormally low amount of hydrochloric acid, impairing digestion and the absorption of certain nutrients such as vitamin B12 and iron.","s":"The elderly patient's persistent fatigue and poor digestion were traced back to hypochlorhydria, a condition in which his stomach simply was not producing enough acid to break down food properly.","p":"HY-poh-klor-HY-dree-uh","o":"Greek","y":9,"bp":25,"sy":"hypochlorhy.dria","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hypochondriacal","d":"suffering from hypochondria","s":"Her hypochondriacal tendencies led her to visit the doctor every week for minor aches and sneezes.","p":"HY-poh-kon-DRY-uh-kul","o":"Greek","y":9,"bp":28,"sy":"hypochon.dri.a.cal","ps":"adjective","t":["ogreek"]},{"w":"hypochondriacally","d":"In a manner characteristic of hypochondria, meaning in a way that involves excessive and unfounded worry about having a serious illness despite reassurance from medical professionals.","s":"He hypochondriacally rushed to the emergency room after reading about a rare tropical disease online, convinced that his minor headache was a symptom of something life-threatening and catastrophic.","p":"HY-poh-kon-DRY-uh-klee","o":"Greek","y":9,"bp":30,"sy":"hypochon.dri.a.cal.ly","ps":"adverb","t":["body","disease","ogreek"]},{"w":"hypochylia","d":"A condition in which the stomach produces an abnormally reduced amount of chyle or gastric juice, leading to impaired digestion and reduced absorption of nutrients from food.","s":"The gastroenterologist suspected hypochylia after the patient reported feeling bloated and uncomfortable after nearly every meal, with food seeming to sit in his stomach for hours without being properly digested.","p":"HY-poh-KY-lee-uh","o":"Greek","y":9,"bp":26,"ps":"noun","t":["body","ogreek"]},{"w":"hypocist","d":"A small parasitic plant, related to the rockrose family, that lacks chlorophyll and lives entirely beneath or attached to the roots of its host plant, drawing all nutrients from it.","s":"The botanist was thrilled to discover a hypocist growing beneath a rockrose shrub in the Mediterranean hillside, its pale fleshy stalks emerging from the soil like tiny ghostly fingers.","p":"HY-poh-sist","o":"Greek","y":8,"bp":24,"ps":"noun","t":["botany","painting","kinship","ogreek"]},{"w":"hypocoristic","d":"Relating to or describing a pet name, nickname, or term of endearment, such as a shortened or affectionate version of a person's name used to express familiarity or fondness.","s":"Linguists study hypocoristic forms like 'Lizzie' for Elizabeth or 'Charlie' for Charles to understand how cultures use affectionate language to signal closeness and warmth between people.","p":"HY-poh-kuh-RIS-tik","o":"Greek","y":8,"bp":35,"sy":"hypocoris.tic","ps":"adjective","t":["emotions","ogreek"]},{"w":"hypocortisolism","d":"A medical condition in which the body produces abnormally low levels of cortisol, the primary stress hormone, leading to fatigue, low blood pressure, and an impaired ability to respond to physical stress.","s":"After months of unexplained exhaustion and dizziness every morning, the doctor finally diagnosed her with hypocortisolism, explaining that her adrenal glands were simply not releasing enough cortisol each day.","p":"HY-poh-KOR-tih-SOL-iz-um","o":"Greek","y":9,"bp":27,"sy":"hypocor.ti.solism","ps":"noun","t":["body","ogreek"]},{"w":"hypocritic","d":"Of, relating to, or characteristic of a hypocrite; displaying or involving hypocrisy, the practice of pretending to hold beliefs or virtues that one does not actually possess or follow.","s":"The committee found it deeply hypocritic that the official who had campaigned loudly against wasteful spending was quietly billing taxpayers for luxury hotel rooms and first-class flights.","p":"HIP-oh-KRIT-ik","o":"Greek","y":7,"bp":30,"sy":"hyp.o.crit.ic","ps":"adjective","t":["logic","ogreek"]},{"w":"hypocrystalline","d":"In geology, describing a rock texture in which only part of the material has crystallized into solid mineral crystals while the rest remains as amorphous volcanic glass, producing a mixed structure.","s":"The hypocrystalline basalt sample contained tiny glittering feldspar crystals suspended in a dark glassy matrix, showing that the lava had cooled quickly enough to freeze some material before it could fully crystallize.","p":"HY-poh-KRIS-tuh-lin","o":"Greek","y":9,"bp":25,"sy":"hypocrys.talline","ps":"adjective","t":["chemistry","minerals","ogreek"]},{"w":"hypodensity","d":"a darker area on a medical scan where tissue is thinner or less solid than normal","s":"The radiologist pointed out the hypodensity on the CT scan, indicating an area of low tissue density.","p":"HY-poh-DEN-sih-tee","o":"Greek","y":8,"bp":38,"sy":"hy.po.den.si.ty","ps":"noun","t":["body","disease","ogreek"]},{"w":"hypodermis","d":"layer of cells that secretes the chitinous cuticle in e.g. arthropods","s":"The hypodermis lies beneath the skin's surface and helps store fat and connect skin to muscle.","p":"HY-poh-DUR-miss","o":"Greek","y":7,"bp":30,"sy":"hy.po.der.mis","ps":"noun","t":["ogreek"]},{"w":"hypodicrotic","d":"Describing a pulse wave in which the secondary (dicrotic) notch or wave is abnormally weak or reduced, indicating diminished arterial elasticity or low blood pressure.","s":"The cardiologist observed a hypodicrotic pulse pattern on the monitor, indicating reduced arterial pressure.","p":"HY-poh-dy-KROT-ik","o":"Greek","y":8,"bp":38,"sy":"hy.podi.crot.ic","ps":"adjective","t":["body","ogreek"]},{"w":"hypodiploid","d":"Having fewer chromosomes than the normal diploid number for the species, a condition often associated with certain cancers or genetic abnormalities.","s":"The cancer cells were identified as hypodiploid, meaning they contained fewer chromosomes than normal.","p":"HY-poh-DIP-loyd","o":"Greek","y":9,"bp":34,"sy":"hy.podiploid","ps":"adjective","t":["disease","numbers","ogreek"]},{"w":"hypoendemic","d":"Describing a disease or infection that occurs at a consistently low, stable level within a population or region, with only minimal ongoing transmission.","s":"Malaria was described as hypoendemic in that mountain region because only a small percentage of the population was affected.","p":"HY-poh-en-DEM-ik","o":"Greek","y":8,"bp":37,"sy":"hy.poen.dem.ic","ps":"adjective","t":["disease","ogreek"]},{"w":"hypoferritinemia","d":"An abnormally low concentration of ferritin, the iron-storage protein, in the blood, often indicating depleted iron stores and a risk of iron-deficiency anemia.","s":"The doctor diagnosed her with hypoferritinemia after blood tests showed dangerously low iron-storage protein levels.","p":"HY-poh-fair-ih-tih-NEE-mee-uh","o":"Greek","y":9,"bp":30,"sy":"hy.po.fer.ritine.mia","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hypofibrinolysis","d":"A condition in which the breakdown of fibrin blood clots is abnormally reduced, leading to excessive clot persistence and an increased risk of thrombosis.","s":"Patients with hypofibrinolysis are at greater risk for blood clots because their bodies cannot break down fibrin properly.","p":"HY-poh-fy-brih-NOL-ih-sis","o":"Greek","y":9,"bp":32,"sy":"hy.pofib.ri.nol.y.sis","ps":"noun","t":["body","ogreek"]},{"w":"hypofibrinolytic","d":"Relating to or characterized by hypofibrinolysis, describing a state in which the body's clot-dissolving activity is abnormally low.","s":"The hypofibrinolytic condition meant the patient's clotting system was stuck in overdrive.","p":"HY-poh-fy-brih-noh-LIT-ik","o":"Greek","y":9,"bp":30,"sy":"hy.pofib.ri.nolyt.ic","ps":"adjective","t":["character","ogreek"]},{"w":"hypofluorite","d":"A chemical salt or ion containing fluorine in its lowest oxidation state combined with oxygen, analogous to hypochlorite but with fluorine instead of chlorine.","s":"The chemist synthesized a hypofluorite compound during the experiment on reactive oxygen-fluorine species.","p":"HY-poh-FLOOR-ite","o":"Greek","y":9,"bp":38,"sy":"hy.poflu.o.rite","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypofractionated","d":"Describing a radiation therapy schedule in which fewer, larger doses of radiation are given over a shorter period of time rather than many smaller daily doses.","s":"The radiation oncologist used a hypofractionated treatment plan, delivering larger doses over fewer sessions.","p":"HY-poh-FRAK-shun-ay-ted","o":"Greek","y":9,"bp":30,"sy":"hy.pofrac.tion.at.ed","ps":"adjective","t":["body","pharmacy","physics","time","ogreek"]},{"w":"hypogastric","d":"Relating to the hypogastrium, the lower middle region of the abdomen situated below the navel and between the two iliac regions.","s":"The surgeon made an incision in the hypogastric region, just below the navel.","p":"HY-poh-GAS-trik","o":"Greek","y":7,"bp":35,"sy":"hy.pogas.tric","ps":"adjective","t":["body","ogreek"]},{"w":"hypogeal","d":"Occurring or living below the surface of the ground; in botany, describing seed germination in which the cotyledons remain underground rather than rising above the soil.","s":"Peanuts are hypogeal plants because their seed leaves remain below the soil during germination.","p":"HY-poh-JEE-ul","o":"Greek","y":8,"bp":25,"sy":"hy.pogeal","ps":"adjective","t":["botany","ogreek"]},{"w":"hypogenesis","d":"Incomplete or deficient development of an organ, tissue, or organism, resulting in a smaller or less fully formed structure than normal.","s":"Hypogenesis of the limbs resulted in shorter-than-normal arm development in the embryo.","p":"HY-poh-JEN-ih-sis","o":"Greek","y":8,"bp":40,"sy":"hy.po.ge.n.e.sis","ps":"noun","t":["body","music","ogreek"]},{"w":"hypogenic","d":"Formed or originating from below, especially describing geological features or cave formations created by upward-moving groundwater or gases rather than surface processes.","s":"The cave formation was hypogenic, meaning it developed from water rising from below rather than trickling down from above.","p":"HY-poh-JEN-ik","o":"Greek","y":8,"bp":26,"sy":"hy.pogenic","ps":"adjective","t":["minerals","landforms","ogreek"]},{"w":"hypoglossal","d":"supplies intrinsic muscles of the tongue and other tongue muscles","s":"Damage to the hypoglossal nerve made it difficult for the patient to move his tongue normally.","p":"HY-poh-GLOS-ul","o":"Greek","y":7,"bp":35,"sy":"hy.poglos.sal","ps":"noun","t":["body","ogreek"]},{"w":"hypoglycorrhachia","d":"An abnormally low concentration of glucose in the cerebrospinal fluid, which can indicate meningitis, brain tumors, or other serious conditions affecting the central nervous system.","s":"The spinal fluid analysis revealed hypoglycorrhachia, indicating abnormally low glucose in the cerebrospinal fluid.","p":"HY-poh-gly-kor-AY-kee-uh","o":"Greek","y":9,"bp":32,"sy":"hy.po.gly.c.or.rhachia","ps":"noun","t":["body","disease","ogreek"]},{"w":"hypogonadism","d":"incompetence of the gonads (especially in the male with low testosterone); results in deficient development of secondary sex characteristics and (in prepubertal males) a body with long legs and a short trunk","s":"The teenager was diagnosed with hypogonadism, which explained his delayed puberty and low hormone levels.","p":"HY-poh-GOH-nad-iz-um","o":"Greek","y":6,"bp":38,"sy":"hy.pog.o.nadism","ps":"noun","t":["ogreek"]},{"w":"hypogonadotropic","d":"Describing a form of hypogonadism caused by insufficient production of gonadotropin hormones from the pituitary gland, resulting in reduced stimulation and function of the gonads.","s":"Her hypogonadotropic condition meant her pituitary gland was not sending enough signals to stimulate the ovaries.","p":"HY-poh-goh-nad-oh-TROH-pik","o":"Greek","y":8,"bp":30,"sy":"hy.pog.o.nadotrop.ic","ps":"adjective","t":["body","ogreek"]},{"w":"hypograph","d":"A word, phrase, or caption placed beneath an image, illustration, or main heading to provide additional explanation or context; a subtitle or subscript text element.","s":"The designer placed a hypograph beneath the main title to give the page a layered, dynamic look.","p":"HY-poh-graf","o":"Greek","y":8,"bp":28,"sy":"hy.po.graph","ps":"noun","t":["chemistry","numbers","wordwords","ogreek"]},{"w":"hypogravity","d":"A condition of gravitational force significantly lower than that experienced at Earth's surface, such as that found on the Moon or in certain spacecraft environments.","s":"Astronauts exercising in hypogravity conditions must work hard to prevent muscle loss.","p":"HY-poh-GRAV-ih-tee","o":"Greek","y":8,"bp":37,"sy":"hy.pograv.i.ty","ps":"noun","t":["astronomy","physics","ecology","ogreek"]},{"w":"hypohamiltonian","d":"Describing a graph that does not itself contain a Hamiltonian cycle but in which the removal of any single vertex produces a graph that does contain one.","s":"The mathematician proved the graph was hypohamiltonian because removing any single vertex made it Hamiltonian.","p":"HY-poh-ham-il-TOH-nee-un","o":"Greek","y":9,"bp":31,"sy":"hy.po.hamil.to.ni.an","ps":"adjective","t":["ogreek"]},{"w":"hypohidrosis","d":"A medical condition in which the sweat glands produce abnormally little sweat, impairing the body's ability to regulate temperature and potentially causing dangerous overheating.","s":"People with hypohidrosis cannot sweat enough, making them vulnerable to overheating in warm weather.","p":"HY-poh-hy-DROH-sis","o":"Greek","y":8,"bp":38,"sy":"hy.po.hidro.sis","ps":"noun","t":["body","ogreek"]},{"w":"hypohydration","d":"A state of reduced total body water content below normal levels, typically caused by inadequate fluid intake or excessive fluid loss, similar to mild dehydration.","s":"The athlete was warned that even mild hypohydration could significantly reduce her performance on the field.","p":"HY-poh-hy-DRAY-shun","o":"Greek","y":9,"bp":28,"sy":"hy.po.hy.dra.tion","ps":"noun","t":["ogreek"]},{"w":"hypoimmunogenic","d":"Describing a substance, cell, or organism that triggers a weaker-than-normal immune response, making it less likely to be recognized and attacked by the immune system.","s":"Scientists engineered a hypoimmunogenic cell line that would be less likely to trigger rejection in transplant patients.","p":"HY-poh-ih-myoo-noh-JEN-ik","o":"Greek","y":9,"bp":28,"sy":"hy.poim.muno.genic","ps":"adjective","t":["ogreek"]},{"w":"hypoinsulinaemia","d":"An abnormally low level of insulin circulating in the blood, which can impair glucose uptake and lead to elevated blood sugar; the British spelling of hypoinsulinemia.","s":"The British medical report documented hypoinsulinaemia in patients whose pancreas produced insufficient insulin.","p":"HY-poh-in-suh-lih-NEE-mee-uh","o":"Greek","y":9,"bp":27,"sy":"hy.poinsuli.naemia","ps":"noun","t":["body","chemistry","wordwords","ogreek"]},{"w":"hypoinsulinemia","d":"An abnormally low concentration of insulin in the bloodstream, reducing the body's ability to regulate blood glucose and often associated with type 1 diabetes or underproduction by the pancreas.","s":"Hypoinsulinemia was confirmed by lab tests showing the patient's insulin levels were far below the normal range.","p":"HY-poh-in-suh-lih-NEE-mee-uh","o":"Greek","y":9,"bp":28,"sy":"hy.poinsu.line.mia","ps":"noun","t":["body","disease","ogreek"]},{"w":"hypointense","d":"Appearing darker than the surrounding tissue or reference structure on a medical imaging scan, particularly MRI, indicating relatively lower signal strength in that region.","s":"The radiologist noted a hypointense area on the MRI scan, suggesting a region with less signal than surrounding tissue.","p":"HY-poh-in-TENSE","o":"Greek","y":9,"bp":34,"sy":"hy.pointense","ps":"adjective","t":["body","ogreek"]},{"w":"hypointensity","d":"A region on a medical scan, especially an MRI, that appears darker than the surrounding tissue due to producing a lower signal, often indicating abnormal tissue composition.","s":"The hypointensity visible on the brain scan could indicate a lesion or area of reduced blood flow.","p":"HY-poh-in-TEN-sih-tee","o":"Greek","y":9,"bp":26,"sy":"hy.pointen.si.ty","ps":"noun","t":["body","ogreek"]},{"w":"hypoiodite","d":"A chemical compound or ion in which iodine is bonded to oxygen in its lowest oxidation state, analogous to hypochlorite, and typically a powerful but unstable oxidizing agent.","s":"The chemist carefully handled the hypoiodite solution because of its strong oxidizing properties.","p":"HY-poh-EYE-oh-dite","o":"Greek","y":9,"bp":27,"sy":"hy.poiodite","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypokinesis","d":"Abnormally reduced or slow voluntary movement, often seen in neurological conditions such as Parkinson's disease, where the brain signals for motion are diminished.","s":"The neurologist observed hypokinesis in the patient, who moved much more slowly and stiffly than normal.","p":"HY-poh-kih-NEE-sis","o":"Greek","y":8,"bp":37,"sy":"hy.poki.ne.sis","ps":"noun","t":["body","disease","ogreek"]},{"w":"hypokinetic","d":"Relating to or characterized by abnormally reduced movement or motor activity, describing either a patient's physical state or a condition associated with low physical motion.","s":"Children with hypokinetic disorders often appear sluggish and have difficulty initiating physical activities.","p":"HY-poh-kih-NET-ik","o":"Greek","y":8,"bp":37,"sy":"hy.poki.net.ic","ps":"adjective","t":["character","tools","ogreek"]},{"w":"hypolimnion","d":"The cold, dense, oxygen-depleted bottom layer of a stratified lake that lies beneath the thermocline and remains largely isolated from the warmer surface water above.","s":"Scientists measured the dissolved oxygen in the hypolimnion and found it nearly depleted during summer.","p":"HY-poh-LIM-nee-on","o":"Greek","y":8,"bp":34,"sy":"hy.polimnion","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypolipemia","d":"An abnormally low concentration of lipids, such as fats and cholesterol, in the bloodstream, which can result from malnutrition, certain diseases, or lipid-lowering treatments.","s":"Although rare, hypolipemia can indicate underlying liver disease or malnutrition when fat levels drop too low.","p":"HY-poh-lih-PEE-mee-uh","o":"Greek","y":9,"bp":34,"sy":"hy.polipemia","ps":"noun","t":["body","disease","ogreek"]},{"w":"hypolipemic","d":"acting to lower the amount of fat and cholesterol in the blood","s":"The doctor prescribed a hypolipemic drug to bring the patient's high cholesterol down to a safer level.","p":"HY-poh-lih-PEE-mik","o":"Greek","y":8,"bp":34,"sy":"hy.polipemic","ps":"adjective","t":["body","pharmacy","ogreek"]},{"w":"hypolipidemia","d":"A condition characterized by abnormally low levels of lipids, including cholesterol and triglycerides, in the blood, sometimes caused by genetic factors, malabsorption, or disease.","s":"Her hypolipidemia puzzled doctors because most patients struggle with too much fat in the blood, not too little.","p":"HY-poh-lip-ih-DEE-mee-uh","o":"Greek","y":9,"bp":25,"sy":"hy.polipi.demia","ps":"noun","t":["body","disease","character","ogreek"]},{"w":"hypolophid","d":"A small or underdeveloped transverse ridge on the lower molar teeth of mammals, representing a reduced crest that is less prominent than the main tooth ridges.","s":"The paleontologist identified the fossil molar as hypolophid based on the incomplete ridge pattern on its surface.","p":"HY-poh-LOH-fid","o":"Greek","y":8,"bp":27,"sy":"hy.polophid","ps":"noun","t":["body","animals","ogreek"]},{"w":"hypomagnesemia","d":"An abnormally low level of magnesium in the blood, which can cause muscle cramps, irregular heartbeat, and nerve problems, often resulting from poor diet or impaired absorption.","s":"The patient's muscle cramps were caused by hypomagnesemia, a dangerously low level of magnesium in the blood.","p":"HY-poh-mag-neh-SEE-mee-uh","o":"Greek","y":9,"bp":29,"sy":"hy.po.mag.ne.semia","ps":"noun","t":["body","ogreek"]},{"w":"hypomagnesia","d":"A deficiency of magnesium in the body, referring to below-normal amounts of this essential mineral that is critical for muscle function, nerve signaling, and bone health.","s":"The nutritionist noted that hypomagnesia can result from a diet consistently lacking in leafy green vegetables.","p":"HY-poh-mag-NEE-zhuh","o":"Greek","y":9,"bp":39,"sy":"hy.po.mag.ne.sia","ps":"noun","t":["body","minerals","ogreek"]},{"w":"hypomania","d":"A mental state characterized by elevated mood, increased energy, and reduced need for sleep that is less severe than full mania and does not typically cause major impairment in daily functioning.","p":"HY-poh-MAY-nee-uh","o":"Greek","y":8,"bp":29,"sy":"hy.po.ma.nia","ps":"noun","t":["physics","character","emotions","time","ogreek"]},{"w":"hypomasculinity","d":"A state of reduced or below-normal masculine traits, behaviors, or characteristics, whether biological, psychological, or social in nature.","s":"The study explored how society's rigid standards can make men feel shame about perceived hypomasculinity.","p":"hy-poh-mas-kyoo-LIN-ih-tee","o":"Greek","y":9,"bp":31,"sy":"hy.po.mas.culin.i.ty","ps":"noun","t":["ogreek"]},{"w":"hypometabolism","d":"A condition in which the body's metabolic rate is abnormally low, meaning cells burn energy more slowly than normal.","s":"Bears exhibit hypometabolism during hibernation, dramatically slowing their body functions to conserve energy.","p":"hy-poh-meh-TAB-oh-liz-um","o":"Greek","y":9,"bp":24,"sy":"hy.pometabolism","ps":"noun","t":["physics","ogreek"]},{"w":"hypomethylating","d":"Describing a process or agent that reduces the addition of methyl groups to DNA, often used in cancer treatment to reactivate silenced genes.","s":"The oncologist prescribed a hypomethylating agent to reactivate silenced tumor-suppressor genes in the cancer cells.","p":"hy-poh-METH-ih-lay-ting","o":"Greek","y":9,"bp":28,"sy":"hy.pomethy.lat.ing","ps":"adjective","t":["disease","numbers","ogreek"]},{"w":"hypomobility","d":"An abnormally decreased range of motion or movement in a joint or body part, often causing stiffness and limited physical function.","s":"The doctor noted hypomobility in the patient's knee joint after months of wearing a cast.","p":"hy-poh-moh-BIL-ih-tee","o":"Greek","y":8,"bp":41,"sy":"hy.po.mo.bil.i.ty","ps":"noun","t":["ogreek"]},{"w":"hypomodification","d":"A condition in which a molecule, cell, or structure undergoes fewer chemical or structural changes than would normally be expected.","s":"The scientist observed hypomodification of the enzyme, meaning fewer chemical changes had occurred than expected.","p":"hy-poh-mod-ih-fih-KAY-shun","o":"Greek","y":9,"bp":33,"sy":"hy.po.mod.i.fi.ca.tion","ps":"noun","t":["chemistry","ogreek"]},{"w":"hyponasty","d":"A plant growth response in which the lower surface of a leaf or organ grows faster than the upper surface, causing the structure to curve upward.","s":"Hyponasty in the plant caused its leaves to curl upward when the temperature dropped at night.","p":"hy-poh-NAS-tee","o":"Greek","y":8,"bp":26,"sy":"hy.ponasty","ps":"noun","t":["botany","music","ogreek"]},{"w":"hyponitrite","d":"A chemical salt or ion containing less oxygen than a nitrite, formed from hyponitrous acid and used in certain chemical reactions.","s":"The chemist carefully handled the hyponitrite compound because of its unstable molecular structure.","p":"hy-poh-NY-tryt","o":"Greek","y":9,"bp":35,"sy":"hy.poni.trite","ps":"noun","t":["chemistry","ogreek"]},{"w":"hyponitrous","d":"a weak acid containing nitrogen in a low oxidation state","s":"Hyponitrous acid is a weak acid studied mainly in advanced chemistry laboratories.","p":"hy-poh-NY-trus","o":"Greek","y":9,"bp":35,"sy":"hy.poni.trous","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hyponutrition","d":"A state of receiving insufficient nutrients for normal body function, similar to undernutrition, leading to deficiencies and poor health outcomes.","s":"The relief workers were alarmed by the hyponutrition they observed in children at the refugee camp.","p":"hy-poh-noo-TRISH-un","o":"Greek","y":9,"bp":26,"sy":"hy.ponu.tri.tion","ps":"noun","t":["ogreek"]},{"w":"hypoosmolar","d":"Describing a solution that has a lower concentration of dissolved particles than a reference solution, such as blood plasma.","s":"The patient was given a hypoosmolar solution because her blood salt concentration was already too high.","p":"hy-poh-oz-MOH-lar","o":"Greek","y":8,"bp":37,"sy":"hy.poos.mo.lar","ps":"adjective","t":["body","physics","ogreek"]},{"w":"hypoosmolarity","d":"A condition in which a solution has an abnormally low osmolar concentration, meaning fewer dissolved particles per liter than normal bodily fluids.","s":"Hypoosmolarity of the plasma was detected after the patient drank excessive amounts of plain water.","p":"hy-poh-oz-moh-LAR-ih-tee","o":"Greek","y":9,"bp":30,"sy":"hy.poos.mo.lar.i.ty","ps":"noun","t":["physics","ogreek"]},{"w":"hypoperfused","d":"Describing a tissue or organ that has received an inadequate supply of blood flow, leading to reduced oxygen and nutrient delivery.","s":"The surgeon found that part of the heart muscle was hypoperfused due to the blocked artery.","p":"hy-poh-per-FYOOZD","o":"Greek","y":8,"bp":38,"sy":"hy.pop.er.fused","ps":"adjective","t":["body","chemistry","music","ogreek"]},{"w":"hypoperfusion","d":"A medical condition in which blood flow to a tissue or organ is insufficient to meet its metabolic needs, potentially leading to organ damage.","s":"Hypoperfusion of the brain during the accident may have contributed to the patient's confusion afterward.","p":"hy-poh-per-FYOO-zhun","o":"Greek","y":7,"bp":28,"sy":"hy.pop.er.fu.sion","ps":"noun","t":["body","music","ogreek"]},{"w":"hypoperfusional","d":"Relating to or characterized by hypoperfusion, meaning pertaining to a state of inadequate blood flow through tissues or organs.","s":"The team identified hypoperfusional damage in the tissue sample taken from the ischemic region.","p":"hy-poh-per-FYOO-zhun-ul","o":"Greek","y":9,"bp":31,"sy":"hy.pop.er.fu.sion.al","ps":"adjective","t":["body","character","ogreek"]},{"w":"hypopharynx","d":"The lowest part of the pharynx, or throat, located just above the esophagus and larynx, through which food passes on the way to the stomach.","s":"The scope revealed a small lesion in the hypopharynx, the lowest section of the patient's throat.","p":"hy-poh-FAIR-inks","o":"Greek","y":8,"bp":35,"sy":"hy.pophar.ynx","ps":"noun","t":["body","ogreek"]},{"w":"hypophosphate","d":"A salt or ester containing less oxygen than a standard phosphate group, representing a lower oxidation state of phosphorus.","s":"Hypophosphate levels in the soil explained why the crops were not growing properly that season.","p":"hy-poh-FOS-fayt","o":"Greek","y":9,"bp":25,"sy":"hy.pophos.phate","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypophosphatemia","d":"An abnormally low level of phosphate in the blood, which can weaken bones and muscles and impair nerve and cell function.","s":"The doctor diagnosed hypophosphatemia after noticing the patient's bone weakness and fatigue.","p":"hy-poh-fos-fuh-TEE-mee-uh","o":"Greek","y":9,"bp":27,"sy":"hy.pophos.phatemia","ps":"noun","t":["body","ogreek"]},{"w":"hypophosphite","d":"A salt or ion of hypophosphorous acid that contains phosphorus in a very low oxidation state, with less oxygen than phosphite compounds.","s":"Hypophosphite salts are used in some industrial plating processes to deposit metal onto surfaces.","p":"hy-poh-FOS-fyt","o":"Greek","y":9,"bp":25,"sy":"hy.pophos.phite","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypophosphorylated","d":"Describing a molecule, especially a protein, that has fewer phosphate groups attached to it than would normally be present or expected.","s":"The researchers found that the protein was hypophosphorylated, meaning it had fewer phosphate groups attached than expected.","p":"hy-poh-fos-FOR-ih-lay-tid","o":"Greek","y":9,"bp":32,"sy":"hy.pophos.pho.ry.lat.ed","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hypophosphorylation","d":"The process or state of having an abnormally low level of phosphorylation, meaning fewer phosphate groups are added to molecules than normal.","s":"Hypophosphorylation of the retinoblastoma protein allows it to slow down cell division.","p":"hy-poh-fos-for-ih-LAY-shun","o":"Greek","y":9,"bp":32,"sy":"hy.pophos.pho.ry.la.tion","ps":"noun","t":["chemistry","ogreek"]},{"w":"hypoplasia","d":"underdevelopment of an organ because of a decrease in the number of cells","s":"The dentist explained that the child's weak enamel was caused by hypoplasia during tooth development.","p":"hy-poh-PLAY-zhuh","o":"Greek","y":8,"bp":29,"sy":"hy.popla.sia","ps":"noun","t":["music","numbers","ogreek"]},{"w":"hypoplastron","d":"The lower or ventral plate of a turtle's plastron, one of the paired bony plates that form the underside of the shell.","s":"The biologist labeled the hypoplastron, one of the lower shell plates found in the turtle specimen.","p":"hy-poh-PLAS-tron","o":"Greek","y":8,"bp":36,"sy":"hy.poplas.tron","ps":"noun","t":["ogreek"]},{"w":"hypoploid","d":"Describing a cell or organism that has fewer chromosomes than the normal diploid number, resulting in a chromosome set that is incomplete.","s":"The cell was identified as hypoploid because it contained fewer chromosomes than the normal diploid number.","p":"hy-poh-PLOYD","o":"Greek","y":9,"bp":26,"sy":"hy.poploid","ps":"adjective","t":["numbers","ogreek"]},{"w":"hypoproteinemia","d":"abnormally low level of protein in the blood; can indicate inadequate diet or intestinal or renal disorders","s":"Hypoproteinemia in the malnourished child caused fluid to accumulate in the abdomen.","p":"hy-poh-proh-tee-NEE-mee-uh","o":"Greek","y":9,"bp":28,"sy":"hy.popro.teine.mia","ps":"noun","t":["body","disease","ogreek"]},{"w":"hyporelief","d":"A sculptural or artistic technique in which figures or designs are carved or modeled so that they are slightly recessed below the surrounding surface.","s":"The ancient carving used hyporelief, where the design was cut below the flat surface of the stone.","p":"hy-poh-rih-LEEF","o":"Greek","y":8,"bp":29,"sy":"hy.pore.lief","ps":"noun","t":["painting","ogreek"]},{"w":"hyporesponsive","d":"Showing a weaker or lower-than-normal reaction to a stimulus, treatment, or signal, whether in biological, immunological, or behavioral contexts.","s":"The immune cells were hyporesponsive to the vaccine, failing to produce enough antibodies.","p":"hy-poh-rih-SPON-siv","o":"Greek","y":9,"bp":27,"sy":"hy.pore.spon.sive","ps":"adjective","t":["ogreek"]},{"w":"hyporesponsiveness","d":"The quality or state of reacting less strongly than expected to a given stimulus or treatment, indicating a diminished response in a system or organism.","s":"The drug trial noted hyporesponsiveness in elderly patients who received the standard dose.","p":"hy-poh-rih-SPON-siv-nes","o":"Greek","y":9,"bp":30,"sy":"hy.pore.spon.sive.ness","ps":"noun","t":["ogreek"]},{"w":"hyposalivation","d":"An abnormally reduced production of saliva, causing a persistently dry mouth that can interfere with eating, speaking, and oral health.","s":"Hyposalivation made it difficult for the patient to swallow food comfortably after radiation therapy.","p":"hy-poh-sal-ih-VAY-shun","o":"Greek","y":9,"bp":29,"sy":"hy.pos.ali.va.tion","ps":"noun","t":["ogreek"]},{"w":"hyposecretion","d":"The production or release of an abnormally small amount of a substance by a gland or organ, such as insufficient hormone output.","s":"Hyposecretion of insulin by the pancreas can lead to high blood sugar levels.","p":"hy-poh-sih-KREE-shun","o":"Greek","y":9,"bp":26,"sy":"hy.pose.cre.tion","ps":"noun","t":["body","music","ogreek"]},{"w":"hyposkeletal","d":"Relating to or characterized by an underdeveloped or deficient skeletal structure, with fewer or less dense bones than normal.","s":"The fossil showed hyposkeletal features, with underdeveloped bone structures compared to related species.","p":"hy-poh-SKEL-ih-tul","o":"Greek","y":8,"bp":36,"sy":"hy.poskele.tal","ps":"adjective","t":["body","character","ogreek"]},{"w":"hyposmolality","d":"A condition in which the osmolality of a body fluid, especially blood, is lower than normal, indicating a reduced concentration of dissolved particles per kilogram of water.","s":"The nurse measured hyposmolality in the patient's blood after he had consumed too much water.","p":"hy-poh-smoh-LAL-ih-tee","o":"Greek","y":9,"bp":29,"sy":"hy.pos.mo.lal.i.ty","ps":"noun","t":["body","physics","ogreek"]},{"w":"hyposphagma","d":"A hemorrhage occurring beneath the conjunctiva of the eye, causing a visible red patch on the white of the eye due to a burst blood vessel.","s":"The ophthalmologist noted a hyposphagma, a small pool of blood visible beneath the white of the eye.","p":"hy-poh-SFAG-muh","o":"Greek","y":9,"bp":35,"sy":"hy.posphag.ma","ps":"noun","t":["body","seafaring","ogreek"]},{"w":"hyposternum","d":"A bony or cartilaginous structure located below or posterior to the sternum, found in certain animals as part of the ventral skeletal system.","s":"The entomologist examined the hyposternum of the beetle to help identify the species.","p":"hy-poh-STER-num","o":"Greek","y":8,"bp":35,"sy":"hy.poster.num","ps":"noun","t":["animals","ogreek"]},{"w":"hypostome","d":"A mouth-bearing structure located on the underside of certain invertebrates, such as ticks or hydra, used for feeding or attachment.","s":"The biologist examined the hypostome of the hydra, the cone-shaped structure surrounding its mouth.","p":"hy-poh-STOHM","o":"Greek","y":8,"bp":28,"sy":"hy.pos.tome","ps":"noun","t":["maps","ogreek"]},{"w":"hypostyle","d":"Describing a large hall or space whose roof is supported by many rows of columns, as seen in ancient Egyptian temples.","s":"The ancient Egyptian hypostyle hall was filled with rows of massive carved columns supporting the roof.","p":"hy-poh-STYL","o":"Greek","y":9,"bp":26,"sy":"hy.postyle","ps":"adjective","t":["buildings","religion","ancient","ogreek"]},{"w":"hyposulfuric","d":"Relating to an acid or compound in which sulfur is in a lower oxidation state than in sulfuric acid, indicating reduced sulfur content or bonding.","s":"The chemistry textbook described hyposulfuric acid as having a lower oxidation state than sulfuric acid.","p":"hy-poh-sul-FYOOR-ik","o":"Greek","y":8,"bp":39,"sy":"hy.po.sul.fu.ric","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hyposulfurous","d":"Relating to a compound or acid containing sulfur in an oxidation state lower than sulfurous, representing a minimal degree of sulfur oxidation.","s":"Hyposulfurous acid is sometimes used as a reducing agent in industrial chemical processes.","p":"hy-poh-SUL-fyur-us","o":"Greek","y":9,"bp":26,"sy":"hy.po.sul.furous","ps":"adjective","t":["chemistry","ogreek"]},{"w":"hypotarsus","d":"A bony projection on the back of the ankle bone (tarsometatarsus) in birds, serving as a pulley-like guide for tendons of the toes.","s":"The ornithologist pointed out the hypotarsus on the bird's ankle bone as a key identification feature.","p":"hy-poh-TAR-sus","o":"Greek","y":8,"bp":29,"sy":"hy.potar.sus","ps":"noun","t":["body","birds","tools","ogreek"]},{"w":"hypotaurine","d":"A sulfur-containing amino acid found in animal tissues that serves as a precursor to taurine and acts as an antioxidant in cells.","s":"Researchers found that hypotaurine acts as an antioxidant in certain cells of the nervous system.","p":"hy-poh-TAW-reen","o":"Greek","y":9,"bp":35,"sy":"hy.potau.rine","ps":"noun","t":["body","animals","chemistry","ogreek"]},{"w":"hypotheca","d":"The lower or inner half of the shell (theca) of a diatom or dinoflagellate, fitting inside the upper half like the bottom of a pillbox.","s":"Under the microscope, the student could see the hypotheca forming the lower half of the diatom's shell.","p":"hy-poh-THEE-kuh","o":"Greek","y":9,"bp":28,"sy":"hy.pothe.ca","ps":"noun","t":["ogreek"]},{"w":"hypothecal","d":"Of or relating to the hypotheca, the lower portion of the shell of a diatom or dinoflagellate.","s":"The scientist examined the hypothecal structure under a powerful microscope to understand the organism's protective casing.","p":"hy-poh-THEE-kul","o":"Greek","y":8,"bp":29,"sy":"hy.pothe.cal","ps":"adjective","t":["ogreek"]},{"w":"hypotriploid","d":"Describing a cell or organism whose chromosome number is slightly less than three times the basic haploid number.","s":"The lab report noted that the hypotriploid cells had fewer chromosomes than a standard triploid set.","p":"hy-poh-TRIP-loyd","o":"Greek","y":9,"bp":35,"sy":"hy.potriploid","ps":"adjective","t":["numbers","time","ogreek"]},{"w":"hypotrochoid","d":"A curve traced by a point on or inside a circle that rolls around the inside of a larger fixed circle.","s":"The spirograph toy drew a beautiful hypotrochoid curve as the small gear rolled inside the larger ring.","p":"hy-poh-TROH-koyd","o":"Greek","y":9,"bp":36,"sy":"hy.potro.choid","ps":"noun","t":["numbers","ogreek"]},{"w":"hypotrophy","d":"A condition of underdevelopment or wasting of a body tissue or organ due to insufficient nourishment or stimulation.","s":"The doctor diagnosed hypotrophy in the patient's muscles after months of inactivity.","p":"hy-POT-roh-fee","o":"Greek","y":8,"bp":29,"sy":"hy.potro.phy","ps":"noun","t":["body","music","ogreek"]},{"w":"hypotropia","d":"A form of strabismus in which one eye is deviated downward relative to the other eye.","s":"The optometrist detected hypotropia when one of the child's eyes consistently drifted downward.","p":"hy-poh-TROH-pee-uh","o":"Greek","y":9,"bp":27,"sy":"hy.potropia","ps":"noun","t":["ogreek"]},{"w":"hypouricemia","d":"An abnormally low level of uric acid in the blood, which may indicate a metabolic or kidney disorder.","s":"The physician noted hypouricemia on the blood test, meaning the patient had unusually low uric acid levels.","p":"hy-poh-yoor-ih-SEE-mee-uh","o":"Greek","y":9,"bp":35,"sy":"hy.pouricemia","ps":"noun","t":["body","disease","chemistry","ogreek"]},{"w":"hypoventilation","d":"Abnormally slow or shallow breathing that causes carbon dioxide to accumulate in the blood and reduces oxygen levels.","s":"The patient's hypoventilation meant he wasn't breathing deeply enough, causing carbon dioxide to build up in his blood.","p":"hy-poh-ven-tih-LAY-shun","o":"Greek","y":7,"bp":30,"sy":"hy.poven.ti.la.tion","ps":"noun","t":["body","chemistry","ogreek"]},{"w":"hypovirulence","d":"A reduced ability of a pathogen to cause disease or harm its host, often used in biological control strategies.","s":"Researchers studied the hypovirulence of the weakened pathogen, hoping it could protect crops without causing serious disease.","p":"hy-poh-VIR-yoo-lense","o":"Greek","y":9,"bp":26,"sy":"hy.povir.u.lence","ps":"noun","t":["disease","ogreek"]},{"w":"hypovirulent","d":"Describing a pathogen or microorganism that has a significantly reduced capacity to cause disease compared to normal strains.","s":"The hypovirulent strain of fungus was used in biological control because it couldn't cause severe infections.","p":"hy-poh-VIR-yoo-lunt","o":"Greek","y":8,"bp":38,"sy":"hy.povir.u.lent","ps":"adjective","t":["disease","ogreek"]},{"w":"hypovolemic","d":"of or relating to a decrease in the volume of circulating blood","s":"After losing so much blood in the accident, the patient was in hypovolemic shock and needed immediate transfusions.","p":"hy-poh-voh-LEE-mik","o":"Greek","y":7,"bp":37,"sy":"hy.po.v.olemic","ps":"adjective","t":["body","ogreek"]},{"w":"hypoxanthin","d":"A naturally occurring purine base found in muscle tissue and body fluids, formed by the breakdown of adenine and converted to xanthine during metabolism.","s":"The biochemist measured hypoxanthin levels in the tissue sample to assess cell breakdown.","p":"hy-pok-ZAN-thin","o":"Greek","y":8,"bp":37,"sy":"hy.pox.an.thin","ps":"noun","t":["body","ogreek"]},{"w":"hypozoic","d":"Describing a geological period or zone that existed before the appearance of animal life, or living beneath the zone where most organisms exist.","s":"The hypozoic layer of the rock formation contained very few traces of ancient life.","p":"hy-poh-ZOH-ik","o":"Greek","y":9,"bp":27,"sy":"hy.po.zoic","ps":"adjective","t":["animals","minerals","ogreek"]},{"w":"hypsochromic","d":"Describing a shift in the absorption spectrum of a substance toward shorter wavelengths (the blue or violet end), often caused by a change in solvent or molecular structure.","s":"Adding the chemical caused a hypsochromic shift, moving the light absorption toward shorter, bluer wavelengths.","p":"hip-soh-KROH-mik","o":"Greek","y":9,"bp":35,"sy":"hyp.sochromic","ps":"adjective","t":["flowers","chemistry","physics","ogreek"]},{"w":"hypsometer","d":"an altimeter that uses the boiling point of water to determine land elevation","s":"The geographer used a hypsometer to determine the mountain campsite's elevation by checking the water's boiling point.","p":"hip-SOM-ih-ter","o":"Greek","y":8,"bp":29,"sy":"hyp.some.ter","ps":"noun","t":["culinary","ogreek"]},{"w":"hypsometry","d":"measurement of the elevation of land above sea level","s":"Using hypsometry, the team mapped every ridge and valley's elevation before planning the hiking trail.","p":"hip-SOM-ih-tree","o":"Greek","y":8,"bp":30,"sy":"hyp.som.e.try","ps":"noun","t":["waterways","numbers","ogreek"]},{"w":"hysteroepilepsy","d":"A historical term for a condition combining features of hysteria and epilepsy, marked by seizure-like convulsions believed to be psychogenic in origin.","s":"Nineteenth-century physicians debated whether hysteroepilepsy was a distinct condition or a combination of two disorders.","p":"his-teh-roh-EP-ih-lep-see","o":"Greek","y":9,"bp":27,"sy":"hys.teroepilep.sy","ps":"noun","t":["ogreek"]},{"w":"hysterogenic","d":"Capable of producing or inducing hysterical symptoms, convulsions, or spasms when a specific area of the body is stimulated.","s":"The researcher identified certain hysterogenic zones on the body that, when pressed, could trigger symptoms in some patients.","p":"his-teh-roh-JEN-ik","o":"Greek","y":8,"bp":36,"sy":"hys.tero.genic","ps":"adjective","t":["disease","ogreek"]},{"w":"hysteroid","d":"Resembling or characteristic of hysteria; exhibiting symptoms or behaviors that look like those of a hysterical disorder but may have a different cause.","s":"The patient's hysteroid episode mimicked a seizure but had no measurable neurological cause.","p":"HIS-teh-royd","o":"Greek","y":9,"bp":26,"sy":"hys.teroid","ps":"adjective","t":["disease","ogreek"]},{"w":"hysterokinetic","d":"Relating to or characterized by the involuntary muscular movements or convulsions associated with hysteria or hysterical disorders.","s":"The therapist studied the hysterokinetic movements in the patient's limbs, which occurred without conscious control.","p":"his-teh-roh-kih-NET-ik","o":"Greek","y":9,"bp":27,"sy":"hys.teroki.net.ic","ps":"adjective","t":["disease","character","ogreek"]},{"w":"hysterotomy","d":"surgical incision into the uterus (as in cesarean section)","s":"The surgeon performed a hysterotomy to deliver the baby safely when a standard birth was not possible.","p":"his-teh-ROT-oh-mee","o":"Greek","y":8,"bp":37,"sy":"hys.tero.to.my","ps":"noun","t":["body","ogreek"]},{"w":"hydantoic","d":"Of, relating to, or derived from hydantoin, a chemical compound used in the synthesis of certain drugs and organic molecules.","s":"The chemistry student carefully studied the hydantoic acid reaction, noting how the five-membered ring structure changed when exposed to different temperatures in the lab.","p":"hy-dan-TOH-ik","o":"French","y":9,"bp":29,"sy":"hy.dan.to.ic","ps":"adjective","t":["pharmacy","chemistry","ofrench"]},{"w":"hydrail","d":"A rail vehicle or transit system powered by hydrogen fuel cells rather than conventional diesel or electric power from the grid.","s":"The city unveiled its new hydrail line at the transportation expo, boasting that the hydrogen-powered trains would produce nothing but water vapor as exhaust.","p":"HY-drayl","o":"French","y":8,"bp":17,"ps":"noun","t":["chemistry","physics","vehicles","ofrench"]},{"w":"hydratase","d":"An enzyme that catalyzes the addition of water to a molecule or the removal of water from a molecule in a biochemical reaction.","s":"Scientists studying cell metabolism discovered that a specific hydratase enzyme was responsible for adding water molecules to fatty acid chains during the energy-conversion process.","p":"HY-druh-tays","o":"French","y":8,"bp":26,"sy":"hy.dratase","ps":"noun","t":["chemistry","numbers","ofrench"]},{"w":"hydrocarbonate","d":"A chemical compound containing hydrogen, carbon, and carbonate groups; a salt or ester related to carbonic acid that also contains hydrocarbon elements.","s":"The geology lab analyzed the rock sample and found traces of hydrocarbonate compounds that suggested the formation had once been submerged beneath an ancient shallow sea.","p":"hy-droh-KAR-buh-nayt","o":"French","y":9,"bp":29,"sy":"hy.dro.car.bon.ate","ps":"noun","t":["chemistry","ofrench"]},{"w":"hydrocode","d":"A computer simulation code or software used to model the behavior of fluids, especially under high-pressure or high-velocity conditions such as shock waves.","s":"The aerospace engineers ran the hydrocode simulation overnight to predict exactly how the experimental fuel would behave inside the rocket chamber at supersonic speeds.","p":"HY-droh-kohd","o":"French","y":9,"bp":26,"sy":"hy.drocode","ps":"noun","t":["physics","waterways","ofrench"]},{"w":"hydrogalvanic","d":"Relating to the production of electric current through the interaction of water and dissimilar metals or electrochemical reactions involving water.","s":"The scientist demonstrated the hydrogalvanic effect by submerging two different metal rods in saltwater and showing how a small measurable electric current immediately began to flow between them.","p":"hy-droh-gal-VAN-ik","o":"French","y":9,"bp":40,"sy":"hy.dro.gal.van.ic","ps":"adjective","t":["physics","ofrench"]},{"w":"hydrogenide","d":"A chemical compound in which hydrogen is bonded to another element, particularly a metal, forming a binary compound analogous to other ionic compounds ending in -ide.","s":"The chemistry textbook explained that a hydrogenide forms when hydrogen bonds directly with a metal such as sodium, resulting in a compound with very different properties than the original elements.","p":"hy-DROJ-uh-nyd","o":"French","y":9,"bp":35,"sy":"hy.dro.genide","ps":"noun","t":["chemistry","ofrench"]},{"w":"hydrogenise","d":"To combine or treat a substance with hydrogen, especially to add hydrogen to an unsaturated organic compound; British spelling of hydrogenize.","s":"The food scientist explained that manufacturers hydrogenise vegetable oils to make them solid at room temperature, which is how margarine and certain shortenings are produced in British factories.","p":"hy-DROJ-uh-nyz","o":"French","y":9,"bp":35,"sy":"hy.dro.genise","ps":"verb","t":["chemistry","wordwords","ofrench"]},{"w":"hydrogenize","d":"To combine or treat a substance with hydrogen, especially to add hydrogen atoms to an unsaturated organic compound; American spelling of hydrogenise.","s":"In the industrial chemistry class, students learned how companies hydrogenize liquid plant oils under high pressure and temperature to produce solid fats used in processed food products.","p":"hy-DROJ-uh-nyz","o":"French","y":9,"bp":38,"sy":"hy.dro.g.e.nize","ps":"verb","t":["chemistry","wordwords","ofrench"]},{"w":"hydrogenless","d":"Lacking or containing no hydrogen; describing a substance or compound from which hydrogen is entirely absent.","s":"The theoretical chemist proposed a hydrogenless compound as a thought experiment, challenging students to figure out whether such a molecule could ever be stable under normal conditions.","p":"hy-DROJ-en-les","o":"French","y":9,"bp":38,"sy":"hy.dro.gen.less","ps":"adjective","t":["chemistry","ofrench"]},{"w":"hydrolipidic","d":"Relating to or involving both water and lipids (fats); often used to describe the balance of water and fat in skin or biological membranes.","s":"The dermatologist recommended a moisturizer that would restore the hydrolipidic balance of the patient's skin, replacing both the oils and the moisture that harsh winter air had stripped away.","p":"hy-droh-lih-PID-ik","o":"French","y":8,"bp":36,"sy":"hy.droli.pidic","ps":"adjective","t":["body","ofrench"]},{"w":"hydrologic","d":"Of or relating to hydrology, the scientific study of water's properties, distribution, and movement across the Earth's surface and through the atmosphere.","s":"The environmental team created a detailed hydrologic map showing every stream, aquifer, and wetland in the region so planners could better protect the local water supply.","p":"hy-droh-LOJ-ik","o":"French","y":5,"bp":30,"sy":"hy.dro.log.ic","ps":"adjective","t":["ofrench"]},{"w":"hydrological","d":"Of or relating to hydrology; pertaining to the scientific study of the occurrence, distribution, and circulation of water on Earth.","s":"The hydrological survey revealed that three separate underground springs were feeding the river, which explained why the water level stayed high even during long dry spells.","p":"hy-droh-LOJ-ih-kul","o":"French","y":5,"bp":39,"sy":"hy.dro.log.i.cal","ps":"adjective","t":["ofrench"]},{"w":"hydrometric","d":"of or relating to hydrometry","s":"The hydrometric gauges installed along the riverbank transmitted real-time water-level data to the flood-warning center, allowing emergency officials to alert communities before dangerous surges arrived downstream.","p":"hy-droh-MET-rik","o":"French","y":7,"bp":37,"sy":"hy.dro.met.ric","ps":"adjective","t":["ofrench"]},{"w":"hydrophobicity","d":"the property of being water-repellent; tending to repel and not absorb water","s":"The researcher tested the hydrophobicity of the new coating by dripping water onto the surface and watching the droplets bead up and roll off without leaving a trace of moisture behind.","p":"hy-droh-foh-BIS-ih-tee","o":"French","y":7,"bp":29,"sy":"hy.dropho.bic.i.ty","ps":"noun","t":["character","ofrench"]},{"w":"hyen","d":"An archaic or dialectal form of hyena; a fierce, scavenging mammal known for its distinctive call and powerful jaws.","s":"The old explorer's journal referred to the spotted hyen that circled the camp each night, its eerie laughing cry echoing across the dark African savanna.","p":"HY-en","o":"French","y":7,"bp":9,"ps":"noun","t":["animals","wordwords","ofrench"]},{"w":"hygienically","d":"in a hygienic manner","s":"The kitchen staff was trained to prepare all food hygienically, washing their hands thoroughly, sanitizing every surface, and storing ingredients at proper temperatures to prevent any contamination.","p":"hy-JEE-nih-klee","o":"French","y":8,"bp":39,"sy":"hy.gien.i.cal.ly","ps":"adverb","t":["ofrench"]},{"w":"hygienism","d":"A doctrine or belief system that promotes cleanliness, sanitation, and healthy living practices as fundamental to personal and public health.","s":"In the nineteenth century, hygienism became a powerful social movement, with reformers insisting that clean water, proper sewage systems, and personal cleanliness could eliminate many deadly diseases from crowded cities.","p":"HY-jeen-iz-um","o":"French","y":8,"bp":28,"sy":"hy.gien.ism","ps":"noun","t":["logic","ofrench"]},{"w":"hygrographic","d":"Of or relating to hygrography, the branch of science that deals with recording and mapping atmospheric humidity or moisture levels.","s":"The meteorology student analyzed the hygrographic data collected over six months, plotting the moisture readings on a chart to identify patterns that predicted afternoon thunderstorms in the valley.","p":"hy-groh-GRAF-ik","o":"French","y":8,"bp":38,"sy":"hy.gro.graph.ic","ps":"adjective","t":["weather","ofrench"]},{"w":"hygrometric","d":"Of or relating to hygrometry, the measurement of the humidity or moisture content of the atmosphere or of a gas.","s":"The museum conservator relied on hygrometric readings taken throughout the gallery to ensure the humidity never rose high enough to damage the ancient paintings on display.","p":"hy-groh-MET-rik","o":"French","y":8,"bp":37,"sy":"hy.gro.met.ric","ps":"adjective","t":["weather","numbers","ofrench"]},{"w":"hygroscopicity","d":"The property or degree to which a substance is able to attract and absorb moisture from the surrounding air.","s":"The pharmacist warned that the powder's high hygroscopicity meant it had to be sealed in airtight containers immediately, because even a few minutes of exposure to humid air would ruin it.","p":"hy-groh-skoh-PIS-ih-tee","o":"French","y":9,"bp":30,"sy":"hy.gro.scop.ic.i.ty","ps":"noun","t":["ofrench"]},{"w":"hyoplastron","d":"One of the paired bony plates forming part of the shell of a turtle, located in the front section of the plastron (the belly shell).","s":"The paleontologist carefully brushed away the surrounding rock to expose the hyoplastron of the fossilized turtle, which provided important clues about the ancient reptile's size and species.","p":"hy-oh-PLAS-tron","o":"French","y":8,"bp":35,"sy":"hy.oplas.tron","ps":"noun","t":["ofrench"]},{"w":"hyperacidity","d":"excessive acidity","s":"The doctor explained that the patient's hyperacidity was causing painful heartburn after every meal and recommended a combination of dietary changes and medication to reduce the excess stomach acid.","p":"hy-per-uh-SID-ih-tee","o":"French","y":8,"bp":39,"sy":"hy.per.acid.i.ty","ps":"noun","t":["ofrench"]},{"w":"hyperalert","d":"In a state of extreme or heightened alertness, far beyond the normal level; acutely aware of one's surroundings, often due to stress or danger.","s":"After hearing a strange noise outside the tent, the campers lay hyperalert in their sleeping bags for hours, listening to every snap of a twig and rustle of leaves in the darkness.","p":"hy-per-uh-LERT","o":"French","y":8,"bp":29,"sy":"hy.per.alert","ps":"adjective","t":["ofrench"]},{"w":"hyperalgesic","d":"Relating to or causing hyperalgesia, a condition of abnormally increased sensitivity to pain, where stimuli that normally cause mild discomfort produce intense pain responses.","s":"The neurologist explained that the hyperalgesic response observed in the patient meant that even a light touch on the affected area felt as painful as a sharp burn to their nervous system.","p":"hy-per-al-JEE-zik","o":"French","y":8,"bp":38,"sy":"hy.per.al.gesic","ps":"adjective","t":["ofrench"]},{"w":"hyperbolically","d":"in an exaggerated manner","s":"The sports announcer hyperbolically declared that the young athlete's home run was the greatest single moment in the entire history of the sport, leaving the crowd both amused and thrilled by the exaggeration.","p":"hy-per-BOL-ih-klee","o":"French","y":8,"bp":30,"sy":"hy.per.bol.i.cal.ly","ps":"adverb","t":["ofrench"]},{"w":"hyperbolicity","d":"The quality or state of being hyperbolic; the tendency to use exaggeration or overstatement, or in mathematics, the property of having the form of a hyperbola.","s":"The debate coach cautioned her team against the hyperbolicity of their arguments, reminding them that wild exaggerations would undermine their credibility far more than they would strengthen their case.","p":"hy-per-boh-LIS-ih-tee","o":"French","y":9,"bp":41,"sy":"hy.per.bol.ic.i.ty","ps":"noun","t":["numbers","ofrench"]},{"w":"hypercapitalism","d":"An extreme or intensified form of capitalism characterized by unchecked market forces, maximum privatization, and the prioritization of profit above nearly all other social values.","s":"The political science professor argued that hypercapitalism had widened the wealth gap so dramatically that a small number of corporations now controlled resources that entire nations once managed together.","p":"hy-per-KAP-ih-tul-iz-um","o":"French","y":9,"bp":31,"sy":"hy.per.cap.i.tal.ism","ps":"noun","t":["physics","economy","character","ofrench"]},{"w":"hypercerebral","d":"Excessively intellectual or overly focused on abstract thought; describing a person or work that emphasizes complex mental activity to an extreme degree.","s":"The novel was so hypercerebral that many readers gave up halfway through, exhausted by the dense philosophical arguments woven into every chapter and the complete absence of action or emotion.","p":"hy-per-SER-uh-brul","o":"French","y":9,"bp":38,"sy":"hy.per.cere.bral","ps":"adjective","t":["ofrench"]},{"w":"hypercomplex","d":"Extremely or extraordinarily complex; in mathematics, relating to a number system that extends beyond complex numbers, such as quaternions or octonions.","s":"The engineer warned that the hypercomplex wiring diagram would require weeks of careful study before any technician could safely attempt repairs on the experimental aircraft's control system.","p":"hy-per-KOM-pleks","o":"French","y":8,"bp":38,"sy":"hy.per.com.plex","ps":"adjective","t":["numbers","ofrench"]},{"w":"hypercompute","d":"To perform computations that exceed the theoretical limits of standard Turing-machine computation, using hypothetical or advanced models of computing that go beyond conventional algorithms.","s":"Theoretical computer scientists debate whether it will ever be physically possible to hypercompute, since doing so would require processing power that seems to break the known laws of physics.","p":"hy-per-kum-PYOOT","o":"French","y":9,"bp":38,"sy":"hy.per.com.pute","ps":"verb","t":["tools","ofrench"]},{"w":"hyperdynamic","d":"Characterized by excessive or abnormally increased force, energy, or activity, especially in reference to the heart or circulatory system pumping with greater than normal intensity.","s":"The cardiologist noted a hyperdynamic heartbeat in the young athlete during the stress test, meaning the heart was pumping with unusually high force and speed even at rest.","p":"hy-per-dy-NAM-ik","o":"French","y":9,"bp":39,"sy":"hy.per.dy.nam.ic","ps":"adjective","t":["body","physics","character","ofrench"]},{"w":"hyperellipse","d":"A geometric curve that generalizes the ellipse by using a higher exponent in its equation, producing a shape that appears more rectangular with rounded corners than a standard ellipse.","s":"The graphic designer used a hyperellipse as the outline for the product logo, achieving a shape that looked softer than a rectangle but more structured and bold than a simple oval.","p":"hy-per-EL-ips","o":"French","y":9,"bp":38,"sy":"hy.per.el.lipse","ps":"noun","t":["numbers","ofrench"]},{"w":"hyperepidemic","d":"An epidemic that spreads with extraordinary speed and scale, far exceeding the normal parameters of a typical epidemic in its reach and impact on a population.","s":"Health officials declared the outbreak a hyperepidemic event after the virus spread across forty countries within two weeks, overwhelming hospitals and prompting emergency international cooperation on a massive scale.","p":"hy-per-ep-ih-DEM-ik","o":"French","y":9,"bp":40,"sy":"hy.per.epi.dem.ic","ps":"adjective","t":["disease","ofrench"]},{"w":"hyperglycemic","d":"Relating to or characterized by hyperglycemia, a condition in which there is an abnormally high concentration of glucose in the bloodstream, often associated with diabetes.","s":"The nurse noticed the patient was showing hyperglycemic symptoms—extreme thirst, blurred vision, and unusual fatigue—and immediately checked the blood sugar level before contacting the doctor on duty.","p":"hy-per-gly-SEE-mik","o":"French","y":8,"bp":37,"sy":"hy.per.glycemic","ps":"adjective","t":["body","disease","character","ofrench"]},{"w":"hypergroup","d":"In mathematics, a generalization of a group in which the result of combining two elements is a set of possible elements rather than a single element, extending standard group theory.","s":"The mathematician introduced the concept of a hypergroup to extend the standard definition of a group in algebra.","p":"HY-per-groop","o":"French","y":9,"bp":29,"sy":"hy.per.group","ps":"noun","t":["chemistry","logic","numbers","ofrench"]},{"w":"hyperhydrogen","d":"A theoretical or experimental form of hydrogen that contains additional energy, particles, or isotopic variation beyond ordinary hydrogen, studied in advanced physics and chemistry.","s":"Physicists theorized about hyperhydrogen as an exotic atom containing extra neutrons bound to a hydrogen nucleus.","p":"hy-per-HY-droh-jen","o":"French","y":9,"bp":40,"sy":"hy.per.hy.dro.gen","ps":"noun","t":["chemistry","physics","numbers","ofrench"]},{"w":"hypernatremic","d":"Relating to or characterized by hypernatremia, a medical condition in which there is an abnormally high concentration of sodium in the blood.","s":"The dehydrated patient was hypernatremic, meaning his blood contained too much sodium.","p":"hy-per-nay-TREE-mik","o":"French","y":9,"bp":40,"sy":"hy.per.na.trem.ic","ps":"adjective","t":["body","chemistry","character","ofrench"]},{"w":"hypernymic","d":"Relating to a hypernym, which is a word whose meaning includes or is broader than that of another word; describing a word that sits at a higher level in a semantic hierarchy.","s":"The linguist noted that 'animal' has a hypernymic relationship to 'dog,' since animal is the broader category.","p":"hy-per-NIM-ik","o":"French","y":9,"bp":29,"sy":"hy.per.nymic","ps":"adjective","t":["wordwords","ofrench"]},{"w":"hyperosmic","d":"Relating to or characterized by hyperosmia, an abnormally heightened or over-sensitive sense of smell in which ordinary odors are perceived as unusually strong or overwhelming.","s":"The hyperosmic patient could detect the faintest odors that everyone else in the room completely missed.","p":"hy-per-OZ-mik","o":"French","y":8,"bp":30,"sy":"hy.per.os.mic","ps":"adjective","t":["character","ofrench"]},{"w":"hypersthenic","d":"Relating to or characterized by hypersthenia, a condition of excessive muscular strength or bodily vigor beyond what is considered normal or healthy.","s":"The hypersthenic individual had a broad, muscular build that made him naturally suited to strength sports.","p":"hy-per-STHEN-ik","o":"French","y":8,"bp":38,"sy":"hy.per.s.thenic","ps":"adjective","t":["character","ofrench"]},{"w":"hypertonicity","d":"(of a solution) the extent to which a solution has a higher osmotic pressure than some other","s":"The IV solution's hypertonicity caused water to move out of the patient's cells and into the bloodstream.","p":"hy-per-toh-NIS-ih-tee","o":"French","y":9,"bp":40,"sy":"hy.per.tonic.i.ty","ps":"noun","t":["ofrench"]},{"w":"hypnagogic","d":"sleep inducing","s":"The warm bath had a hypnagogic effect, and she drifted off to sleep within minutes.","p":"hip-nuh-GOJ-ik","o":"French","y":6,"bp":32,"sy":"hyp.n.a.gog.ic","ps":"adjective","t":["ofrench"]},{"w":"hypnopaedic","d":"Relating to hypnopaedia, the practice or concept of learning or absorbing information while asleep, often through audio recordings played during sleep.","s":"The scientist studied hypnopaedic learning to see if students could absorb vocabulary while sleeping.","p":"hip-noh-PEE-dik","o":"French","y":8,"bp":32,"ps":"adjective","t":["ofrench"]},{"w":"hypoalgesic","d":"Relating to or causing hypoalgesia, a reduced sensitivity to pain, in which a person feels less pain than would normally be expected from a given stimulus.","s":"The medication had a hypoalgesic effect, reducing the patient's sensitivity to pain.","p":"hy-poh-al-JEE-zik","o":"French","y":8,"bp":35,"sy":"hy.poal.gesic","ps":"adjective","t":["ofrench"]},{"w":"hypochondres","d":"The plural of hypochondre; the regions of the abdomen located on either side beneath the lower ribs and above the waist, associated historically with the seat of melancholy.","s":"The anatomist pointed to the hypochondres, the upper regions of the abdomen beneath the ribs.","p":"hy-poh-KON-drz","o":"French","y":9,"bp":35,"sy":"hypochon.dres","ps":"noun","t":["body","emotions","ofrench"]},{"w":"hypoellipse","d":"A geometric curve related to an ellipse but defined by a superellipse equation with an exponent less than two, producing a shape that is more pointed or diamond-like than a standard ellipse.","s":"The mathematician drew a hypoellipse on the board to illustrate the special curve's properties.","p":"hy-poh-ih-LIPS","o":"French","y":9,"bp":35,"sy":"hy.poel.lipse","ps":"noun","t":["minerals","numbers","ofrench"]},{"w":"hyponymic","d":"Relating to a hyponym, which is a word whose meaning is a specific instance or subset of a broader term; describing a word that falls under a more general category word.","s":"The word 'oak' has a hyponymic relationship to 'tree' because oak is a type of tree.","p":"hy-PON-ih-mik","o":"French","y":9,"bp":26,"sy":"hy.ponymic","ps":"adjective","t":["wordwords","ofrench"]},{"w":"hyponymically","d":"In a manner relating to hyponymy; in a way that expresses or demonstrates a specific subordinate word-meaning relationship within a semantic hierarchy.","s":"Linguists explained that 'sparrow' is hyponymically related to 'bird' in the vocabulary hierarchy.","p":"hy-PON-ih-mik-lee","o":"French","y":9,"bp":38,"sy":"hy.ponymi.cal.ly","ps":"adverb","t":["wordwords","ofrench"]},{"w":"hypsometric","d":"Relating to hypsometry, the measurement and mapping of the elevation of land surfaces above sea level, especially as represented on topographic maps.","s":"The hypsometric map used color gradients to show the elevation of mountain ranges.","p":"hip-soh-MET-rik","o":"French","y":7,"bp":37,"sy":"hyp.so.met.ric","ps":"adjective","t":["landforms","waterways","maps","numbers","ofrench"]},{"w":"hydroecology","d":"The scientific study of the relationships between water systems and the living organisms and ecosystems that depend on or are shaped by those aquatic environments.","s":"The hydroecology course taught students how river flow, water chemistry, and seasonal flooding all work together to determine which plants and animals can survive in a wetland.","p":"HY-droh-ee-KOL-uh-jee","o":"German","y":8,"bp":35,"sy":"hy.droe.col.o.gy","ps":"noun","t":["marine","ecology","onordic"]},{"w":"hyrse","d":"An archaic or dialectal term for millet, a small-seeded cereal grain that was cultivated and used as a food source in early European and other ancient cultures.","s":"Archaeologists unearthed charred remains of hyrse in the ancient settlement, proving that the people who lived there grew and ate millet thousands of years ago.","p":"HERSS","o":"German","y":8,"bp":12,"ps":"noun","t":["farming","ancient","wordwords","onordic"]},{"w":"hyoshigi","d":"A pair of hard wooden clappers used in traditional Japanese theater and festivals to signal the start or end of a performance by striking them together to produce a sharp clacking sound.","s":"The stage manager clapped the hyoshigi together sharply to signal the start of the kabuki performance.","p":"hyoh-SHEE-gee","o":"Japanese","y":8,"bp":15,"sy":"hyoshi.gi","ps":"noun","t":["stage","festivals","oeastasia"]},{"w":"Hyacinthian","d":"Of or relating to Hyacinthus, the figure from Greek mythology beloved by Apollo; also used to describe something resembling the hyacinth flower in color or character.","s":"The garden was decorated in a Hyacinthian purple, nodding to the myth of the beloved youth transformed into a flower.","p":"hy-uh-SIN-thee-un","o":"Latin","y":8,"bp":35,"sy":"hy.acinthi.an","ps":"adjective","t":["flowers","myth","colors","olatin"]},{"w":"hyalescence","d":"The process or quality of becoming glassy or transparent; a gradual transition toward a clear, glass-like appearance in a substance or material.","s":"The scientist noted a subtle hyalescence in the mineral sample as it became increasingly glassy under heat.","p":"hy-uh-LES-unts","o":"Latin","y":9,"bp":34,"sy":"hyales.cence","ps":"noun","t":["olatin"]},{"w":"hydriform","d":"Having a shape or form resembling that of a hydra; characterized by a body plan with a tubular or tentacled structure typical of aquatic invertebrates.","s":"The biologist described the hydriform polyp as a tiny water-shaped organism clinging to the reef.","p":"HY-drih-form","o":"Latin","y":8,"bp":28,"sy":"hy.dri.form","ps":"adjective","t":["marine","character","olatin"]},{"w":"hydroculture","d":"The practice of growing plants in a water-based nutrient solution without soil, allowing roots to absorb minerals directly from the liquid environment.","s":"The school greenhouse experiment used hydroculture to grow lettuce in nutrient-rich water without any soil.","p":"HY-droh-kul-cher","o":"Latin","y":9,"bp":38,"sy":"hy.dro.cul.ture","ps":"noun","t":["botany","minerals","ecology","olatin"]},{"w":"hyemal","d":"Of or relating to winter; characteristic of or occurring during the winter season.","s":"The poet described the hyemal landscape as a world frozen in silence under thick grey skies.","p":"HY-uh-mul","o":"Latin","y":8,"bp":18,"sy":"hye.mal","ps":"adjective","t":["time","olatin"]},{"w":"hyemation","d":"The act or process of passing the winter, especially in a dormant or resting state; a wintering period for an organism or community.","s":"The naturalist wrote about the hyemation of the bear, noting it spent months in deep winter sleep.","p":"hy-uh-MAY-shun","o":"Latin","y":8,"bp":28,"sy":"hye.ma.tion","ps":"noun","t":["time","olatin"]},{"w":"hypaethral","d":"partly or entirely open to the sky","s":"The ancient hypaethral temple had no roof over its central chamber, leaving worshippers under the open sky.","p":"hy-PEE-thrul","o":"Latin","y":8,"bp":27,"sy":"hy.paethral","ps":"adjective","t":["olatin"]},{"w":"hyperarc","d":"In graph theory and geometry, an arc or directed edge that connects more than two nodes or extends beyond the properties of a standard arc into higher-dimensional structures.","s":"The mathematician drew a hyperarc connecting multiple nodes simultaneously in the complex graph diagram.","p":"HY-per-ark","o":"Latin","y":8,"bp":27,"sy":"hy.per.arc","ps":"noun","t":["logic","numbers","olatin"]},{"w":"hyperarticulate","d":"Expressing oneself with an exceptionally high degree of clarity and precision, often to a degree that seems excessive or overly elaborate compared to normal speech.","s":"The hyperarticulate debate champion could express complex ideas with such precision that judges were always impressed.","p":"hy-per-ar-TIK-yoo-lit","o":"Latin","y":9,"bp":31,"sy":"hy.per.ar.tic.u.late","ps":"adjective","t":["olatin"]},{"w":"hyperbaton","d":"reversal of normal word order (as in \`cheese I love')","s":"The poet used hyperbaton cleverly, writing 'the stars bright' instead of 'the bright stars' for dramatic effect.","p":"hy-PER-buh-ton","o":"Latin","y":8,"bp":30,"sy":"hy.per.ba.ton","ps":"noun","t":["dishes","wordwords","olatin"]},{"w":"hyperbolist","d":"A person who habitually uses hyperbole, making extreme exaggerations to emphasize a point or create a dramatic effect in speech or writing.","s":"Everyone at school knew Jake was a hyperbolist when he claimed his backpack weighed a million pounds.","p":"hy-PER-buh-list","o":"Latin","y":8,"bp":35,"sy":"hy.per.bolist","ps":"noun","t":["stage","olatin"]},{"w":"hyperbolize","d":"to enlarge beyond bounds or the truth","p":"hy-PER-buh-lyz","o":"Latin","y":9,"bp":35,"sy":"hy.per.bolize","ps":"verb","t":["logic","olatin"]},{"w":"hypercarnivorous","d":"Describing an animal whose diet consists of more than 70 percent meat, making it far more dependent on flesh as a food source than a typical carnivore.","s":"The hypercarnivorous wolf relies almost entirely on meat, with very little plant matter in its diet.","p":"hy-per-KAR-nih-vor-us","o":"Latin","y":9,"bp":32,"sy":"hy.per.car.niv.o.rous","ps":"adjective","t":["animals","numbers","olatin"]},{"w":"hypercompact","d":"Extremely compact or densely packed, compressed far beyond normal limits, as in certain astronomical objects or engineered devices.","s":"The engineers designed a hypercompact battery that could store enormous energy in a device smaller than a coin.","p":"hy-per-KOM-pakt","o":"Latin","y":8,"bp":38,"sy":"hy.per.com.pact","ps":"adjective","t":["astronomy","tools","olatin"]},{"w":"hypercone","d":"A geometric figure that is the four-dimensional analogue of a three-dimensional cone, formed by extending the concept of a cone into a higher dimension.","s":"The mathematician explained how a hypercone exists in four-dimensional space, extending the idea of a regular cone.","p":"HY-per-kohn","o":"Latin","y":9,"bp":28,"sy":"hy.per.cone","ps":"noun","t":["olatin"]},{"w":"hyperconfident","d":"Having an extremely high or excessive degree of self-confidence, often beyond what the situation or one's abilities warrant.","s":"The hyperconfident student refused to study for the test, convinced she already knew everything.","p":"hy-per-KON-fih-dunt","o":"Latin","y":9,"bp":29,"sy":"hy.per.con.fi.dent","ps":"adjective","t":["olatin"]},{"w":"hyperconjugation","d":"In chemistry, the interaction of electrons in a sigma bond with an adjacent empty or partially filled p-orbital or pi system, stabilizing the molecule in a way similar to conjugation but extending beyond usual boundaries.","s":"In chemistry class, we learned that hyperconjugation helps explain why some molecules are more stable than expected.","p":"hy-per-kon-joo-GAY-shun","o":"Latin","y":9,"bp":32,"sy":"hy.per.con.ju.ga.tion","ps":"noun","t":["chemistry","astronomy","physics","olatin"]},{"w":"hypercorrect","d":"Describing a usage or form that results from applying a grammatical rule too zealously, producing an error by trying too hard to be correct.","s":"She used hypercorrect grammar by saying 'between you and I,' thinking it sounded more formal.","p":"hy-per-kuh-REKT","o":"Latin","y":9,"bp":38,"sy":"hy.per.cor.rect","ps":"adjective","t":["wordwords","olatin"]},{"w":"hypercorrection","d":"A linguistic error that occurs when a speaker applies a rule of grammar or pronunciation too broadly, producing a form that is considered incorrect even while attempting to sound more proper.","s":"Saying 'whomever called' when 'whoever called' is right is a classic example of hypercorrection.","p":"hy-per-kuh-REK-shun","o":"Latin","y":8,"bp":30,"sy":"hy.per.cor.rec.tion","ps":"noun","t":["wordwords","olatin"]},{"w":"hypercorrectly","d":"In a manner that reflects hypercorrection; applying a linguistic or grammatical rule with such excessive zeal that the result becomes incorrect.","s":"He hypercorrectly avoided ending sentences with prepositions, producing awkward phrases no one actually uses.","p":"hy-per-kuh-REKT-lee","o":"Latin","y":9,"bp":29,"sy":"hy.per.cor.rect.ly","ps":"adverb","t":["wordwords","olatin"]},{"w":"hypercorrectness","d":"The state or quality of being hypercorrect; the tendency to overcorrect language use in a way that introduces new errors while trying to avoid others.","s":"Her hypercorrectness in speech made conversations stiff because she obsessed over every tiny grammar rule.","p":"hy-per-kuh-REKT-nes","o":"Latin","y":9,"bp":30,"sy":"hy.per.cor.rect.ness","ps":"noun","t":["wordwords","olatin"]},{"w":"hypercycle","d":"In theoretical biology, a self-organizing system of interacting molecules in which each component catalyzes the reproduction of the next, forming a cooperative loop that could explain the origin of life.","s":"The biology lecture explained how a hypercycle is a self-replicating system of molecules that may have helped start life.","p":"HY-per-sy-kul","o":"Latin","y":9,"bp":30,"sy":"hy.per.cy.cle","ps":"noun","t":["chemistry","olatin"]},{"w":"hypercylinder","d":"A four-dimensional geometric figure that is the higher-dimensional analogue of a cylinder, formed by extending a three-dimensional cylinder into a fourth spatial dimension.","s":"The geometry textbook challenged students to imagine a hypercylinder extending into a fourth dimension.","p":"hy-per-SIL-in-der","o":"Latin","y":9,"bp":26,"sy":"hy.per.cylin.der","ps":"noun","t":["olatin"]},{"w":"hyperdense","d":"Having an extremely high density, far greater than normal; used to describe matter packed so tightly that it exceeds ordinary measures of compactness, as in neutron stars.","s":"A neutron star is hyperdense, packing more mass than our sun into a sphere just a few miles across.","p":"HY-per-dens","o":"Latin","y":9,"bp":29,"sy":"hy.per.dense","ps":"adjective","t":["astronomy","physics","numbers","olatin"]},{"w":"hyperdiffusion","d":"An extremely rapid or exaggerated spreading of particles, substances, or cultural traits beyond what normal diffusion would produce, occurring at an accelerated or amplified rate.","s":"Researchers studied hyperdiffusion in fluids where particles spread far faster than normal diffusion would predict.","p":"hy-per-dih-FYOO-zhun","o":"Latin","y":9,"bp":29,"sy":"hy.per.dif.fu.sion","ps":"noun","t":["physics","olatin"]},{"w":"hyperdiverse","d":"Exhibiting an extraordinarily high level of diversity, especially in biological contexts where a region or taxon contains an exceptional variety of species.","s":"The rainforest was hyperdiverse, containing thousands of insect species in just one acre.","p":"hy-per-dih-VERS","o":"Latin","y":9,"bp":38,"sy":"hy.per.di.verse","ps":"adjective","t":["olatin"]},{"w":"hyperdulia","d":"In Catholic theology, the highest form of veneration given to the Virgin Mary, distinguished from the worship due to God alone and the lesser honor paid to other saints.","s":"The theologian explained that hyperdulia is the special veneration reserved for the Virgin Mary.","p":"hy-per-DOO-lee-uh","o":"Latin","y":9,"bp":30,"sy":"hy.per.du.lia","ps":"noun","t":["religion","olatin"]},{"w":"hyperelastic","d":"Describing a material that can undergo very large elastic deformations and return to its original shape, with stress-strain behavior that is nonlinear and highly flexible.","s":"The gymnast's hyperelastic joints allowed her to bend in ways most people cannot.","p":"hy-per-ih-LAS-tik","o":"Latin","y":7,"bp":39,"sy":"hy.per.e.las.tic","ps":"adjective","t":["olatin"]},{"w":"hyperextend","d":"extend a joint beyond its normal range","s":"Don't hyperextend your elbow.","p":"hy-per-ik-STEND","o":"Latin","y":7,"bp":37,"sy":"hy.per.ex.tend","ps":"verb","t":["olatin"]},{"w":"hyperfeminine","d":"Exhibiting or characterized by an exaggerated or extreme degree of traits traditionally associated with femininity, often beyond what is considered typical or expected.","s":"The costume designer created a hyperfeminine look with layers of lace, ruffles, and pink ribbons.","p":"hy-per-FEM-ih-nin","o":"Latin","y":9,"bp":28,"sy":"hy.per.fem.i.nine","ps":"adjective","t":["festivals","character","olatin"]},{"w":"hyperferremia","d":"An abnormally high concentration of iron in the blood, which can lead to organ damage and other serious health complications if left untreated.","s":"The doctor ordered additional blood tests after the initial panel suggested the patient might be suffering from hyperferremia caused by repeated iron infusions.","p":"HY-per-feh-REE-mee-uh","o":"Latin","y":9,"bp":26,"sy":"hy.per.fer.remia","ps":"noun","t":["body","chemistry","music","olatin"]},{"w":"hyperflexion","d":"The excessive bending of a limb or joint beyond its normal range of motion, often resulting in injury to muscles, tendons, or ligaments.","s":"The gymnast suffered a severe wrist injury after a fall caused sudden hyperflexion that stretched her tendons far beyond their safe limit.","p":"HY-per-FLEK-shun","o":"Latin","y":8,"bp":38,"sy":"hy.per.flex.ion","ps":"noun","t":["body","olatin"]},{"w":"hyperfocus","d":"An intense and prolonged state of concentration on a single task or subject, often to the exclusion of everything else around the person.","s":"During finals week, Maya entered a state of hyperfocus so deep that she didn't notice her phone buzzing with dozens of messages for three straight hours.","p":"HY-per-FOH-kus","o":"Latin","y":7,"bp":30,"sy":"hy.per.fo.cus","ps":"noun","t":["olatin"]},{"w":"hypergenesis","d":"Excessive or abnormal development and growth of tissue or an organism, beyond what is considered normal or healthy.","s":"The biologist noted signs of hypergenesis in the lab samples, where the cells had multiplied far more rapidly than any previous experiment had recorded.","p":"HY-per-JEN-eh-sis","o":"Latin","y":8,"bp":41,"sy":"hy.per.ge.n.e.sis","ps":"noun","t":["body","olatin"]},{"w":"hypergeometric","d":"Relating to a type of advanced mathematical function or probability distribution that extends beyond standard geometric relationships, used in combinatorics and statistics.","s":"The statistics professor challenged her advanced class with a problem requiring a hypergeometric distribution to calculate the probability of drawing specific cards from a deck.","p":"HY-per-jee-oh-MET-rik","o":"Latin","y":7,"bp":30,"sy":"hy.per.ge.o.met.ric","ps":"adjective","t":["numbers","olatin"]},{"w":"hypergeometrically","d":"In a manner relating to or described by hypergeometric functions or distributions, applying advanced mathematical methods that go beyond ordinary geometric calculations.","s":"The researcher explained that the sampling outcomes could only be modeled hypergeometrically, since the population was finite and items were drawn without replacement.","p":"HY-per-jee-oh-MET-rih-klee","o":"Latin","y":9,"bp":35,"sy":"hy.per.ge.o.met.ri.cal.ly","ps":"adverb","t":["numbers","olatin"]},{"w":"hypnocyst","d":"A dormant, protective cyst formed by certain microorganisms that allows them to survive unfavorable environmental conditions in a sleep-like inactive state.","s":"The scientist discovered that the single-celled organism had formed a hypnocyst, encasing itself in a tough protective shell to survive the freezing winter temperatures.","p":"HIP-noh-sist","o":"Latin","y":9,"bp":28,"sy":"hyp.no.cyst","ps":"noun","t":["ecology","olatin"]},{"w":"hypochondrium","d":"the upper region of the abdomen just below the lowest ribs on either side of the epigastrium","s":"The doctor pressed gently on the patient's hypochondrium to check for liver tenderness.","p":"hy-poh-KON-dree-um","o":"Latin","y":9,"bp":25,"sy":"hypochon.dri.um","ps":"noun","t":["body","olatin"]},{"w":"hypocomplementemia","d":"A condition characterized by abnormally low levels of complement proteins in the blood, which can impair the immune system's ability to fight infection and disease.","s":"The immunologist explained that the patient's recurring infections were consistent with hypocomplementemia, meaning her immune system lacked enough complement proteins to respond effectively.","p":"HY-poh-kom-pleh-men-TEE-mee-uh","o":"Latin","y":9,"bp":27,"sy":"hypocom.ple.mentemia","ps":"noun","t":["body","disease","character","olatin"]},{"w":"hypocorism","d":"a name of endearment (especially one using a diminutive suffix)","s":"\`Billy' is a hypocorism for \`William'.","p":"hy-POK-oh-riz-um","o":"Latin","y":8,"bp":26,"ps":"noun","t":["wordwords","olatin"]},{"w":"hypogeum","d":"An underground chamber or series of rooms, especially one used in ancient times as a tomb, shrine, or storage space beneath a building.","s":"The archaeologists carefully excavated the hypogeum beneath the ancient Roman villa, discovering elaborately painted walls and ceramic urns filled with the ashes of the deceased.","p":"hy-poh-JEE-um","o":"Latin","y":8,"bp":25,"sy":"hy.pogeum","ps":"noun","t":["buildings","religion","ancient","time","olatin"]},{"w":"Hypophrygian","d":"Relating to an ancient Greek musical mode or its medieval equivalent that is positioned a step below the Phrygian mode, giving it a distinct and somber tonal character.","s":"The medieval choir performed the chant in the Hypophrygian mode, and its low, resonant tones echoed through the stone walls of the cathedral with an eerie beauty.","p":"hy-poh-FRIJ-ee-un","o":"Latin","y":9,"bp":36,"sy":"hy.pophry.gian","ps":"adjective","t":["music","ancient","olatin"]},{"w":"hypothecate","d":"pledge without delivery or title of possession","p":"hy-POTH-eh-kayt","o":"Latin","y":8,"bp":37,"sy":"hy.poth.e.cate","ps":"verb","t":["olatin"]},{"w":"hypothecation","d":"The practice of pledging an asset as collateral for a loan or debt without transferring ownership or possession of that asset to the lender.","s":"The bank approved the business loan only after the owner agreed to hypothecation of the company's warehouse, meaning the building secured the debt without changing hands.","p":"hy-poth-eh-KAY-shun","o":"Latin","y":7,"bp":28,"sy":"hy.poth.e.ca.tion","ps":"noun","t":["economy","olatin"]},{"w":"hypothecator","d":"A person who pledges property or assets as collateral for a loan or obligation while retaining possession and ownership of those assets.","s":"As the hypothecator in the agreement, she kept full use of her investment portfolio even though it legally served as security for the substantial business loan she had taken.","p":"hy-POTH-eh-kay-ter","o":"Latin","y":8,"bp":39,"sy":"hy.poth.e.ca.tor","ps":"noun","t":["economy","olatin"]},{"w":"hystericalness","d":"The quality or state of being hysterical; an extreme degree of uncontrolled emotion, laughter, fear, or excitement that is difficult to manage or suppress.","s":"The hystericalness of the crowd at the comedy show reached such a peak that the performer had to pause for several minutes before anyone could hear his next joke.","p":"hih-STEHR-ih-kul-nes","o":"Latin","y":9,"bp":29,"sy":"hys.ter.i.cal.ness","ps":"noun","t":["emotions","olatin"]},{"w":"hystricine","d":"Of, relating to, or resembling porcupines; having characteristics typical of the porcupine family Hystricidae, especially the presence of sharp defensive quills.","s":"The zoologist described the animal's hystricine defense mechanism in detail, explaining how its sharp quills detached easily and embedded themselves in the skin of any predator that came too close.","p":"HIS-trih-syn","o":"Latin","y":9,"bp":27,"sy":"hys.tricine","ps":"adjective","t":["kinship","olatin"]},{"w":"hyawa","d":"A resinous substance obtained from a tropical tree native to South America, used by indigenous peoples as incense, a sealant, or in traditional medicinal practices.","s":"The shaman carefully collected hyawa from the notched trunk of the tree, explaining that the fragrant resin would be burned during the healing ceremony that evening.","p":"HYAH-wah","o":"Macushi","y":9,"bp":12,"ps":"noun","t":["body","pharmacy","flowers","festivals"]},{"w":"hyomental","d":"Relating to or connecting the hyoid bone in the throat and the chin; describing the anatomical region or muscles between these two structures.","s":"The anatomy student labeled the hyomental region on her diagram of the lower face and neck.","p":"hy-oh-MEN-tul","o":"French","y":8,"bp":28,"sy":"hy.omen.tal","ps":"adjective","t":["body","ofrench"]},{"w":"hyperfunction","d":"Excessive or abnormally elevated functioning of an organ, gland, or system beyond its normal operating level.","s":"The thyroid's hyperfunction caused her heart to race and made it hard to sleep.","p":"hy-per-FUNK-shun","o":"French","y":9,"bp":38,"sy":"hy.per.func.tion","ps":"noun","t":["body","music","ofrench"]},{"w":"hypofunction","d":"A condition in which an organ or body system operates at a level below its normal or expected capacity, producing insufficient output or activity.","s":"The doctor explained that hypofunction of the adrenal glands leads to constant fatigue.","p":"HY-poh-funk-shun","o":"French","y":8,"bp":38,"sy":"hy.po.func.tion","ps":"noun","t":["music","ofrench"]},{"w":"hyenalike","d":"Resembling or characteristic of a hyena, especially in having a sneaky, scavenging, or cackling quality.","s":"The villain's hyenalike cackle echoed through the empty warehouse.","p":"hy-EE-nuh-lyk","o":"French","y":9,"bp":26,"sy":"hye.nalike","ps":"adjective","t":["ofrench"]},{"w":"hymnless","d":"Lacking or without hymns; describing a religious service or setting that has no hymns sung or performed.","s":"The small chapel held a hymnless service, relying only on spoken prayer and silence.","p":"HIM-les","o":"French","y":8,"bp":19,"sy":"hymn.less","ps":"adjective","t":["religion","ofrench"]},{"w":"hymnlike","d":"Resembling or having the quality of a hymn; solemn, reverent, and melodic in the manner of a religious song.","s":"The choir sang a hymnlike melody that filled the auditorium with a sense of peace.","p":"HIM-lyk","o":"French","y":9,"bp":19,"sy":"hymn.like","ps":"adjective","t":["music","religion","ofrench"]},{"w":"hymnsheet","d":"A printed sheet of paper containing the words, and sometimes the music, of one or more hymns for use during a religious service.","s":"Each guest at the memorial service was handed a hymnsheet so they could sing along.","p":"HIM-sheet","o":"French","y":8,"bp":26,"sy":"hymn.sheet","ps":"noun","t":["music","religion","wordwords","ofrench"]},{"w":"hypercube","d":"A geometric figure in four or more dimensions that is the analogue of a cube; a mathematical object extending the concept of a square and cube into higher-dimensional space.","s":"The math teacher showed us how a hypercube is to a cube as a cube is to a square.","p":"HY-per-kyoob","o":"French","y":7,"bp":28,"sy":"hy.per.cube","ps":"noun","t":["numbers","ofrench"]},{"w":"hyperlinkage","d":"The state or system of having numerous hyperlinks connecting web pages or digital documents together; an extensive network of electronic cross-references.","s":"The website's hyperlinkage made it easy to jump from one article to related topics instantly.","p":"HY-per-link-ij","o":"French","y":9,"bp":38,"sy":"hy.per.link.age","ps":"noun","t":["physics","ofrench"]},{"w":"hypersensitize","d":"To make extremely or excessively sensitive to a stimulus, substance, or emotional trigger, often beyond a normal or healthy degree.","s":"Repeated exposure to the allergen can hypersensitize the immune system, making reactions worse over time.","p":"hy-per-SEN-sih-tyz","o":"French","y":9,"bp":29,"sy":"hy.per.sen.si.tize","ps":"verb","t":["emotions","ofrench"]},{"w":"hypoarticulation","d":"The condition of speaking with insufficient clarity or precision, producing sounds or words that are mumbled, slurred, or inadequately formed.","s":"The speech therapist diagnosed the student with hypoarticulation because his words were consistently mumbled and unclear.","p":"hy-poh-ar-tik-yoo-LAY-shun","o":"French","y":9,"bp":32,"sy":"hy.poar.tic.u.la.tion","ps":"noun","t":["wordwords","ofrench"]},{"w":"hypocritely","d":"In the manner of a hypocrite; acting or speaking with insincerity or pretending to have beliefs and virtues that one does not actually hold.","s":"She hypocritely lectured others about honesty while hiding her own mistakes.","p":"HIP-oh-krit-lee","o":"French","y":8,"bp":35,"sy":"hyp.ocrite.ly","ps":"adverb","t":["logic","ofrench"]},{"w":"hydrophyte","d":"a plant that grows partly or wholly in water whether rooted in the mud, as a lotus, or floating without anchorage, as the water hyacinth","y":9,"bp":54,"nt":"Senior","ps":"noun","t":["botany","flowers","seafaring"]},{"w":"hydroperiod","d":"the length of time an area stays flooded","s":"The marsh has a long hydroperiod.","p":"HY-droh-peer-ee-uhd","o":"Greek","y":8,"bp":81,"nt":"North South Finals","t":["waterways","numbers","time","ogreek"]},{"w":"hyacinthine","d":"of a deep purplish blue, or of thick curling hair","s":"The painter gave the boy hyacinthine curls.","p":"hy-uh-SIN-thyn","y":9,"bp":8,"m":"hiacinthine","nt":"Advanced","ps":"adjective","sy":"hy.a.cin.thine","o":"Greek","t":["eponyms","ogreek","epgreek"]}]`,h:`[{"w":"hygroscopic","d":"tending to absorb moisture from the air","s":"The little packets in new shoe boxes contain a hygroscopic material to keep the shoes dry.","p":"hy-gruh-SKAHP-ik","o":"Greek","y":6,"bp":45,"nt":"Open","ps":"adjective","t":["chemistry","weather","championship","ogreek"],"m":"hygroskopic","sy":"hy.gro.scop.ic"},{"w":"hypermetric","d":"Having one or more syllables beyond the standard measure of a poetic verse.","s":"The composer allowed a hypermetric line to spill over the usual rhythm to emphasize the singer's deep emotion.","p":"hy-pur-MET-rik","o":"Greek","y":8,"bp":30,"nt":"Open","ps":"adjective","t":["championship","prosody","greek","poetry","numbers","wordwords","ogreek"],"m":"hypermetrick","sy":"hy.per.met.ric"},{"w":"hymenophore","d":"The portion of a fungal fruiting body that bears the reproductive cell-producing layer.","s":"On a typical button mushroom, the hymenophore consists of the brown gills under the cap.","p":"hy-MEN-uh-for","o":"Greek","y":9,"bp":50,"nt":"Open","ps":"noun","t":["mycology","structures","championship","ogreek"],"m":"himenophore","sy":"hy.men.o.phore"},{"w":"hymenopteran","d":"a member of a large group of mostly social insects that includes bees and wasps","s":"The honeybee is a vital hymenopteran that helps pollinate colorful flowers in our garden.","p":"hy-muh-NOP-tuh-ruhn","o":"Greek","y":8,"bp":50,"nt":"Open","ps":"noun","t":["championship","entomology","insects","ogreek"],"m":"hymenoptaran","sy":"hy.men.op.ter.an"},{"w":"hypostatic","d":"relating to the underlying, essential personal reality or substance, especially in religious doctrines.","s":"The teacher explained the hypostatic union as the perfect joining of divine and human qualities in one person.","p":"hye-puh-STAT-ik","o":"Greek","y":6,"bp":35,"nt":"Open","ps":"adjective","t":["championship","theology","philosophy","religion","logic","ogreek"],"m":"hipostatic","sy":"hy.po.stat.ic"},{"w":"hylomorphism","d":"the theory that every physical object is a combination of matter and form.","s":"According to the ancient concept of hylomorphism, a bronze statue gets its identity from both the metal and the artist's design.","p":"hy-luh-MOR-fiz-um","o":"Greek","y":8,"bp":55,"nt":"Open","ps":"noun","t":["championship","philosophy","logic","ogreek"],"m":"hylomorfism","sy":"hy.lo.mor.phism"},{"w":"hypostasis","d":"the underlying reality or true substance of something, regardless of its changing outward appearance.","s":"The debaters tried to figure out the hypostasis of justice, looking past specific laws to find its truest form.","p":"hy-POS-tuh-sis","o":"Greek","y":6,"bp":55,"nt":"Open","ps":"noun","t":["championship","philosophy","ogreek"],"m":"hipostasis","sy":"hy.pos.ta.sis"},{"w":"hypocycloid","d":"a shape traced by a point on a small circle rolling around the inside of a larger circle.","s":"Using gears of different sizes, the young engineer designed a machine that moves in a perfect hypocycloid.","p":"hy-puh-SY-kloyd","o":"Greek","y":9,"bp":40,"nt":"Open","ps":"noun","t":["championship","geometry","kinematics","numbers","ogreek"],"m":"hypocicloid","sy":"hy.po.cy.cloid"},{"w":"hyperboloid","d":"a geometric surface that looks like an hourglass or a curved cooling tower.","s":"The modern tower was built in the shape of a hyperboloid, twisting elegantly upward into the sky.","p":"hy-PUR-buh-loyd","o":"Greek","y":8,"bp":45,"nt":"Open","ps":"noun","t":["geometry","surfaces","buildings","championship","ogreek"],"m":"hyperbaloid","sy":"hy.per.bo.loid"},{"w":"hyetography","d":"The study and mapping of the geographic distribution of rainfall.","s":"By studying hyetography, scientists can figure out which regions of the country get the most summer rain.","p":"hy-uh-TOG-ruh-fee","o":"Greek","y":8,"bp":60,"nt":"Open","ps":"noun","t":["championship","meteorology","rain","weather","ogreek"],"m":"hyetografy","sy":"hy.e.tog.ra.phy"},{"w":"hyperlexia","d":"A fascinating ability where a very young child learns to read at an incredibly advanced level without being taught.","s":"Her hyperlexia was evident when she started reading thick chapter books fluently at age three.","p":"high-per-LEK-see-uh","o":"Greek","y":9,"bp":40,"nt":"Open","ps":"noun","t":["learning","development","championship","ogreek"],"m":"hyperlexea","sy":"hy.per.lex.i.a"},{"w":"hypermnesia","d":"An incredibly heightened or unusually excellent ability to remember detailed past events.","s":"With her extraordinary hypermnesia, the detective could recall the exact outfit every suspect wore on any given day.","p":"high-perm-NEE-zhuh","o":"Greek","y":9,"bp":55,"nt":"Open","ps":"noun","t":["championship","memory","cognition","ogreek"],"m":"hypermnezia","sy":"hy.perm.ne.si.a"},{"w":"hyperinflation","d":"A completely out-of-control economic situation where prices skyrocket so fast that money becomes almost worthless.","s":"During the terrible period of hyperinflation, a loaf of bread that cost one dollar on Monday cost fifty dollars by Friday.","p":"hy-per-in-FLAY-shun","o":"Greek","y":6,"bp":35,"nt":"Open","ps":"noun","t":["championship","currency","prices","economy","ogreek"],"m":"hyperenflation","sy":"hy.per.in.fla.tion"},{"w":"hypsography","d":"The geographic mapping of the varying elevations of the earth's surface.","s":"The colorful map used hypsography to show the steep mountain peaks in dark brown and the flat plains in green.","p":"hip-SOG-ruh-fee","o":"Greek","y":8,"bp":55,"nt":"Open","ps":"noun","t":["championship","geography","mapping","ogreek"],"m":"hipsography","sy":"hyp.sog.ra.phy"},{"w":"hygrometry","d":"The branch of physics that deals with measuring the amount of moisture or humidity in the air.","s":"Because the rare paintings needed a dry environment, the museum relied on hygrometry to constantly monitor the room's air.","p":"hy-GROM-uh-tree","o":"Greek","y":8,"bp":55,"nt":"Open","ps":"noun","t":["championship","science","measurement","weather","physics","ogreek"],"m":"higrometry","sy":"hy.grom.e.try"},{"w":"hypsographic","d":"Pertaining to the visual representation of elevation above sea level on a map.","s":"A detailed hypsographic curve vividly shows how much of the continent sits safely above the ocean surface.","p":"hip-suh-GRAF-ik","o":"Greek","y":8,"bp":50,"nt":"Open","ps":"adjective","t":["cartography","geography","maps","championship","ogreek"],"m":"hypsografic","sy":"hyp.so.graph.ic"},{"w":"hypersthene","d":"a dark, shiny mineral that is prized for its purplish metallic sheen when polished.","s":"He cut a smooth cabochon from the hypersthene to show off its mysterious silvery-purple flash.","p":"HY-per-stheen","o":"Greek","y":9,"bp":55,"nt":"Open","ps":"noun","t":["championship","mineralogy","gemology","minerals","ogreek"],"m":"hyperstene","sy":"hy.per.sthene"},{"w":"hyaluronic","d":"relating to a naturally occurring acid in the body that helps keep tissues and skin plump and well-hydrated.","s":"Many high-end moisturizers feature hyaluronic acid to give the face a bouncy, refreshed look.","p":"hy-uh-luh-RON-ik","o":"Scientific English","y":5,"bp":55,"nt":"Open","ps":"adjective","t":["championship","skincare","chemistry","body"],"m":"hyluronic","sy":"hy.a.lu.ron.ic"},{"w":"hyalography","d":"the specialized art and process of engraving delicate designs onto transparent, glassy surfaces","s":"He studied hyalography so he could carve beautiful, frosty portraits onto thick window panes.","p":"hy-uh-LOG-ruh-fee","o":"Greek","y":8,"bp":60,"nt":"Open","ps":"noun","t":["championship","glassmaking","art","painting","ogreek"],"m":"hyallography","sy":"hy.a.log.ra.phy"},{"w":"hydrophilicity","d":"The quality of having a strong attraction to water or being easily dissolved in it.","s":"The sponge's extreme hydrophilicity allowed it to soak up the spilled juice in mere seconds.","p":"hye-droh-fih-LIS-ih-tee","o":"Greek","y":7,"bp":50,"nt":"Open","ps":"noun","t":["championship","chemistry","water","ogreek"],"m":"hydrophillicity","sy":"hy.dro.phi.lic.i.ty"},{"w":"hyaloclastite","d":"a glassy rock formed when volcanic lava suddenly cools and shatters underwater","s":"The island is largely made of hyaloclastite from ancient underwater eruptions.","p":"hy-al-oh-KLAS-tight","o":"Greek","y":9,"bp":30,"nt":"Open","ps":"noun","t":["championship","geology","volcanoes","minerals","ogreek"],"m":"hyaloclastight","sy":"hy.a.lo.clas.tite"},{"w":"hypercatalectic","d":"Having an extra beat or sound at the very end of a metrical line.","s":"Shakespeare occasionally used a hypercatalectic line to give an actor an extra unstressed beat.","p":"hy-per-kat-uh-LEK-tik","o":"Greek","y":9,"bp":55,"nt":"Open","ps":"adjective","t":["championship","prosody","meter","ogreek"],"m":"hypercatelactic","sy":"hy.per.cat.a.lec.tic"},{"w":"hypotaxis","d":"The subordination of one clause to another in a sentence to show clear relationships between ideas.","s":"The author favored hypotaxis, linking multiple dependent clauses together to create long, complex sentences.","p":"hy-puh-TAK-sis","o":"Greek","y":8,"bp":45,"nt":"Open","ps":"noun","t":["championship","rhetoric","grammar","law","ogreek"],"m":"hypotaxes","sy":"hy.po.tax.is"},{"w":"hypermetropia","d":"A vision condition where objects that are far away look clear, but things up close are blurry.","s":"My grandfather wears his favorite reading glasses to correct his hypermetropia when looking at a book.","p":"hy-per-mih-TROH-pee-uh","o":"Greek","y":9,"bp":55,"nt":"Open","ps":"noun","t":["championship","medicine","anatomy","ogreek"],"m":"hypermatropia","sy":"hy.per.me.tro.pi.a"},{"w":"hypostatize","d":"to treat an abstract concept as if it were a real, physical thing","s":"It is a mistake to hypostatize justice as a living creature rather than a noble ideal we strive for.","p":"hy-POS-tuh-tyz","o":"Greek","y":9,"bp":50,"nt":"Open","ps":"verb","t":["championship","philosophy","concepts","ogreek"],"m":"hypostatisze","sy":"hy.pos.ta.tize"},{"w":"hypochondriasis","d":"A state of extreme worry that one has a serious illness, despite medical proof that they are healthy.","s":"Her hypochondriasis caused her to visit the doctor every time she had a tiny sniffle.","p":"HIGH-puh-kuhn-DRY-uh-sis","o":"Greek","y":8,"bp":30,"nt":"Open","ps":"noun","t":["championship","psychology","anxiety","body","disease","ogreek"],"m":"hypocondriasis","sy":"hy.po.chon.dri.a.sis"},{"w":"hyperarousal","d":"A state of being unusually tense, alert, and on edge due to anxiety or stress.","s":"The loud fireworks caused a state of hyperarousal in the rescued dog, making him unable to relax.","p":"HIGH-per-uh-ROW-zuhl","o":"Greek/English","y":8,"bp":30,"nt":"Open","ps":"noun","t":["championship","psychology","stress","emotions","ogreek"],"m":"hyperarousel","sy":"hy.per.a.rous.al"},{"w":"hypnopompic","d":"Relating to the groggy state of consciousness right as a person is waking up from sleep.","s":"He saw strange, fading shadows during the hypnopompic moments right before he fully woke up.","p":"HIP-nuh-PAHM-pik","o":"Greek","y":7,"bp":30,"nt":"Open","ps":"adjective","t":["championship","psychology","sleep","ogreek"],"m":"hypnopumpic","sy":"hyp.no.pom.pic"},{"w":"hyetograph","d":"a chart that displays the amount and intensity of rainfall over a specific period.","s":"After the heavy spring showers, the class studied the hyetograph to see which hour had the most downpour.","p":"hy-EE-tuh-graf","o":"Greek","y":8,"bp":46,"nt":"Open","ps":"noun","t":["championship","rain","charts","weather","ogreek"],"m":"hyatograph","sy":"hy.e.to.graph"},{"w":"hygrothermograph","d":"an instrument that continuously records both humidity levels and temperature on a turning cylinder.","s":"The museum uses a hygrothermograph to ensure the air stays perfectly cool and dry for the ancient paintings.","p":"hy-groh-THUR-muh-graf","o":"Greek","y":9,"bp":48,"nt":"Open","ps":"noun","t":["instruments","measurement","weather","championship","ogreek"],"m":"hygrothermagraph","sy":"hy.gro.ther.mo.graph"},{"w":"hymenopterous","d":"belonging to a large group of flying insects that includes busy bees, ants, and wasps.","s":"The bright spring garden is full of hymenopterous creatures buzzing happily around the colorful flowers.","p":"hy-muh-NOP-tur-us","o":"Greek","y":9,"bp":50,"nt":"Open","ps":"adjective","t":["championship","insects","biology","ogreek"],"m":"himenopterous","sy":"hy.men.op.ter.ous"},{"w":"hyphopodium","d":"a short branch on a fungal thread that helps it attach to a plant surface","s":"Using a strong microscope, she pointed to the tiny hyphopodium anchoring the fungus to the leaf.","p":"hy-fuh-POH-dee-um","o":"Greek via Modern Latin","y":8,"bp":55,"nt":"Open","ps":"noun","t":["championship","mycology","biology","botany","olatin","ogreek"],"m":"hiphopodium","sy":"hy.pho.po.di.um"},{"w":"hypervelocity","d":"an extremely fast speed, typically exceeding three thousand meters per second","s":"The asteroid impact was so powerful because the rock was traveling at hypervelocity through the vacuum of space.","p":"hy-per-vuh-LAHS-ih-tee","o":"Greek and Latin","y":7,"bp":45,"nt":"Open","ps":"noun","t":["championship","speed","physics","olatin","ogreek"],"m":"hipervelocity","sy":"hy.per.ve.loc.i.ty"},{"w":"hylozoism","d":"the ancient belief that all matter in the universe is alive to some degree","s":"Early thinkers who supported hylozoism thought that the moving stars and oceans were literally living beings.","p":"hy-luh-ZOH-iz-uhm","o":"Greek","y":9,"bp":50,"nt":"Open","ps":"noun","t":["philosophy","nature","ancient","championship","ogreek"],"m":"hilozoism","sy":"hy.lo.zo.ism"},{"w":"hyperthymesia","d":"An extremely rare ability to remember almost every single day and event of your own life in perfect detail.","s":"The woman with hyperthymesia could easily recall exactly what she had for lunch on a random Tuesday ten years ago.","p":"hy-per-thy-MEE-zhuh","o":"Greek","y":9,"bp":60,"nt":"Open","ps":"noun","t":["championship","memory","brain","time","ogreek"],"m":"hyperthimesia","sy":"hy.per.thy.me.si.a"},{"w":"hyperphantasia","d":"The ability to create mental images in your mind that are as incredibly vivid and colorful as real life.","s":"Endowed with hyperphantasia, the artist could design an entire glowing fantasy city in her mind before drawing a single line.","p":"hy-per-fan-TAY-zhuh","o":"Greek","y":9,"bp":55,"nt":"Open","ps":"noun","t":["championship","perception","imagination","colors","ogreek"],"m":"hyperfantasia","sy":"hy.per.phan.ta.si.a"},{"w":"hydroponics","d":"The method of growing plants in water filled with added nutrients instead of using soil.","s":"The futuristic greenhouse uses advanced hydroponics to grow huge heads of lettuce entirely in flowing water trays.","p":"hy-druh-PON-iks","o":"Greek","y":6,"bp":35,"nt":"Open","ps":"noun","t":["championship","agriculture","plants","botany","ogreek"],"m":"hydroponnics","sy":"hy.dro.pon.ics"},{"w":"hypotyposis","d":"Describing a scene so vividly that listeners feel they can see it before them.","s":"Her hypotyposis of the burning ship left the whole class silent.","p":"hy-poh-ty-POH-sis","o":"Greek","y":9,"bp":66,"nt":"Open","ps":"noun","t":["championship","rhetoric","ogreek"],"m":"hipotyposis","sy":"hy.po.ty.po.sis"},{"w":"hydraulis","d":"The organ of the ancient world, whose wind pressure was kept steady by water.","s":"A bronze model shows a hydraulis being played at the games.","p":"hy-DRAW-lis","o":"Greek","y":8,"bp":66,"nt":"Open","ps":"noun","t":["championship","organology","body","weather","music","ancient","ogreek"],"m":"hydralis","sy":"hy.drau.lis"},{"w":"hydrophane","d":"A chalky opal that turns clear and shows its fire once it has soaked up water.","s":"Dropped into a glass of water, the hydrophane grew as clear as ice.","p":"HY-druh-fayn","o":"Greek","y":9,"bp":64,"nt":"Open","ps":"noun","t":["championship","jewellery","minerals","ogreek"],"m":"hidrophane","sy":"hy.dro.phane"},{"w":"hyperosmia","d":"An unusually sharp sense of smell that notices what others cannot.","s":"Her hyperosmia let her name every spice in the cupboard from the doorway.","p":"hy-pur-OZ-mee-uh","o":"Greek","y":9,"bp":62,"nt":"Open","ps":"noun","t":["championship","perfumery","ogreek"],"m":"hiperosmia","sy":"hy.per.os.mi.a"},{"w":"hydraulicking","d":"Washing away banks of gravel with powerful jets of water to reach what lies beneath.","s":"Whole hillsides were stripped bare by hydraulicking.","p":"hy-DRAW-lik-ing","o":"Greek","y":9,"bp":64,"nt":"Open","ps":"noun","t":["championship","hydraulics","mining","economy","ogreek"],"m":"hydralicking","sy":"hy.drau.lick.ing"},{"w":"hysteresis","d":"The way a material lags behind, so that its state depends on what happened to it before.","s":"Iron shows hysteresis when the magnet is taken away again.","p":"his-tuh-REE-sis","o":"Greek","y":5,"bp":66,"nt":"Open","ps":"noun","t":["championship","electronics","physics","ogreek"],"m":"hysterisis","sy":"hys.ter.e.sis"},{"w":"hypabyssal","d":"Formed from molten rock that cooled just a little way below the surface.","s":"Thin hypabyssal sheets cut across the older beds.","p":"hy-puh-BIS-ul","o":"Greek","y":9,"bp":65,"nt":"Open","ps":"adjective","t":["championship","petrology","minerals","ogreek"],"m":"hypabysal","sy":"hyp.a.bys.sal"},{"w":"hypogean","d":"Living or growing beneath the surface of the earth.","s":"The hypogean fungus fruits entirely underground, so pigs must sniff it out.","p":"hy-puh-JEE-un","o":"Greek","y":8,"bp":63,"nt":"Open","ps":"adjective","t":["championship","speleology","ogreek"],"m":"hipogean","sy":"hy.po.ge.an"},{"w":"hyporheic","d":"Belonging to the wet gravel just beneath the bed of a stream.","s":"Insect larvae hide in the hyporheic gravel where the current cannot reach them.","p":"hy-poh-REE-ik","o":"Greek","y":8,"bp":65,"nt":"Open","ps":"adjective","t":["championship","hydrology","waterways","household","ogreek"],"m":"hyporeic","sy":"hy.po.rhe.ic"},{"w":"hyaenodont","d":"An extinct flesh-eating mammal with long shearing teeth, unrelated to today's hunters.","s":"The hyaenodont had a skull nearly as long as its body was tall.","p":"hy-EE-nuh-dont","o":"Greek","y":8,"bp":68,"nt":"Open","ps":"noun","t":["championship","palaeontology","body","animals","ecology","ogreek"],"m":"hyenodont","sy":"hy.ae.no.dont"},{"w":"hyetology","d":"The study of rainfall and how it is spread over the world.","s":"A short course in hyetology taught him why one hillside is always wetter.","p":"hy-uh-TOL-uh-jee","o":"Greek","y":8,"bp":66,"nt":"Open","ps":"noun","t":["championship","hydrology","weather","ogreek"],"m":"hyetollogy","sy":"hy.e.tol.o.gy"},{"w":"hypsodont","d":"Having tall-crowned teeth that keep on growing to survive a diet of gritty grass.","s":"Horses became hypsodont once the great grasslands spread.","p":"HIP-suh-dont","o":"Greek","y":8,"bp":66,"nt":"Open","ps":"adjective","t":["championship","palaeontology","body","botany","royalty","ogreek"],"m":"hipsodont","sy":"hyp.so.dont"},{"w":"hypogene","d":"Formed far below the surface by heat and fluids rising from within the earth.","s":"The hypogene ores were carried up by hot water from deep down.","p":"HY-puh-jeen","o":"Greek","y":9,"bp":64,"nt":"Open","ps":"adjective","t":["championship","petrology","ogreek"],"m":"hipogene","sy":"hy.po.gene"},{"w":"hypognathous","d":"Having jaws that point straight downward, as many beetles do.","s":"The grasshopper's hypognathous head lets it bite the leaf directly beneath it.","p":"hy-POG-nuh-thus","o":"Greek","y":9,"bp":67,"nt":"Open","ps":"adjective","t":["championship","entomology","insects","ogreek"],"m":"hypognathus","sy":"hy.pog.na.thous"},{"w":"hypnozoite","d":"A sleeping form of the malaria parasite that hides in the liver for months.","s":"A single hypnozoite can wake up long after the traveller has come home.","p":"hip-nuh-ZOH-ite","o":"Greek","y":9,"bp":69,"nt":"Open","ps":"noun","t":["championship","parasitology","body","time","ogreek"],"m":"hipnozoite","sy":"hyp.no.zo.ite"},{"w":"hyperhidrosis","d":"Sweating far more heavily than the body needs for cooling.","s":"His hyperhidrosis made writing in ink an adventure.","p":"hy-per-hy-DROH-sis","o":"Greek","y":7,"bp":69,"nt":"Open","ps":"noun","t":["championship","dermatology","ogreek"],"m":"hyperhydrosis","sy":"hy.per.hi.dro.sis"},{"w":"hypertrichosis","d":"An excessive growth of hair over parts of the body.","s":"The medicine's odd side effect was a mild hypertrichosis along both arms.","p":"hy-per-trih-KOH-sis","o":"Greek","y":8,"bp":69,"nt":"Open","ps":"noun","t":["championship","dermatology","ogreek"],"m":"hypertricosis","sy":"hy.per.tri.cho.sis"},{"w":"hyperacusis","d":"A condition in which ordinary sounds seem painfully loud.","s":"Her hyperacusis made the school bell sound like a thunderclap.","p":"hy-per-uh-KYOO-sis","o":"Greek","y":7,"bp":60,"nt":"Open","ps":"noun","t":["championship","psychology","ogreek"],"m":"hyperacousis","sy":"hy.per.a.cu.sis"},{"w":"hypnopaedia","d":"Learning while asleep by listening to recordings.","s":"The story imagines children taught by hypnopaedia as they slumber.","p":"hip-noh-PEE-dee-uh","o":"Greek","y":9,"bp":62,"nt":"Open","ps":"noun","t":["championship","education","ogreek"],"m":"hipnopaedia","sy":"hyp.no.pae.di.a"},{"w":"hylomorphic","d":"Relating to the idea that each thing is matter joined to a form.","s":"The hylomorphic theory explains a statue as bronze shaped into a figure.","p":"hy-loh-MOR-fik","o":"Greek","y":8,"bp":64,"nt":"Open","ps":"adjective","t":["championship","philosophy","ogreek"],"m":"hilomorphic","sy":"hy.lo.mor.phic"},{"w":"hylozoic","d":"Relating to the belief that all matter has some kind of life in it.","s":"Early Greek thinkers held hylozoic views of the world.","p":"hy-luh-ZOH-ik","o":"Greek","y":9,"bp":64,"nt":"Open","ps":"adjective","t":["championship","philosophy","logic","ogreek"],"m":"hylozoec","sy":"hy.lo.zo.ic"},{"w":"hypothec","d":"A lender's right over property that stays in the borrower's hands.","s":"Under Scots law the landlord had a hypothec over the crop.","p":"hy-POTH-ik","o":"Greek","y":7,"bp":66,"nt":"Open","ps":"noun","t":["championship","jurisprudence","ogreek"],"m":"hipothec","sy":"hy.poth.ec"},{"w":"hypergamy","d":"Marriage into a group of higher standing than one's own.","s":"The study of hypergamy filled a whole chapter of the book.","p":"hy-PUR-guh-mee","o":"Greek","y":7,"bp":64,"nt":"Open","ps":"noun","t":["championship","anthropology","kinship","ogreek"],"m":"hypergammy","sy":"hy.per.ga.my"},{"w":"hyperpyron","d":"A gold coin of the later Byzantine empire.","s":"Each hyperpyron in the purse bore an emperor's portrait.","p":"hy-PER-pih-ron","o":"Greek","y":9,"bp":70,"nt":"Open","ps":"noun","t":["championship","numismatics","economy","ogreek"],"m":"hiperpyron","sy":"hy.per.py.ron"}]`};
